_system_dark_cache = None
_system_dark_cache_time = 0
_theme_dark_override = None

def set_theme_dark_override(dark):
    global _theme_dark_override
    _theme_dark_override = None if dark is None else bool(dark)

def get_theme_dark_override():
    return _theme_dark_override

def is_system_dark():
    if _theme_dark_override is not None:
        return _theme_dark_override
    return native_system_dark()

def native_system_dark():
    global _system_dark_cache, _system_dark_cache_time
    now = time.time()
    if _system_dark_cache is not None and now - _system_dark_cache_time < 2:
        return _system_dark_cache
    result = False
    if sys.platform == "win32":
        try:
            import winreg
            key = winreg.OpenKey(winreg.HKEY_CURRENT_USER,
                                 r"Software\Microsoft\Windows\CurrentVersion\Themes\Personalize")
            value, _ = winreg.QueryValueEx(key, "AppsUseLightTheme")
            winreg.CloseKey(key)
            result = value == 0
        except Exception:
            result = False
    elif sys.platform == "darwin":
        try:
            p = subprocess.run(
                ["defaults", "read", "-g", "AppleInterfaceStyle"],
                capture_output=True, text=True, timeout=2
            )
            result = "Dark" in p.stdout
        except Exception:
            result = False
    else:
        try:
            p = subprocess.run(
                ["gsettings", "get", "org.gnome.desktop.interface", "color-scheme"],
                capture_output=True, text=True, timeout=2
            )
            result = "dark" in p.stdout.lower()
        except Exception:
            result = False
    _system_dark_cache = result
    _system_dark_cache_time = now
    return result

_TIME_SYNC_LOCK = threading.Lock()
_TIME_SYNC_OFFSET = 0.0
_TIME_SYNC_BUSY = False
_TIME_SYNC_INFO = {"ok": False, "at": 0.0, "source": "", "offset": 0.0, "error": "", "rtt": 0.0}


def app_now():
    return datetime.now() + timedelta(seconds=_TIME_SYNC_OFFSET)


def time_sync_offset():
    return _TIME_SYNC_OFFSET


def time_sync_status():
    with _TIME_SYNC_LOCK:
        return dict(_TIME_SYNC_INFO)


def _time_epoch_taobao(raw):
    return float(json.loads(raw)["data"]["t"]) / 1000.0


def _time_epoch_suning(raw):
    return float(json.loads(raw)["currentTime"]) / 1000.0


def _time_epoch_qq(raw):
    match = re.search(r'"t"\s*:\s*(\d+)', raw)
    return float(match.group(1)) if match else None


def _time_epoch_date(raw):
    return None


_TIME_ENDPOINTS = (
    ("苏宁", "https://f.m.suning.com/api/ct.do", _time_epoch_suning),
    ("腾讯", "https://vv.video.qq.com/checktime?otype=json", _time_epoch_qq),
    ("百度", "https://www.baidu.com", _time_epoch_date),
    ("淘宝", "https://api.m.taobao.com/rest/api3.do?api=mtop.common.getTimestamp", _time_epoch_taobao),
)


def _time_sync_worker():
    global _TIME_SYNC_OFFSET, _TIME_SYNC_BUSY
    best = None
    last_error = ""
    for name, url, parser in _TIME_ENDPOINTS:
        started = time.time()
        try:
            request = urllib.request.Request(url, headers={"User-Agent": "Mozilla/5.0"})
            with urllib.request.urlopen(request, timeout=4) as response:
                raw = response.read(8192).decode("utf-8", "ignore")
                date_header = response.headers.get("Date")
            finished = time.time()
            epoch = parser(raw)
            if epoch is None and date_header:
                try:
                    from email.utils import parsedate_to_datetime
                    epoch = parsedate_to_datetime(date_header).timestamp()
                except Exception:
                    epoch = None
        except Exception as exc:
            last_error = str(exc)
            continue
        if epoch is None:
            continue
        rtt = max(0.0, finished - started)
        offset = epoch - (started + rtt / 2.0)
        if best is None or rtt < best[1]:
            best = (offset, rtt, name)
    with _TIME_SYNC_LOCK:
        if best is not None and abs(best[0]) < 86400:
            _TIME_SYNC_OFFSET = best[0]
            _TIME_SYNC_INFO.update({"ok": True, "at": time.time() + best[0], "source": best[2],
                                    "offset": best[0], "error": "", "rtt": best[1]})
            log_message("网络校时成功：偏差 %+.2f 秒（%s）" % (best[0], best[2]), "INFO")
        else:
            _TIME_SYNC_INFO.update({"ok": False, "error": last_error or "时间接口不可用"})
            log_message("网络校时失败：%s" % (last_error or "时间接口不可用"), "WARNING")
        _TIME_SYNC_BUSY = False


def sync_network_time_async():
    global _TIME_SYNC_BUSY
    with _TIME_SYNC_LOCK:
        if _TIME_SYNC_BUSY:
            return False
        _TIME_SYNC_BUSY = True
    threading.Thread(target=_time_sync_worker, daemon=True).start()
    return True


def time_sync_status_text():
    info = time_sync_status()
    if info.get("ok"):
        offset = float(info.get("offset") or 0.0)
        sign = "+" if offset >= 0 else "-"
        return "已校时 %s%.2f 秒 · %s" % (sign, abs(offset), info.get("source") or "网络")
    if info.get("error"):
        return "校时失败，使用本机时间"
    return "尚未校时"


_AUTO_DARK_RESOLVER = None


def set_auto_dark_resolver(resolver):
    global _AUTO_DARK_RESOLVER
    _AUTO_DARK_RESOLVER = resolver


def clock_is_dark_now():
    hour = datetime.now().hour
    return hour >= 20 or hour < 8


def auto_theme_is_dark():
    if _AUTO_DARK_RESOLVER is not None:
        try:
            return bool(_AUTO_DARK_RESOLVER())
        except Exception:
            pass
    return clock_is_dark_now()


def widget_is_dark(content):
    mode = getattr(content, "theme_mode", "system")
    if mode == "dark":
        return True
    if mode == "light":
        return False
    if mode == "auto":
        return auto_theme_is_dark()
    return is_system_dark()

def clamp_rect_into_screens(x, y, w, h):
    try:
        screens = QGuiApplication.screens()
    except Exception:
        return int(x), int(y)
    if not screens:
        return int(x), int(y)
    w = max(1, int(w))
    h = max(1, int(h))
    best, best_area = None, -1
    for s in screens:
        g = s.availableGeometry()
        ox = max(0, min(x + w, g.right() + 1) - max(x, g.left()))
        oy = max(0, min(y + h, g.bottom() + 1) - max(y, g.top()))
        if ox * oy > best_area:
            best, best_area = g, ox * oy
    if best is None:
        c = QPoint(x + w // 2, y + h // 2)
        best = min(screens, key=lambda s: (s.availableGeometry().center() - c).manhattanLength()).availableGeometry()
    keep_w = (w + 1) // 2
    keep_h = (h + 1) // 2
    nx = max(best.left() - (w - keep_w), min(x, best.right() + 1 - keep_w))
    ny = max(best.top() - (h - keep_h), min(y, best.bottom() + 1 - keep_h))
    return int(nx), int(ny)


def clamp_window_into_screens(widget):
    try:
        if widget is None or not widget.isWindow():
            return
        if widget.isFullScreen() or getattr(widget, 'is_fullscreen', False):
            return
        cx, cy = clamp_rect_into_screens(widget.x(), widget.y(), widget.width(), widget.height())
        if (cx, cy) != (widget.x(), widget.y()):
            widget.move(cx, cy)
    except Exception:
        pass


class WindowBoundsGuard(QObject):
    def __init__(self, app):
        super().__init__(app)
        self.app = app
        self._busy = set()
        app.installEventFilter(self)

    def _watched(self, obj):
        if not isinstance(obj, QWidget) or not obj.isWindow():
            return False
        if obj.windowType() in (Qt.WindowType.Popup, Qt.WindowType.ToolTip, Qt.WindowType.SplashScreen):
            return False
        return True

    def eventFilter(self, obj, event):
        et = event.type()
        if et != QEvent.Type.Show and et != QEvent.Type.Move and et != QEvent.Type.Resize:
            return False
        if obj in self._busy or not self._watched(obj):
            return False
        self._busy.add(obj)
        try:
            clamp_window_into_screens(obj)
        finally:
            self._busy.discard(obj)
        return False


class ScreenReclampHelper(QObject):
    def __init__(self, widget, callback):
        super().__init__(widget)
        self.widget = widget
        self.callback = callback
        self.connected_screen = None
        self.timer = QTimer(self)
        self.timer.setSingleShot(True)
        self.timer.setInterval(200)
        self.timer.timeout.connect(self.reclamp)
        widget.installEventFilter(self)

    def eventFilter(self, obj, event):
        if event.type() == QEvent.Type.Show:
            self.connect_window()
        return False

    def connect_window(self):
        wh = self.widget.windowHandle()
        if wh is None:
            return
        try:
            wh.screenChanged.disconnect(self._on_screen_changed)
        except Exception:
            pass
        wh.screenChanged.connect(self._on_screen_changed)
        self._on_screen_changed()

    def _on_screen_changed(self, *args):
        try:
            scr = self.widget.screen()
        except Exception:
            scr = None
        if self.connected_screen is not scr:
            if self.connected_screen is not None:
                try:
                    self.connected_screen.geometryChanged.disconnect(self._schedule)
                except Exception:
                    pass
            self.connected_screen = scr
            if scr is not None:
                scr.geometryChanged.connect(self._schedule)
        self._schedule()

    def _schedule(self, *args):
        self.timer.start()

    def reclamp(self):
        try:
            self.callback()
        except Exception:
            pass

def get_system_theme(force_dark=None):
    dark = is_system_dark() if force_dark is None else force_dark
    if dark:
        return Theme("system_dark", is_dark=True,
                     bg_color="#1e1e2e", frame_bg="#2a2a3a",
                     accent_color="#89b4fa", text_color="#cdd6f4",
                     border_color="#45475a", font_family="Microsoft YaHei",
                     font_size=9, window_round_radius=12)
    else:
        return Theme("system_light", is_dark=False,
                     bg_color="#f5f5f5", frame_bg="#ffffff",
                     accent_color="#3498db", text_color="#2c3e50",
                     border_color="#d1d8e0", font_family="Microsoft YaHei",
                     font_size=9, window_round_radius=12)

