def apply_combo_popup_theme(combo, colors):
    try:
        view = combo.view()
    except Exception:
        return
    if view is None:
        return
    view.setStyleSheet(
        f"QListView {{ background-color: {colors['input_bg']}; color: {colors['text_color']};"
        f" border: 1px solid {colors['border_color']}; outline: none; padding: 2px; }}"
        f" QListView::item {{ padding: 3px 6px; border-radius: 3px; min-height: 20px; }}"
        f" QListView::item:hover {{ background-color: {colors['alternate_bg']}; color: {colors['text_color']}; }}"
        f" QListView::item:selected {{ background-color: {colors['accent']}; color: {colors['btn_text']}; }}"
    )
    container = view.window()
    if container is not None and container is not view:
        container.setAttribute(Qt.WidgetAttribute.WA_TranslucentBackground, False)
        container.setStyleSheet(
            f"QFrame {{ background-color: {colors['input_bg']};"
            f" border: 1px solid {colors['border_color']}; }}"
        )


def apply_modern_window_effect(hwnd, effect_type="acrylic", is_dark=False, enable=True):
    if sys.platform != "win32":
        return False
    try:
        from ctypes import windll, c_int, byref, sizeof
        dwmapi = windll.dwmapi
        if not enable:
            backdrop_value = c_int(1)
            dwmapi.DwmSetWindowAttribute(hwnd, 38, byref(backdrop_value), sizeof(backdrop_value))
            margins = (c_int * 4)(0, 0, 0, 0)
            dwmapi.DwmExtendFrameIntoClientArea(hwnd, byref(margins))
            return True
        dark_value = c_int(1 if is_dark else 0)
        dwmapi.DwmSetWindowAttribute(hwnd, 20, byref(dark_value), sizeof(dark_value))
        backdrop_type = 3 if effect_type == "acrylic" else (2 if effect_type == "mica" else 4)
        backdrop_value = c_int(backdrop_type)
        dwmapi.DwmSetWindowAttribute(hwnd, 38, byref(backdrop_value), sizeof(backdrop_value))
        corner_pref = c_int(2)
        dwmapi.DwmSetWindowAttribute(hwnd, 33, byref(corner_pref), sizeof(corner_pref))
        margins = (c_int * 4)(-1, -1, -1, -1)
        dwmapi.DwmExtendFrameIntoClientArea(hwnd, byref(margins))
        return True
    except Exception as e:
        debug_print(f"毛玻璃特效失败: {e}")
        return False

def enable_accent_blur(hwnd, tint=0x8CF8F4F2):
    if sys.platform != "win32":
        return False
    try:
        from ctypes import windll, c_int, c_uint, c_void_p, c_size_t, Structure, byref, sizeof, cast
        class ACCENT_POLICY(Structure):
            _fields_ = [("AccentState", c_int),
                        ("AccentFlags", c_int),
                        ("GradientColor", c_uint),
                        ("AnimationId", c_int)]
        class WINCOMPATTRDATA(Structure):
            _fields_ = [("Attribute", c_int),
                        ("Data", c_void_p),
                        ("SizeOfData", c_size_t)]
        policy = ACCENT_POLICY()
        policy.AccentState = 3
        policy.AccentFlags = 2
        policy.GradientColor = tint
        data = WINCOMPATTRDATA()
        data.Attribute = 19
        data.Data = cast(byref(policy), c_void_p)
        data.SizeOfData = sizeof(policy)
        return bool(windll.user32.SetWindowCompositionAttribute(int(hwnd), byref(data)))
    except Exception as e:
        debug_print(f"ACCENT 背景模糊失败: {e}")
        return False

def debug_print(*args, **kwargs):
    out = sys.stderr or sys.stdout
    if out is None:
        return
    try:
        print(*args, file=out, **kwargs)
        out.flush()
    except (OSError, ValueError):
        try:
            out.flush()
        except Exception:
            pass

def global_excepthook(exc_type, exc_value, exc_traceback):
    tb_text = "".join(traceback.format_exception(exc_type, exc_value, exc_traceback))
    with open("crash.log", "w", encoding="utf-8") as f:
        f.write(tb_text)
    traceback.print_exception(exc_type, exc_value, exc_traceback)
    debug_print("全局异常已捕获，详情请查看 crash.log")
    try:
        show_crash_dialog(tb_text)
    except Exception:
        pass

def show_crash_dialog(tb_text):
    app = QApplication.instance()
    if app is None:
        return
    box = QMessageBox()
    box.setWindowFlag(Qt.WindowType.WindowStaysOnTopHint, True)
    box.setIcon(QMessageBox.Icon.Critical)
    box.setWindowTitle("程序发生严重错误")
    box.setText("程序检测到严重错误并已停止运行。\n请复制下方错误信息反馈给开发者后重新启动。")
    box.setInformativeText(tb_text[-3000:])
    box.setTextFormat(Qt.TextFormat.PlainText)
    copy_btn = box.addButton("复制错误信息", QMessageBox.ButtonRole.ActionRole)
    ok_btn = box.addButton("确定", QMessageBox.ButtonRole.AcceptRole)
    box.exec()
    if box.clickedButton() is copy_btn:
        app.clipboard().setText(tb_text)

sys.excepthook = global_excepthook

