_PERM_BY_NAME = {flag.name: flag for flag, _label in _PERM_LABELS}

BASELINE_RISK_MAX = 2
BASELINE_MAX_ITEMS = 12

BASELINE_ALLOWED = frozenset(
    flag for flag, spec in _PERM_SPECS.items() if spec["risk"] <= BASELINE_RISK_MAX)

FALLBACK_ALLOWED = frozenset(
    flag for flag, spec in _PERM_SPECS.items() if spec["fallback"])


def permission_flag_from(value):
    if isinstance(value, PluginPermission):
        flag = value
    elif isinstance(value, int):
        flag = PluginPermission(value)
    elif isinstance(value, str):
        text = value.strip()
        if text.upper().startswith("PLUGINPERMISSION."):
            text = text.split(".", 1)[1]
        flag = _PERM_BY_NAME.get(text.upper())
        if flag is None:
            raise ValueError(f"未知权限位: {value}")
    else:
        raise ValueError(f"未知权限位: {value}")
    if int(flag) == 0 or flag not in _PERM_SPECS:
        raise ValueError(f"未知权限位: {value}")
    return flag


def clean_permission_text(value, limit):
    text = re.sub(r"\s+", " ", str(value or "")).strip()
    if len(text) > limit:
        return text[:limit - 1] + "…"
    return text


def _perm_spec_entry(flag, source, feature="", title="", reason="", fallback=False):
    spec = _PERM_SPECS[flag]
    return {
        "flag": int(flag),
        "perm": flag.name,
        "feature": clean_permission_text(feature, 24),
        "title": clean_permission_text(title, 40),
        "reason": clean_permission_text(reason, 240),
        "fallback": bool(fallback) and flag in FALLBACK_ALLOWED,
        "risk": spec["risk"],
        "scope": perm_scope(flag),
        "source": source,
    }


def perm_feature(flag, spec):
    text = (spec or {}).get("feature") or ""
    if text and text != _PERM_SPECS[flag]["name"]:
        return text
    return perm_name(flag)


def perm_title(flag, spec):
    text = (spec or {}).get("title") or ""
    if text and text != tr("perm_default_title").format(name=_PERM_SPECS[flag]["name"]):
        return text
    return perm_text("perm_default_title", name=perm_name(flag))


def parse_permission_manifest(manifest, fallback_perms=PluginPermission.NONE):
    manifest = manifest if isinstance(manifest, dict) else {}
    warnings = []
    declared = PluginPermission(fallback_perms)
    legacy = False
    specs = {}
    baseline = PluginPermission.NONE
    p2 = manifest.get("permissions_v2")
    mp = manifest.get("permissions")
    if isinstance(mp, int) and mp >= 0:
        declared = PluginPermission(mp)
    if isinstance(p2, dict):
        legacy = False
        raw_baseline = p2.get("baseline") or []
        if isinstance(raw_baseline, list):
            for raw in raw_baseline:
                try:
                    flag = permission_flag_from(raw)
                except ValueError:
                    warnings.append(f"baseline_unknown:{raw}")
                    continue
                if flag not in BASELINE_ALLOWED:
                    warnings.append(f"baseline_not_allowed:{flag.name}")
                    specs[int(flag)] = _perm_spec_entry(
                        flag, "baseline_demoted",
                        reason=tr("perm_reason_baseline_demoted"),
                        fallback=flag in FALLBACK_ALLOWED)
                    continue
                baseline |= flag
        ondemand_raw = p2.get("on_demand") or []
        if not isinstance(ondemand_raw, list):
            ondemand_raw = []
        if len(ondemand_raw) > 24:
            warnings.append("on_demand_truncated")
            ondemand_raw = ondemand_raw[:24]
        for item in ondemand_raw:
            if not isinstance(item, dict):
                warnings.append("on_demand_invalid")
                continue
            try:
                flag = permission_flag_from(item.get("perm"))
            except ValueError:
                warnings.append(f"on_demand_unknown:{item.get('perm')}")
                continue
            if int(baseline) & int(flag):
                warnings.append(f"on_demand_duplicated:{flag.name}")
                continue
            reason = item.get("reason")
            if not isinstance(reason, str) or not reason.strip():
                warnings.append(f"missing_reason:{flag.name}")
                reason = ""
            specs[int(flag)] = _perm_spec_entry(
                flag, "manifest_v2", item.get("feature"), item.get("title"),
                reason, bool(item.get("fallback", False)))
    else:
        baseline = PluginPermission(int(declared) & sum(
            int(f) for f in BASELINE_ALLOWED))
        for flag in _PERM_SPECS:
            if int(declared) & int(flag) and not int(baseline) & int(flag):
                specs[int(flag)] = _perm_spec_entry(
                    flag, "legacy",
                    reason=tr("perm_reason_legacy_missing"),
                    fallback=flag in FALLBACK_ALLOWED)
                legacy = True
    for flag in _PERM_SPECS:
        if int(baseline) & int(flag) and int(flag) not in specs:
            specs[int(flag)] = _perm_spec_entry(
                flag, "baseline", fallback=flag in FALLBACK_ALLOWED)
    baseline_flags = [flag for flag in _PERM_SPECS if int(baseline) & int(flag)]
    if len(baseline_flags) > BASELINE_MAX_ITEMS:
        removed = sorted(baseline_flags,
                         key=lambda f: -_PERM_SPECS[f]["risk"])[:len(baseline_flags) - BASELINE_MAX_ITEMS]
        for flag in removed:
            baseline_flags.remove(flag)
            baseline &= ~flag
            specs[int(flag)] = _perm_spec_entry(
                flag, "baseline_truncated",
                reason=tr("perm_reason_baseline_truncated"),
                fallback=flag in FALLBACK_ALLOWED)
        warnings.append("baseline_truncated:" + ",".join(f.name for f in removed) +
                        f":exceeds_limit_{BASELINE_MAX_ITEMS}")
    requested = PluginPermission(int(baseline) | sum(
        int(f) for f in _PERM_SPECS if int(f) in specs))
    return {
        "baseline": PluginPermission(int(baseline)),
        "requested": requested,
        "specs": specs,
        "warnings": warnings,
        "legacy": legacy,
        "declared": PluginPermission(int(requested)),
    }


def plugin_declared_permissions(plugin):
    try:
        return PluginPermission(int(getattr(plugin, "requested_permissions", 0) or 0))
    except Exception:
        return PluginPermission.NONE


def permission_declared(plugin, flag):
    return bool(plugin_declared_permissions(plugin) & flag)


def plugin_permission_names(perms):
    if not perms:
        return []
    return [perm_label(flag) for flag, _label in _PERM_LABELS if perms & flag]


def plugin_risk_text(level):
    if level <= 0:
        return "🟢 安全"
    if level == 1:
        return "🟡 低风险"
    if level == 2:
        return "🟠 中风险"
    return "🔴 高风险"


