_REASON_CODES = (
    ("应用内部配置文件受保护", "zone.protected_file"),
    ("禁止改写或删除插件程序文件", "zone.plugin_source"),
    ("禁止改写插件程序文件", "zone.plugin_source"),
    ("无读取插件源码权限", "zone.plugin_source"),
    ("无系统信息权限", "zone.system"),
    ("无开机启动项权限", "zone.startup"),
    ("已设置为拒绝并记住", "perm.remembered_deny"),
    ("禁止导入危险模块", "hard.blocked_module"),
    ("禁止插件干预安全钩子", "hard.security_hook"),
    ("无改写控件类权限", "seal.widget_class"),
    ("插件处于禁用状态", "hard.disabled"),
    ("无写入文件权限", "perm.not_granted"),
    ("无读取文件权限", "perm.not_granted"),
    ("已设置为拒绝并记住", "perm.remembered_deny"),
)


def decision_meta(code):
    return _DECISION_TABLE.get(code, ("L2", "grant", True, True, "security_center.permissions"))


def reason_decision_code(reason):
    text = str(reason or "")
    for prefix, code in _REASON_CODES:
        if text.startswith(prefix):
            return code
    return "perm.not_granted"


def make_decision(code, ok=None, perm=None, capability="", target="", scope=None,
                  origin="api", operation="", plugin="", message="", **extra):
    layer, denied_by, retryable, unlockable, unlock_action = decision_meta(code)
    if ok is None:
        ok = code.startswith("ok.")
    data = {
        "ok": bool(ok),
        "code": code,
        "layer": layer,
        "denied_by": denied_by,
        "retryable": retryable,
        "unlockable": unlockable,
        "unlock_action": unlock_action,
        "permission": getattr(perm, "name", "") if perm is not None else str(perm or ""),
        "permission_bit": int(perm) if perm is not None else 0,
        "capability": str(capability or ""),
        "target": str(target or "")[:120],
        "scope": scope if isinstance(scope, dict) else {"kind": "none", "value": "", "zone": ""},
        "origin": str(origin or "api"),
        "operation": str(operation or ""),
        "plugin": str(plugin or ""),
        "reason": str(message or ""),
        "retry_after_ms": 0,
    }
    for key, value in extra.items():
        if key in data:
            data[key] = value
        else:
            data[key] = value
    return data


class _DenialFields:
    code = "perm.not_granted"
    permission = ""
    permission_bit = 0
    capability = ""
    scope = None
    denied_by = "grant"
    layer = "L2"
    retryable = True
    unlockable = True
    unlock_action = ""
    retry_after_ms = 0
    origin = "api"
    plugin = ""
    operation = ""
    target = ""
    details = None

    def _init_denial(self, message, code, permission="", capability="", scope=None,
                     origin="api", plugin="", operation="", target="", **extra):
        layer, denied_by, retryable, unlockable, unlock_action = decision_meta(code)
        self.code = code
        self.layer = layer
        self.denied_by = denied_by
        self.retryable = retryable
        self.unlockable = unlockable
        self.unlock_action = unlock_action
        self.permission = str(permission or "")
        self.permission_bit = int(_PERM_BY_NAME[self.permission]) if self.permission in _PERM_BY_NAME else 0
        self.capability = str(capability or "")
        self.scope = scope if isinstance(scope, dict) else {"kind": "none", "value": "", "zone": ""}
        self.origin = str(origin or "api")
        self.plugin = str(plugin or "")
        self.operation = str(operation or "")
        self.target = str(target or "")[:120]
        self.message = str(message or "")
        self.details = dict(extra)
        self.retry_after_ms = int(extra.get("retry_after_ms", 0) or 0)

    def to_dict(self):
        data = {
            "type": type(self).__name__,
            "code": self.code,
            "permission": self.permission,
            "permission_bit": self.permission_bit,
            "capability": self.capability,
            "scope": dict(self.scope or {}),
            "denied_by": self.denied_by,
            "layer": self.layer,
            "retryable": self.retryable,
            "unlockable": self.unlockable,
            "unlock_action": self.unlock_action,
            "retry_after_ms": self.retry_after_ms,
            "origin": self.origin,
            "plugin": self.plugin,
            "operation": self.operation,
            "target": self.target,
            "message": self.message,
            "details": dict(self.details or {}),
        }
        return data


class PluginPermissionDenied(_DenialFields, PermissionError):

    def __init__(self, message, code="perm.not_granted", permission="", capability="",
                 scope=None, origin="api", plugin="", operation="", target="", **extra):
        PermissionError.__init__(self, message)
        self._init_denial(message, code, permission, capability, scope,
                          origin, plugin, operation, target, **extra)


class PluginHardBlockDenied(_DenialFields, ImportError):

    def __init__(self, message, code="hard.blocked_module", permission="", capability="",
                 scope=None, origin="import", plugin="", operation="", target="", **extra):
        ImportError.__init__(self, message)
        self._init_denial(message, code, permission, capability, scope,
                          origin, plugin, operation, target, **extra)


def decision_error(decision, message=None, origin=None):
    data = decision if isinstance(decision, dict) else {}
    text = message or data.get("reason") or tr("perm_msg_denied_remember")
    return PluginPermissionDenied(
        text,
        code=data.get("code", "perm.not_granted"),
        permission=data.get("permission", ""),
        capability=data.get("capability", ""),
        scope=data.get("scope"),
        origin=origin or data.get("origin", "api"),
        plugin=data.get("plugin", ""),
        operation=data.get("operation", ""),
        target=data.get("target", ""),
        retry_after_ms=data.get("retry_after_ms", 0))


class PermissionResult:

    def __init__(self, data=None, denial=None):
        self._data = dict(data or {})
        self._denial = denial

    @property
    def ok(self):
        return bool(self._data.get("ok"))

    @property
    def level(self):
        return str(self._data.get("level") or "none")

    @property
    def code(self):
        return str(self._data.get("code") or "")

    @property
    def denial(self):
        return self._denial

    @property
    def retryable(self):
        return bool(self._data.get("retryable", False))

    @property
    def unlockable(self):
        return bool(self._data.get("unlockable", False))

    @property
    def retry_after_ms(self):
        return int(self._data.get("retry_after_ms", 0) or 0)

    def get(self, key, default=None):
        return self._data.get(key, default)

    def keys(self):
        return self._data.keys()

    def items(self):
        return self._data.items()

    def to_dict(self):
        data = dict(self._data)
        if self._denial is not None:
            data["denial"] = self._denial
        return data

    def __getitem__(self, key):
        return self._data[key]

    def __contains__(self, key):
        return key in self._data

    def __bool__(self):
        return self.ok

    def __eq__(self, other):
        if isinstance(other, PermissionResult):
            return self._data == other._data
        if isinstance(other, bool):
            return self.ok == other
        if other is None:
            return False
        return NotImplemented

    __hash__ = None

    def __repr__(self):
        return f"PermissionResult({self._data!r})"


_PLUGIN_DIR_GUARD = ""
_AUDIT_MANAGER = None
_AUDIT_REENTRY = threading.local()


def _set_plugin_dir_guard(path):
    global _PLUGIN_DIR_GUARD
    _PLUGIN_DIR_GUARD = str(path or "")


def _set_audit_manager(manager):
    global _AUDIT_MANAGER
    _AUDIT_MANAGER = manager


def _caller_is_plugin_frame(start=2, depth=1):
    base = _PLUGIN_DIR_GUARD
    if not base:
        return False
    try:
        frame = sys._getframe(start)
    except ValueError:
        return False
    for _ in range(depth):
        if frame is None:
            return False
        filename = getattr(frame.f_code, "co_filename", "") or ""
        if filename and (filename == base or filename.startswith(base + os.sep)):
            return True
        frame = frame.f_back
    return False


def _manager_hard_denial(target, message, code="hard.manager_access"):
    return PluginPermissionDenied(
        message, code=code, capability="manager.access", origin="api",
        operation="manager.access", target=str(target))


def _audit_control_denial(target):
    return PluginPermissionDenied(
        "插件不可干预审计与安全控制", code="hard.audit_control",
        capability="audit.control", origin="api", operation="audit.control",
        target=str(target))


_INTERPRETER_GUARD_INSTALLED = False


def _install_interpreter_guards():
    global _INTERPRETER_GUARD_INSTALLED
    if _INTERPRETER_GUARD_INSTALLED:
        return
    _INTERPRETER_GUARD_INSTALLED = True
    original_addaudithook = sys.addaudithook
    original_settrace = sys.settrace
    original_setprofile = sys.setprofile

    def guarded_addaudithook(hook):
        if _caller_is_plugin_frame(2, 2):
            raise PluginPermissionDenied(
                "插件不可注册审计钩子", code="hard.security_hook",
                capability="audit.hook", origin="api",
                operation="sys.addaudithook", target="addaudithook")
        return original_addaudithook(hook)

    def guarded_settrace(*args, **kwargs):
        if _caller_is_plugin_frame(2, 2):
            raise PluginPermissionDenied(
                "插件不可设置调试跟踪", code="hard.security_hook",
                capability="debug.trace", origin="api",
                operation="sys.settrace", target="settrace")
        return original_settrace(*args, **kwargs)

    def guarded_setprofile(*args, **kwargs):
        if _caller_is_plugin_frame(2, 2):
            raise PluginPermissionDenied(
                "插件不可设置性能跟踪", code="hard.security_hook",
                capability="debug.profile", origin="api",
                operation="sys.setprofile", target="setprofile")
        return original_setprofile(*args, **kwargs)

    sys.addaudithook = guarded_addaudithook
    sys.settrace = guarded_settrace
    sys.setprofile = guarded_setprofile


class _GuardedAuditLocal(threading.local):

    def __setattr__(self, name, value):
        if name in ("active", "autostart_token", "internal") and _caller_is_plugin_frame(2, 1):
            raise _audit_control_denial(name)
        self.__dict__[name] = value


class _PluginManagerFacade:

    __slots__ = ("_startup_dirs_cache",)

    def __init__(self, manager):
        dirs = []
        if manager is not None:
            try:
                dirs = list(manager._startup_dirs() or ())
            except Exception:
                dirs = []
        object.__setattr__(self, "_startup_dirs_cache", tuple(dirs))

    def _startup_dirs(self):
        return list(object.__getattribute__(self, "_startup_dirs_cache"))

    def __getattr__(self, name):
        raise _manager_hard_denial(name, "插件不可访问插件管理器内部")

    def __setattr__(self, name, value):
        raise _manager_hard_denial(name, "插件不可改写插件管理器内部")

    def __repr__(self):
        return "<PluginManagerFacade>"


class PluginAPI:

    def __init__(self, plugin, app):
        self._plugin = plugin
        self.__api_app = app
        self._denial_callback = None
        self._last_denial = None
        self._degraded = {}

    @property
    def _app(self):
        try:
            frame = sys._getframe(1)
            caller = os.path.basename(frame.f_code.co_filename or "")
        except Exception:
            caller = ""
        if caller and not caller.startswith("djs_pyqt6"):
            self._observe("api.direct_app_access", f"插件直接访问 api._app（{caller}），应改用 api.host")
        return self.__api_app

    @_app.setter
    def _app(self, value):
        self.__api_app = value

    @property
    def host(self):
        return HostFacade(self)

    def _internal_manager(self):
        return getattr(self.__api_app, "plugin_manager", None)

    def _manager(self):
        manager = self._internal_manager()
        if manager is None:
            return None
        return _PluginManagerFacade(manager)

    def _plugin_file(self):
        return getattr(self._plugin, "filename", "") if self._plugin is not None else ""

    def _observe(self, code, detail, target=""):
        manager = self._internal_manager()
        if manager is None:
            return
        try:
            manager.note_observation(self._plugin, code, detail, "api", target)
        except Exception:
            pass

    def log(self, message, level="INFO"):
        if self._plugin is None:
            _audit_guard.active = True
            try:
                log_message(f"[Plugin:setup] {message}", level)
            finally:
                _audit_guard.active = False
            return
        self._plugin.log_plugin(message, level)

    def _plugin_name(self):
        return self._plugin.name if self._plugin and hasattr(self._plugin, 'name') else "unknown"

    def _require(self, perm, event, reason):
        manager = self._internal_manager()
        if manager is None:
            return False
        return manager.require_permission(perm, event, reason, plugin=self._plugin)

    def _validate_widget_class(self, id_name, widget_class, kind):
        if not (isinstance(widget_class, type) and issubclass(widget_class, QWidget)):
            msg = f"{kind}注册失败: 类未继承 QWidget (ID={id_name})"
            self._app.plugin_manager.report_register_error(self._plugin_name(), msg)
            raise TypeError(msg)

    def _check_duplicate_id(self, id_name, registry, kind):
        if id_name in registry:
            msg = f"{kind}注册失败: ID 重复 (ID={id_name})"
            self._app.plugin_manager.report_register_error(self._plugin_name(), msg)
            raise ValueError(msg)

    def register_dynamic_bg(self, id_name, display_name, widget_class, border_radius=None):
        self._require(PluginPermission.UI_INJECT, "register_dynamic_bg", "无界面注入权限（注册动态背景）")
        self._validate_widget_class(id_name, widget_class, "动态背景")
        self._check_duplicate_id(id_name, self._app.dynamic_bg_registry, "动态背景")
        self._app.dynamic_bg_registry[id_name] = display_name
        self._app.dynamic_bg_classes[id_name] = {
            "class": widget_class,
            "border_radius": border_radius
        }
        self.log(f"成功注册动态背景: {display_name}")

    def update_dynamic_bg_radius(self, id_name, border_radius):
        entry = self._app.dynamic_bg_classes.get(id_name)
        if not entry:
            self.log(f"未找到动态背景: {id_name}", "WARNING")
            return False
        entry["border_radius"] = border_radius
        for win in getattr(self._app, 'windows', []):
            w = getattr(win, 'bg_dynamic_widget', None)
            if w is not None and getattr(w, '_bg_id', None) == id_name:
                if hasattr(w, 'set_radius'):
                    w.set_radius(border_radius if border_radius is not None else 0)
                elif hasattr(w, 'radius'):
                    w.radius = border_radius if border_radius is not None else 0
                    w.update()
        return True

    def register_settings_panel(self, id_name, display_name, widget_class):
        self._require(PluginPermission.UI_INJECT, "register_settings_panel", "无界面注入权限（注册设置面板）")
        self._validate_widget_class(id_name, widget_class, "设置面板")
        if not hasattr(self._app, 'plugin_settings_panels'):
            self._app.plugin_settings_panels = {}
        self._check_duplicate_id(id_name, self._app.plugin_settings_panels, "设置面板")
        self._app.plugin_settings_panels[id_name] = {
            "name": display_name,
            "class": widget_class,
            "plugin": self._plugin_name()
        }
        self.log(f"成功注册设置面板: {display_name}")

    def register_widget(self, id_name, display_name, widget_class):
        self._require(PluginPermission.UI_INJECT, "register_widget", "无界面注入权限（注册自定义控件）")
        self._validate_widget_class(id_name, widget_class, "自定义控件")
        if not hasattr(self._app, 'custom_widget_registry'):
            self._app.custom_widget_registry = {}
        self._check_duplicate_id(id_name, self._app.custom_widget_registry, "自定义控件")
        self._app.custom_widget_registry[id_name] = {
            "name": display_name,
            "class": widget_class
        }
        self.log(f"成功注册自定义控件: {display_name}")

    def register_float_widget(self, id_name, display_name, widget_class,
                              default_size=(200, 200), description="", gpu=False):
        self._require(PluginPermission.UI_INJECT, "register_float_widget", "无界面注入权限（注册悬浮控件）")
        self._validate_widget_class(id_name, widget_class, "独立控件")
        if not hasattr(self._app, 'float_widget_registry'):
            self._app.float_widget_registry = {}
        self._check_duplicate_id(id_name, self._app.float_widget_registry, "独立控件")
        try:
            w, h = int(default_size[0]), int(default_size[1])
        except Exception:
            w, h = 200, 200
        self._app.float_widget_registry[id_name] = {
            "name": display_name,
            "class": widget_class,
            "size": (max(72, w), max(56, h)),
            "description": description or "",
            "plugin": self._plugin_name(),
            "gpu": bool(gpu),
        }
        self.log(f"成功注册独立控件: {display_name}")

    def remove_float_widget(self, widget=None):
        app = self._app
        for win in list(getattr(app, "float_widgets", []) or []):
            if getattr(win, "content", None) is widget:
                app.remove_float_widget(win.widget_id)
                return True
        return False

    def register_fullscreen_skin(self, id_name, display_name, widget_class, description="", gpu=False):
        self._require(PluginPermission.UI_INJECT, "register_fullscreen_skin", "无界面注入权限（注册全屏皮肤）")
        self._validate_widget_class(id_name, widget_class, "全屏皮肤")
        if not hasattr(self._app, 'fullscreen_skin_registry'):
            self._app.fullscreen_skin_registry = {}
        self._check_duplicate_id(id_name, self._app.fullscreen_skin_registry, "全屏皮肤")
        self._app.fullscreen_skin_registry[id_name] = {
            "name": display_name,
            "class": widget_class,
            "description": description or "",
            "plugin": self._plugin_name(),
            "gpu": bool(gpu),
        }
        self.log(f"成功注册全屏皮肤: {display_name}")

    def register_settings_widget(self, id_name, display_name, widget_class):
        self.register_settings_panel(id_name, display_name, widget_class)

    def get_config(self, key, default=None):
        config = self._app.plugin_manager.get_plugin_config(self._plugin.name)
        return config.get(key, default)

    def set_config(self, key, value):
        self._app.plugin_manager.set_plugin_config(self._plugin.name, key, value)

    def show_notification(self, title, message):
        self._require(PluginPermission.NOTIFICATION, "show_notification", "无发送通知权限")
        try:
            tray = self._app.tray_icon.tray
            tray.showMessage(title, message, QSystemTrayIcon.MessageIcon.Information, 3000)
        except Exception as e:
            self.log(f"发送通知失败: {e}", "WARNING")

    def set_autostart(self, name, path, enable=True):
        self._require(PluginPermission.AUTOSTART, "autostart.set",
                      "无开机启动项权限（宿主代写开机启动注册表）")
        return write_autostart_registry(name, path, enable)

    def ping(self):
        self._require(PluginPermission.SYSTEM_INFO, "host.ping", "无获取宿主信息权限（宿主连通检查）")
        return _run_host_capability(self._app, "ping", {})

    def registry_read(self, path, name=None, root="HKEY_CURRENT_USER"):
        self._require(PluginPermission.REGISTRY, "registry.read", "无访问注册表权限（读取注册表）")
        return _capability_registry_read({"path": path, "name": name, "root": root})

    def registry_write(self, path, name, value, root="HKEY_CURRENT_USER", kind="string"):
        self._require(PluginPermission.REGISTRY, "registry.write", "无访问注册表权限（写入注册表）")
        return _capability_registry_write({"path": path, "name": name, "value": value,
                                           "root": root, "kind": kind})

    def registry_delete(self, path, name=None, root="HKEY_CURRENT_USER"):
        self._require(PluginPermission.REGISTRY, "registry.delete", "无访问注册表权限（删除注册表项）")
        return _capability_registry_delete({"path": path, "name": name, "root": root})

    def run_command(self, command, timeout_ms=5000):
        self._require(PluginPermission.COMMAND, "command.run", "无执行系统命令权限")
        try:
            limit = max(500, min(int(timeout_ms), 10000))
        except Exception:
            limit = 5000
        return _run_host_capability(self._app, "run_command",
                                    {"command": command, "timeout_ms": limit})

    def spawn_process(self, program, args=None, timeout_ms=5000, cwd=""):
        self._require(PluginPermission.PROCESS_SPAWN, "process.spawn", "无创建进程权限")
        try:
            limit = max(500, min(int(timeout_ms), 10000))
        except Exception:
            limit = 5000
        return _run_host_capability(self._app, "spawn_process",
                                    {"program": program, "args": list(args or []),
                                     "timeout_ms": limit, "cwd": cwd})

    def socket_probe(self, host, port, timeout_ms=3000):
        self._require(PluginPermission.NETWORK_SOCKET, "socket.probe", "无直接 Socket 权限")
        try:
            limit = max(300, min(int(timeout_ms), 10000))
        except Exception:
            limit = 3000
        return _run_host_capability(self._app, "socket_probe",
                                    {"host": host, "port": port, "timeout_ms": limit})

    def request_permission(self, permission, feature="", reason="", timeout_ms=60000):
        manager = self._internal_manager()
        if manager is None:
            return PermissionResult({"ok": False, "level": "none", "code": "unavailable"})
        if self._plugin is None:
            return PermissionResult({"ok": False, "level": "none", "code": "unknown_plugin"})
        raw = manager.request_permission(
            self._plugin, permission, feature, reason, "explicit", timeout_ms)
        return self._build_result(raw, permission, "request_permission")

    def request_permissions(self, permissions, feature="", reason="", timeout_ms=60000):
        try:
            values = list(permissions)
        except TypeError:
            return PermissionResult({"ok": False, "level": "none", "code": "invalid"})
        if len(values) > 3:
            self.log(tr("perm_request_max_three"), "WARNING")
            return PermissionResult({"ok": False, "level": "none", "code": "too_many"})
        if not values:
            return PermissionResult({"ok": True, "level": "permanent", "code": "empty"})
        last = None
        for value in values:
            last = self.request_permission(value, feature, reason, timeout_ms)
            if not last:
                return last
        return last

    def _build_result(self, raw, permission, operation):
        result = dict(raw or {})
        manager = self._internal_manager()
        denial = None
        if not result.get("ok") and manager is not None:
            denial = manager.denial_from_result(
                self._plugin, permission, result, origin="api", operation=operation)
            self._last_denial = denial
        if denial is not None:
            result.setdefault("retryable", denial.get("retryable"))
            result.setdefault("unlockable", denial.get("unlockable"))
            result.setdefault("unlock_action", denial.get("unlock_action"))
        return PermissionResult(result, denial)

    def _notify_denial(self, decision):
        if not isinstance(decision, dict):
            return
        self._last_denial = decision
        callback = self._denial_callback
        if callback is None:
            return
        try:
            callback(dict(decision))
        except Exception as exc:
            self.log(f"on_denial 回调异常: {exc}", "WARNING")

    def permission_status(self, permission):
        manager = self._internal_manager()
        if manager is None or self._plugin is None:
            return "unknown"
        return manager.permission_status(self._plugin, permission)

    def permission_state(self, permission):
        manager = self._internal_manager()
        if manager is None or self._plugin is None:
            return {"level": "unknown", "status": "unknown", "since": "",
                    "denials": {}, "unlockable": False, "unlock_action": ""}
        return manager.permission_state(self._plugin, permission)

    def can(self, permission, target=None, event=""):
        manager = self._internal_manager()
        if manager is None or self._plugin is None:
            return make_decision("origin.unknown_plugin", ok=False, capability=event,
                                 origin="api", operation=event, target=str(target or ""))
        return manager.evaluate(permission, target=target, event=event,
                                plugin=self._plugin, origin="api")

    def explain(self, permission, target=None, event=""):
        decision = self.can(permission, target, event)
        return {
            "ok": decision.get("ok", False),
            "code": decision.get("code", ""),
            "layer": decision.get("layer", ""),
            "title": decision.get("title") or self._layer_title(decision.get("layer", "")),
            "detail": decision.get("reason", ""),
            "action": decision.get("unlock_action", ""),
            "target": decision.get("target", ""),
            "permission": decision.get("permission", ""),
        }

    def _layer_title(self, layer):
        return layer_title(layer)

    def on_denial(self, callback):
        self._denial_callback = callback if callable(callback) else None
        return self._denial_callback is not None

    def last_denial(self):
        return self._last_denial

    def call_with_fallback(self, permission, primary, fallback=None, target=None, event=""):
        decision = self.can(permission, target, event)
        if decision.get("ok"):
            return primary()
        self._notify_denial(decision)
        if fallback is None:
            raise decision_error(decision, origin="api")
        return fallback(decision)

    def declare_degraded(self, permission, reason, action):
        entry = {
            "permission": getattr(permission, "name", str(permission)),
            "reason": str(reason or "")[:240],
            "action": str(action or "")[:120],
            "time": datetime.now().strftime("%Y-%m-%d %H:%M:%S"),
        }
        self._degraded[entry["permission"]] = entry
        manager = self._internal_manager()
        if manager is not None:
            manager.declare_plugin_degraded(self._plugin, entry)
        return True

    def degraded_state(self):
        return dict(self._degraded)

    def capabilities(self):
        manager = self._internal_manager()
        if manager is None or self._plugin is None:
            return {"api_version": _PLUGIN_API_VERSION, "status": "unknown", "items": [],
                    "limits": {}, "features": {}, "denials": {}, "degraded": {}}
        snapshot = manager.capabilities_snapshot(self._plugin)
        snapshot["api_version"] = _PLUGIN_API_VERSION
        snapshot["degraded"] = dict(self._degraded)
        return snapshot

    def describe(self, obj, depth=1):
        data = {"type": type(obj).__name__, "module": getattr(type(obj), "__module__", "")}
        try:
            data["attributes"] = self.members(obj, True)
        except Exception:
            data["attributes"] = []
        if depth and hasattr(obj, "__dict__"):
            data["values"] = {str(k): type(v).__name__ for k, v in list(vars(obj).items())[:40]}
        return data

    def members(self, obj, public_only=True):
        names = []
        for name in dir(obj):
            if public_only and name.startswith("_"):
                continue
            names.append(name)
        return names[:200]

    def signature(self, func):
        code = getattr(func, "__code__", None)
        name = getattr(func, "__name__", type(func).__name__)
        if code is None:
            return {"name": name, "params": []}
        count = getattr(code, "co_argcount", 0)
        names = list(getattr(code, "co_varnames", ())[:count])
        defaults = getattr(func, "__defaults__", None) or ()
        required = len(names) - len(defaults)
        params = []
        for index, item in enumerate(names):
            default = None
            if index >= required:
                value = defaults[index - required]
                default = value if isinstance(value, (int, float, str, bool, type(None))) else repr(value)[:60]
            params.append({"name": item, "required": index < required, "default": default})
        return {"name": name, "params": params}

    def bind_behavior(self, widget_class, name, func):
        manager = self._internal_manager()
        if manager is None:
            return False
        manager.require_permission(
            PluginPermission.UI_MUTATE, f"widget.bind.{name}",
            "无改写控件类权限（绑定行为）", plugin=self._plugin)
        type.__setattr__(widget_class, str(name), func)
        return True


class HostFacade:

    _REGISTRY_KEYS = (
        "dynamic_bg_registry", "plugin_settings_panels", "custom_widget_registry",
        "float_widget_registry", "fullscreen_skin_registry",
    )

    def __init__(self, api):
        object.__setattr__(self, "_api", api)

    def _manager(self):
        api = object.__getattribute__(self, "_api")
        if api is None:
            return None
        return api._internal_manager()

    def _plugin(self):
        api = object.__getattribute__(self, "_api")
        return getattr(api, "_plugin", None)

    def _require(self, event, reason):
        manager = self._manager()
        if manager is None:
            return False
        return manager.require_permission(
            PluginPermission.UI_READ, event, reason, plugin=self._plugin())

    def _query(self, what):
        api = object.__getattribute__(self, "_api")
        fn = getattr(api, "_host_query", None)
        if not callable(fn):
            return None
        try:
            return fn(what)
        except Exception:
            return None

    def slots(self):
        self._require("host.slots", "无读取界面结构权限（查看插槽）")
        data = self._query("slots")
        if isinstance(data, list):
            return data
        api = object.__getattribute__(self, "_api")
        app = api._app
        result = []
        for key in HostFacade._REGISTRY_KEYS:
            registry = getattr(app, key, None)
            if isinstance(registry, dict):
                result.append({"kind": key, "ids": sorted(str(x) for x in registry.keys())})
        return result

    def theme(self):
        self._require("host.theme", "无读取界面结构权限（读取主题）")
        data = self._query("theme")
        if isinstance(data, dict) and data:
            return data
        api = object.__getattribute__(self, "_api")
        theme = getattr(api._app, "theme", None)
        if theme is None:
            return {"dark": is_system_dark(), "colors": {}}
        try:
            data = theme.to_dict()
        except Exception:
            data = {}
        if isinstance(data, dict):
            return data
        return {"dark": is_system_dark(), "colors": {}}

    def windows_meta(self):
        self._require("host.windows_meta", "无读取界面结构权限（查看窗口）")
        data = self._query("windows_meta")
        if isinstance(data, list):
            return data
        api = object.__getattribute__(self, "_api")
        windows = getattr(api._app, "windows", []) or []
        result = []
        for index, win in enumerate(windows):
            project = getattr(win, "project", None)
            result.append({
                "index": index,
                "title": str(getattr(project, "name", "") or ""),
                "visible": bool(getattr(win, "isVisible", lambda: False)()),
                "size": [int(getattr(win, "width", lambda: 0)()),
                         int(getattr(win, "height", lambda: 0)())],
                "fullscreen": bool(getattr(win, "is_fullscreen", False)),
                "project_type": str(getattr(project, "project_type", "") or ""),
            })
        return result

    def __getattr__(self, name):
        if str(name).startswith("register_"):
            api = object.__getattribute__(self, "_api")
            return getattr(api, name)
        raise AttributeError(f"api.host 不暴露 {name}")


