class PluginRowDelegate(QStyledItemDelegate):
    def __init__(self, parent=None):
        super().__init__(parent)
        self.bar_color = None

    def paint(self, painter, option, index):
        super().paint(painter, option, index)
        if index.column() != 0 or not (option.state & QStyle.StateFlag.State_Selected):
            return
        color = QColor(self.bar_color) if self.bar_color else option.palette.highlight().color()
        painter.save()
        painter.fillRect(option.rect.left(), option.rect.top() + 1, 3,
                         max(0, option.rect.height() - 2), color)
        painter.restore()


class ClipboardPermissionProxy:
    _GUARDED = frozenset({
        "text", "setText", "mimeData", "setMimeData", "pixmap", "setPixmap",
        "image", "setImage", "clear", "data",
    })

    def __init__(self, real, manager):
        object.__setattr__(self, "_real", real)
        object.__setattr__(self, "_manager", manager)

    def __getattr__(self, name):
        real = object.__getattribute__(self, "_real")
        if name in ClipboardPermissionProxy._GUARDED:
            manager = object.__getattribute__(self, "_manager")

            def guarded(*args, **kwargs):
                manager.require_permission(
                    PluginPermission.CLIPBOARD, f"clipboard.{name}",
                    f"无剪贴板权限（{name}）")
                return getattr(real, name)(*args, **kwargs)

            return guarded
        return getattr(real, name)


def read_plugin_manifest(plugin_dir, module_name):
    manifest_path = os.path.join(plugin_dir, module_name + ".json")
    if not os.path.isfile(manifest_path):
        return {}, None
    try:
        with open(manifest_path, "rb") as mf:
            mraw = mf.read(256 * 1024 + 1)
        if len(mraw) > 256 * 1024:
            return {}, "plugin.json 超过 256KB，已忽略清单"
        loaded = json.loads(mraw.decode("utf-8", errors="replace"))
        if isinstance(loaded, dict):
            return loaded, None
        return {}, None
    except Exception as e:
        return {}, f"plugin.json 解析失败: {e}"


def apply_plugin_manifest(plugin, manifest):
    manifest = manifest if isinstance(manifest, dict) else {}
    if manifest:
        for key, limit in (("name", 64), ("version", 32), ("author", 64), ("description", 200)):
            value = manifest.get(key)
            if isinstance(value, str) and value.strip():
                setattr(plugin, key, value.strip()[:limit])
    parsed = parse_permission_manifest(manifest, plugin.requested_permissions)
    plugin.baseline_permissions = parsed["baseline"]
    plugin.requested_permissions = parsed["requested"]
    plugin.ondemand_permissions = PluginPermission(
        int(parsed["requested"]) & ~int(parsed["baseline"]))
    plugin.permission_specs = parsed["specs"]
    plugin.permission_warnings = parsed["warnings"]
    plugin.permission_legacy = parsed["legacy"]
    om = manifest.get("own_modules")
    if isinstance(om, list):
        plugin.own_modules = [str(x).strip()[:200] for x in om
                              if isinstance(x, str) and x.strip()]


def write_autostart_registry(name, path, enable=True):
    if winreg is None:
        raise RuntimeError("当前系统不支持注册表开机启动项")
    label = str(name or "").strip()
    if not re.fullmatch(r"[A-Za-z0-9 ._-]{1,64}", label):
        raise ValueError("开机启动项名称只能使用字母、数字、空格、点、下划线、短横线，且不超过 64 个字符")
    raw = str(path or "").strip()
    if not raw or not os.path.isabs(raw):
        raise ValueError("开机启动项目标必须是绝对路径")
    target = os.path.abspath(raw)
    manager = _AUDIT_MANAGER
    if manager is not None and _caller_is_plugin_frame(2, 1):
        plugin = getattr(_plugin_context, "current_plugin", None)
        if plugin is None:
            plugin, _in_plugin = manager._scan_plugin_stack(limit=24)
        if plugin is not None:
            manager.require_permission(
                PluginPermission.AUTOSTART, "autostart.set",
                "无开机启动项权限（直接写入开机启动注册表）", plugin=plugin)
    run_key = r"Software\Microsoft\Windows\CurrentVersion\Run"
    previous_token = getattr(_audit_guard, "autostart_token", None)
    _audit_guard.autostart_token = object()
    try:
        if enable:
            if not os.path.isfile(target):
                raise FileNotFoundError(f"开机启动项目标不存在: {target}")
            key = winreg.OpenKey(winreg.HKEY_CURRENT_USER, run_key, 0, winreg.KEY_SET_VALUE)
            try:
                winreg.SetValueEx(key, label, 0, winreg.REG_SZ, f'"{target}"')
            finally:
                winreg.CloseKey(key)
            return True
        try:
            key = winreg.OpenKey(winreg.HKEY_CURRENT_USER, run_key, 0, winreg.KEY_SET_VALUE)
        except FileNotFoundError:
            return True
        try:
            try:
                winreg.DeleteValue(key, label)
            except FileNotFoundError:
                pass
        finally:
            winreg.CloseKey(key)
        return True
    finally:
        _audit_guard.autostart_token = previous_token


