def _host_jsonable(value, depth=0):
    if depth > 4:
        return None
    if value is None or isinstance(value, (bool, int, float, str)):
        return value
    if isinstance(value, (list, tuple)):
        return [_host_jsonable(v, depth + 1) for v in list(value)[:64]]
    if isinstance(value, dict):
        return {str(k): _host_jsonable(v, depth + 1) for k, v in list(value.items())[:64]}
    fn = getattr(value, "to_dict", None)
    if callable(fn):
        try:
            return _host_jsonable(fn(), depth + 1)
        except Exception:
            return None
    return None


_HOST_REGISTRY_ROOTS = {
    "HKEY_CURRENT_USER": "HKEY_CURRENT_USER",
    "HKEY_LOCAL_MACHINE": "HKEY_LOCAL_MACHINE",
}


def _registry_handle(root_name):
    if winreg is None:
        return None, "unsupported_platform"
    name = str(root_name or "HKEY_CURRENT_USER").upper()
    if name not in _HOST_REGISTRY_ROOTS:
        return None, "unsupported_root"
    return getattr(winreg, name, None), ""


def _registry_subpath(path):
    text = str(path or "").strip().strip("\\")
    if not text:
        return None
    if not re.match(r"(?i)^software(\\|$)", text):
        return None
    return text


def _capability_registry_read(params):
    handle, error = _registry_handle(params.get("root"))
    if handle is None:
        return {"ok": False, "error": error}
    path = _registry_subpath(params.get("path"))
    if path is None:
        return {"ok": False, "error": "path_not_allowed"}
    name = params.get("name")
    try:
        key = winreg.OpenKey(handle, path, 0, winreg.KEY_READ)
    except FileNotFoundError:
        return {"ok": False, "error": "not_found"}
    except OSError as exc:
        return {"ok": False, "error": str(exc)[:160]}
    try:
        if name is not None:
            try:
                value, value_type = winreg.QueryValueEx(key, str(name))
            except FileNotFoundError:
                return {"ok": False, "error": "value_not_found"}
            if isinstance(value, bytes):
                return {"ok": False, "error": "binary_value_unsupported"}
            return {"ok": True, "value": str(value)[:2048], "type": int(value_type)}
        values = {}
        for index in range(64):
            try:
                sub_name, sub_value, sub_type = winreg.EnumValue(key, index)
            except OSError:
                break
            if isinstance(sub_value, bytes):
                continue
            values[str(sub_name)] = str(sub_value)[:2048]
        return {"ok": True, "values": values}
    finally:
        try:
            winreg.CloseKey(key)
        except Exception:
            pass


def _capability_registry_write(params):
    handle, error = _registry_handle(params.get("root"))
    if handle is None:
        return {"ok": False, "error": error}
    if str(params.get("root") or "HKEY_CURRENT_USER").upper() != "HKEY_CURRENT_USER":
        return {"ok": False, "error": "root_readonly"}
    path = _registry_subpath(params.get("path"))
    name = str(params.get("name") or "").strip()
    if path is None:
        return {"ok": False, "error": "path_not_allowed"}
    if not name:
        return {"ok": False, "error": "name_required"}
    kind = str(params.get("kind") or "string").lower()
    value = params.get("value")
    try:
        if kind == "dword":
            data, data_type = int(value), winreg.REG_DWORD
        elif kind == "qword":
            data, data_type = int(value), winreg.REG_QWORD
        elif kind == "expand":
            data, data_type = str(value), winreg.REG_EXPAND_SZ
        else:
            data, data_type = str(value), winreg.REG_SZ
        key = winreg.CreateKeyEx(handle, path, 0, winreg.KEY_SET_VALUE)
    except (OSError, ValueError) as exc:
        return {"ok": False, "error": str(exc)[:160]}
    try:
        winreg.SetValueEx(key, name, 0, data_type, data)
    except OSError as exc:
        return {"ok": False, "error": str(exc)[:160]}
    finally:
        try:
            winreg.CloseKey(key)
        except Exception:
            pass
    return {"ok": True, "path": path, "name": name}


def _capability_registry_delete(params):
    handle, error = _registry_handle(params.get("root"))
    if handle is None:
        return {"ok": False, "error": error}
    if str(params.get("root") or "HKEY_CURRENT_USER").upper() != "HKEY_CURRENT_USER":
        return {"ok": False, "error": "root_readonly"}
    path = _registry_subpath(params.get("path"))
    if path is None:
        return {"ok": False, "error": "path_not_allowed"}
    name = params.get("name")
    if name is None:
        try:
            winreg.DeleteKey(handle, path)
        except FileNotFoundError:
            return {"ok": False, "error": "not_found"}
        except OSError as exc:
            return {"ok": False, "error": str(exc)[:160]}
        return {"ok": True, "path": path, "name": None}
    try:
        key = winreg.OpenKey(handle, path, 0, winreg.KEY_ALL_ACCESS)
    except FileNotFoundError:
        return {"ok": False, "error": "not_found"}
    except OSError as exc:
        return {"ok": False, "error": str(exc)[:160]}
    try:
        winreg.DeleteValue(key, str(name))
    except OSError as exc:
        return {"ok": False, "error": str(exc)[:160]}
    finally:
        try:
            winreg.CloseKey(key)
        except Exception:
            pass
    return {"ok": True, "path": path, "name": name}


def _capability_process(program, args, cwd, timeout_ms):
    if not program:
        return {"ok": False, "error": "program_required"}
    proc = QProcess()
    proc.setProcessChannelMode(QProcess.ProcessChannelMode.SeparateChannels)
    if cwd and os.path.isdir(cwd):
        proc.setWorkingDirectory(cwd)
    state = {"done": False}
    loop = QEventLoop()

    def _finish(*_args):
        state["done"] = True
        loop.quit()

    proc.finished.connect(_finish)
    proc.errorOccurred.connect(_finish)
    proc.start(program, list(args or []))
    if not proc.waitForStarted(2500):
        return {"ok": False, "error": "start_failed"}
    timer = QTimer()
    timer.setSingleShot(True)
    timer.timeout.connect(loop.quit)
    timer.start(max(500, int(timeout_ms)))
    loop.exec()
    timer.stop()
    if not state["done"]:
        proc.kill()
        proc.waitForFinished(800)
        return {"ok": False, "error": "timeout"}
    try:
        out = bytes(proc.readAllStandardOutput()).decode("utf-8", "replace")
        err = bytes(proc.readAllStandardError()).decode("utf-8", "replace")
    except Exception:
        out, err = "", ""
    code = int(proc.exitCode()) if proc.exitStatus() == QProcess.ExitStatus.NormalExit else -1
    return {"ok": code == 0, "exit_code": code, "stdout": out[:4000], "stderr": err[:4000]}


def _capability_socket_probe(host, port, timeout_ms):
    if not host:
        return {"ok": False, "error": "host_required"}
    try:
        port_value = int(port)
    except Exception:
        return {"ok": False, "error": "port_invalid"}
    if port_value <= 0 or port_value > 65535:
        return {"ok": False, "error": "port_invalid"}
    sock = QTcpSocket()
    try:
        connected = bool(sock.waitForConnected(max(300, int(timeout_ms))))
    except Exception:
        connected = False
    sock.abort()
    if connected:
        return {"ok": True, "host": str(host), "port": port_value}
    return {"ok": False, "error": "connect_failed"}


def _run_host_capability(app, method, params):
    params = params if isinstance(params, dict) else {}
    op = str(method or "")
    if op == "ping":
        return {"ok": True, "host_pid": os.getpid(),
                "version": str(getattr(app, "current_version", "") or ""),
                "build": str(getattr(app, "build_version", "") or ""),
                "api_version": _PLUGIN_API_VERSION}
    if op == "registry_read":
        return _capability_registry_read(params)
    if op == "registry_write":
        return _capability_registry_write(params)
    if op == "registry_delete":
        return _capability_registry_delete(params)
    if op == "run_command":
        command = str(params.get("command") or "").strip()
        if not command or len(command) > 1000:
            return {"ok": False, "error": "command_invalid"}
        if sys.platform == "win32":
            shell = os.environ.get("COMSPEC", "cmd.exe")
            argv = ["/c", command]
        else:
            shell = "/bin/sh"
            argv = ["-c", command]
        result = _capability_process(shell, argv, "", int(params.get("timeout_ms") or 5000))
        result["command"] = command
        return result
    if op == "spawn_process":
        program = str(params.get("program") or "").strip()
        if not program or len(program) > 512:
            return {"ok": False, "error": "program_invalid"}
        argv = [str(x)[:512] for x in (params.get("args") or [])][:32]
        result = _capability_process(program, argv, str(params.get("cwd") or ""),
                                     int(params.get("timeout_ms") or 5000))
        result["program"] = program
        return result
    if op == "socket_probe":
        return _capability_socket_probe(params.get("host"), params.get("port"),
                                        int(params.get("timeout_ms") or 3000))
    return {"ok": False, "error": "unsupported_op"}


class RemotePlugin(Plugin):

    def __init__(self, manager, meta):
        super().__init__()
        self._manager = manager
        self.name = str(meta.get("name") or "Unnamed Plugin")
        self.version = str(meta.get("version") or "0.1")
        self.author = str(meta.get("author") or "Unknown")
        self.description = str(meta.get("description") or "")
        self.filename = meta.get("filename")
        self.requested_permissions = PluginPermission(int(meta.get("requested_permissions") or 0))
        self.permissions = PluginPermission(int(meta.get("permissions") or 0))
        self.baseline_permissions = PluginPermission(int(meta.get("baseline_permissions") or 0))
        self.ondemand_permissions = PluginPermission(int(meta.get("ondemand_permissions") or 0))
        self.permission_specs = dict(meta.get("permission_specs") or {})
        self.permission_warnings = list(meta.get("permission_warnings") or [])
        self.permission_legacy = bool(meta.get("permission_legacy", False))
        self.trusted = bool(meta.get("trusted", False))
        self.signature_verified = bool(meta.get("signature_verified", False))
        self.enabled = bool(meta.get("enabled", False))
        self.enable_error = str(meta.get("enable_error") or "")
        self.has_info_widget = bool(meta.get("has_info_widget", False))
        self.remote = True

    def log_plugin(self, message, level="INFO"):
        timestamp = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
        self.log.append(f"[{timestamp}][{level}] {message}")
        if len(self.log) > 500:
            del self.log[:-500]

    def on_enable(self):
        _audit_guard.active = True
        try:
            self._manager.plugin_host_enable(self.filename)
        finally:
            _audit_guard.active = False

    def on_disable(self):
        _audit_guard.active = True
        try:
            self._manager.plugin_host_disable(self.filename)
        finally:
            _audit_guard.active = False

    def get_info_widget(self, parent=None):
        if not self.has_info_widget:
            return None
        panel = QWidget(parent)
        panel.setObjectName("PluginInfoPanel")
        layer = QVBoxLayout(panel)
        layer.setContentsMargins(0, 0, 0, 0)
        layer.setSpacing(8)
        title = QLabel(self.name)
        title.setObjectName("PluginInfoTitle")
        text = QLabel(self.description or self.filename)
        text.setObjectName("PluginInfoText")
        text.setWordWrap(True)
        layer.addWidget(title)
        layer.addWidget(text)
        button = QPushButton(tr("plugin_open_panel"))
        button.setCursor(Qt.CursorShape.PointingHandCursor)
        layer.addWidget(button, 0, Qt.AlignmentFlag.AlignLeft)
        layer.addStretch(1)
        theme = getattr(getattr(self._manager, "app", None), "theme", None) or get_system_theme()
        try:
            tk = get_theme_colors(theme)
        except Exception:
            tk = get_theme_colors(get_system_theme())
        panel.setStyleSheet(
            "QWidget#PluginInfoPanel { background: transparent; }"
            "QLabel#PluginInfoTitle { color: %s; font-weight: 600; }"
            "QLabel#PluginInfoText { color: %s; }"
            "QPushButton { background: %s; color: %s; border: 1px solid %s;"
            " border-radius: 6px; padding: 6px 12px; }"
            "QPushButton:hover { border-color: %s; color: %s; }"
            % (tk["text_color"], tk["secondary_text"], tk["input_bg"], tk["text_color"],
               tk["border_color"], tk["accent"], tk["accent"]))
        def _open_panel():
            factory = RemoteWidgetFactory(self._manager, "info_widget", self.filename, self.filename,
                                          (520, 340), {"name": self.name, "version": self.version})
            dialog = RemoteWidgetHostDialog(self._manager, factory, None)
            dialog.setAttribute(Qt.WidgetAttribute.WA_DeleteOnClose, True)
            panel._info_dialog = dialog
            dialog.show()
        button.clicked.connect(lambda checked=False: _open_panel())
        return panel

    def __getattr__(self, name):
        if name.startswith("on_") and len(name) > 3:
            def _forward(*args, **kwargs):
                _audit_guard.active = True
                try:
                    self._manager.plugin_host_event(name, self.filename, args, kwargs)
                finally:
                    _audit_guard.active = False
            return _forward
        raise AttributeError(name)


class RemoteWidgetFactory:

    def __init__(self, manager, kind, widget_id, plugin_filename, default_size=(320, 240), meta=None):
        self.manager = manager
        self.kind = kind
        self.widget_id = widget_id
        self.plugin_filename = plugin_filename
        self.default_size = default_size
        self.meta = meta or {}

    def __call__(self, *args, **kwargs):
        parent = kwargs.get("parent")
        for item in args:
            if isinstance(item, QWidget):
                parent = item
                break
        if self.kind in ("settings_panel", "settings_page"):
            return RemoteWidgetHostDialog(self.manager, self, parent)
        return RemoteWidgetHostWidget(self.manager, self, parent)

    def __repr__(self):
        return f"<RemoteWidgetFactory {self.kind}:{self.widget_id}>"


class RemoteWidgetHostWidget(QWidget):

    _FORWARD_PREFIX = ("set_", "update_", "trigger_", "refresh_", "apply_",
                       "start", "stop", "reset", "next_", "show_")

    def __init__(self, manager, factory, parent=None, token=None):
        super().__init__(parent)
        self._manager = manager
        self._factory = factory
        self._token = token or manager.plugin_host_new_widget_token()
        self._hwnd = 0
        self._container = None
        self._layout = QVBoxLayout(self)
        self._layout.setContentsMargins(0, 0, 0, 0)
        self._layout.setSpacing(0)
        self._placeholder = QLabel("插件控件加载中…", self)
        self._placeholder.setAlignment(Qt.AlignmentFlag.AlignCenter)
        self._placeholder.setWordWrap(True)
        self._layout.addWidget(self._placeholder)
        self.setMinimumSize(1, 1)
        manager.plugin_host_register_widget(self._token, self)
        self.destroyed.connect(lambda *_: manager.plugin_host_forget_widget(self._token))
        self._create_tries = 0
        self._create_timer = QTimer(self)
        self._create_timer.setInterval(400)
        self._create_timer.timeout.connect(self._retry_create_widget)
        if not manager.plugin_host_create_widget(self._token, factory, 0, 0):
            self._create_timer.start()

    def _retry_create_widget(self):
        if self.__dict__.get("_hwnd"):
            self._create_timer.stop()
            return
        self._create_tries += 1
        if self._create_tries > 90:
            self._create_timer.stop()
            self._placeholder.setText("插件控件加载失败\n插件宿主未响应")
            return
        if self._manager.plugin_host_create_widget(self._token, self._factory, 0, 0):
            self._create_timer.stop()

    def notify_create_failed(self, message):
        if self.__dict__.get("_hwnd"):
            return
        timer = self.__dict__.get("_create_timer")
        if timer is not None:
            timer.stop()
        text = str(message or "").strip() or "插件宿主拒绝创建控件"
        self._placeholder.setText("插件控件加载失败\n" + text +
                                  "\n请在安全中心确认该插件已获得界面注入权限")

    def notify_create_pending(self):
        if self.__dict__.get("_hwnd"):
            return
        timer = self.__dict__.get("_create_timer")
        if timer is not None and not timer.isActive():
            timer.start()

    def attach_native(self, hwnd):
        try:
            win = QWindow.fromWinId(int(hwnd))
            container = QWidget.createWindowContainer(win, self)
            container.setMinimumSize(1, 1)
            container.setFocusPolicy(Qt.FocusPolicy.StrongFocus)
        except Exception as e:
            self._placeholder.setText(f"控件嵌入失败\n{e}")
            return
        self._hwnd = int(hwnd)
        self._foreign_window = win
        timer = self.__dict__.get("_create_timer")
        if timer is not None:
            timer.stop()
        self._layout.addWidget(container)
        self._placeholder.hide()
        self._container = container
        container.installEventFilter(self)
        self.setFocusProxy(container)
        self.manager_sync_size()
        self._sync_foreign_geometry()

    def eventFilter(self, obj, event):
        if obj is self.__dict__.get("_container") and event.type() == QEvent.Type.MouseButtonPress:
            hwnd = self.__dict__.get("_hwnd") or 0
            if hwnd:
                try:
                    import ctypes
                    ctypes.windll.user32.SetFocus(int(hwnd))
                except Exception:
                    pass
        return super().eventFilter(obj, event)

    def manager_sync_size(self):
        if self._hwnd:
            self._manager.plugin_host_resize_widget(self._token, max(1, self.width()), max(1, self.height()))

    def _sync_foreign_geometry(self):
        win = self.__dict__.get("_foreign_window")
        if win is None:
            return
        try:
            win.setGeometry(0, 0, max(1, self.width()), max(1, self.height()))
        except Exception:
            pass

    def detach_remote(self):
        state = self.__dict__
        token = state.get("_token")
        if not token:
            return
        state["_token"] = ""
        state["_hwnd"] = 0
        container = state.get("_container")
        if container is not None:
            try:
                container.hide()
                container.setParent(None)
                container.deleteLater()
            except Exception:
                pass
        state["_container"] = None
        state["_foreign_window"] = None
        try:
            self._manager.plugin_host_forget_widget(token)
        except Exception:
            pass

    def closeEvent(self, event):
        self.detach_remote()
        super().closeEvent(event)

    def resizeEvent(self, event):
        super().resizeEvent(event)
        self.manager_sync_size()
        self._sync_foreign_geometry()

    def __getattr__(self, name):
        if name.startswith("_") or not name:
            raise AttributeError(name)
        state = self.__dict__
        manager = state.get("_manager")
        if manager is None:
            raise AttributeError(name)
        if name.startswith(self._FORWARD_PREFIX) or name in ("invalidate", "rebuild"):
            token = state.get("_token")

            def _forward(*args, **kwargs):
                manager.plugin_host_call_widget(token, name, args, kwargs)
            return _forward
        raise AttributeError(name)


class RemoteWidgetHostDialog(RemoteWidgetHostWidget):

    def __init__(self, manager, factory, parent=None, token=None):
        super().__init__(manager, factory, parent, token)
        self.setWindowFlags(Qt.WindowType.Dialog)
        self.setWindowTitle(factory.meta.get("name") or factory.widget_id)
        width, height = factory.default_size
        screen = QGuiApplication.primaryScreen()
        if screen is not None:
            geo = screen.availableGeometry()
            width = min(int(width), max(420, geo.width() - 60))
            height = min(int(height), max(300, geo.height() - 80))
        self.resize(int(width), int(height))

    def showEvent(self, event):
        super().showEvent(event)
        QTimer.singleShot(80, self._focus_native)

    def _focus_native(self):
        hwnd = self.__dict__.get("_hwnd") or 0
        if not hwnd:
            return
        try:
            import ctypes
            ctypes.windll.user32.SetFocus(int(hwnd))
        except Exception:
            pass


_reflect_observer = None


def _report_dunder(name, action):
    if _reflect_observer is None:
        return
    try:
        _reflect_observer(name, action)
    except Exception:
        pass


def _check_dunder(name, action):
    text = str(name)
    if text.startswith("__") and text.endswith("__"):
        _report_dunder(text, action)


def _host_safe_builtins(import_fn):
    import builtins as _bi
    allowed = (
        "print", "len", "range", "int", "float", "str", "list", "dict", "tuple",
        "set", "bool", "bytes", "bytearray", "isinstance", "hasattr", "getattr",
        "setattr", "delattr", "property", "staticmethod", "classmethod", "super",
        "object", "type", "enumerate", "zip", "map", "filter", "sorted", "reversed",
        "min", "max", "sum", "abs", "round", "any", "all", "iter", "next", "ord",
        "chr", "id", "repr", "dir", "vars", "hex", "oct", "bin", "divmod", "pow",
        "hash", "slice", "complex", "memoryview", "frozenset", "format", "callable",
        "open", "eval", "exec", "compile", "__build_class__",
    )
    table = {}
    for name in allowed:
        value = getattr(_bi, name, None)
        if value is not None:
            table[name] = value
    for name in dir(_bi):
        value = getattr(_bi, name)
        if isinstance(value, type) and issubclass(value, BaseException):
            table[name] = value
    table["__import__"] = import_fn
    table["True"] = True
    table["False"] = False
    table["None"] = None
    table["getattr"] = lambda obj, name, *default: (
        _check_dunder(name, "getattr"), getattr(obj, name, *default))[1]
    table["setattr"] = lambda obj, name, value: (
        _check_dunder(name, "setattr"), setattr(obj, name, value))[1]
    table["delattr"] = lambda obj, name: (
        _check_dunder(name, "delattr"), delattr(obj, name))[1]
    table["vars"] = lambda *items: (_report_dunder("__dict__", "vars"), vars(*items))[1]
    table["dir"] = lambda *items: (_report_dunder("*", "dir"), dir(*items))[1]
    return table


