class HostPluginAPI:

    def __init__(self, runtime, filename):
        self._runtime = runtime
        self._filename = filename
        self._plugin = None
        self._denial_callback = None
        self._last_denial = None
        self._degraded = {}
        self._token = hashlib.sha256(os.urandom(24)).hexdigest()[:24]
        try:
            runtime.register_caller_token(filename, self._token)
        except Exception:
            pass

    def bind(self, plugin):
        self._plugin = plugin
        if plugin is not None:
            plugin.api = self

    @property
    def host(self):
        return HostFacade(self)

    @property
    def _app(self):
        guard = getattr(self._runtime, "guard", None)
        if guard is not None and self._plugin is not None:
            try:
                guard.note_observation(self._plugin, "api.direct_app_access",
                                       "宿主模式禁止插件直取内部对象", "api", "")
            except Exception:
                pass
        return guard

    def _internal_manager(self):
        return getattr(self._runtime, "guard", None)

    def _manager(self):
        guard = self._internal_manager()
        if guard is None:
            return None
        return _PluginManagerFacade(guard)

    def _host_query(self, what):
        if self._plugin is None:
            return None
        return self._runtime.host_request("host_query",
                                          {"what": str(what), "plugin": self._filename,
                                           "_caller_token": self._token}, 6000)

    def _host_capability(self, op, params, timeout_ms, permission, event, reason):
        self._require(permission, event, reason)
        payload = {"op": str(op), "plugin": self._filename, "_caller_token": self._token}
        payload.update(params or {})
        result = self._runtime.host_request("capability", payload, timeout_ms)
        if isinstance(result, dict):
            return result
        return {"ok": False, "error": "host.unavailable"}

    def _name(self):
        if self._plugin is not None:
            return getattr(self._plugin, "name", self._filename)
        return self._filename

    def _require(self, perm, event, reason):
        guard = getattr(self._runtime, "guard", None)
        if self._plugin is None or guard is None:
            return False
        return guard.require_permission(perm, event, reason, plugin=self._plugin)

    def log(self, message, level="INFO"):
        self._runtime.send_event("log", {"plugin": self._filename, "message": str(message), "level": level})

    def _validate_widget_class(self, id_name, widget_class, kind):
        if not (isinstance(widget_class, type) and issubclass(widget_class, QWidget)):
            msg = f"{kind}注册失败: 类未继承 QWidget (ID={id_name})"
            self._runtime.report_register_error(self._filename, msg)
            raise TypeError(msg)

    def _check_duplicate(self, id_name, kind):
        if (kind, id_name) in self._runtime.widget_classes:
            msg = f"{kind}注册失败: ID 重复 (ID={id_name})"
            self._runtime.report_register_error(self._filename, msg)
            raise ValueError(msg)

    def _register(self, kind, id_name, display_name, widget_class, extra=None):
        self._runtime.widget_classes[(kind, id_name)] = widget_class
        payload = {"kind": kind, "id": str(id_name), "name": str(display_name),
                   "plugin": self._filename}
        if extra:
            payload.update(extra)
        self._runtime.send_event("register", payload)

    def register_dynamic_bg(self, id_name, display_name, widget_class, border_radius=None):
        self._require(PluginPermission.UI_INJECT, "register_dynamic_bg", "无界面注入权限（注册动态背景）")
        self._validate_widget_class(id_name, widget_class, "动态背景")
        self._check_duplicate(id_name, "dynamic_bg")
        self._register("dynamic_bg", id_name, display_name, widget_class,
                       {"radius": border_radius})

    def update_dynamic_bg_radius(self, id_name, border_radius):
        self._runtime.send_event("radius", {"plugin": self._filename, "id": str(id_name),
                                            "radius": border_radius})
        return True

    def register_settings_panel(self, id_name, display_name, widget_class):
        self._require(PluginPermission.UI_INJECT, "register_settings_panel", "无界面注入权限（注册设置面板）")
        self._validate_widget_class(id_name, widget_class, "设置面板")
        self._check_duplicate(id_name, "settings_panel")
        self._register("settings_panel", id_name, display_name, widget_class)

    def register_settings_widget(self, id_name, display_name, widget_class):
        self.register_settings_panel(id_name, display_name, widget_class)

    def register_settings_page(self, id_name, display_name, widget_class, size=None):
        self._require(PluginPermission.UI_INJECT, "register_settings_page", "无界面注入权限（注册设置页）")
        self._validate_widget_class(id_name, widget_class, "设置页")
        self._check_duplicate(id_name, "settings_page")
        extra = {"size": [int(size[0]), int(size[1])]} if size else None
        self._register("settings_page", id_name, display_name, widget_class, extra)

    def register_card_slot(self, slot_id, display_name, widget_class,
                           anchor="bottom", size=(320, 120), offset=(0, 0)):
        self._require(PluginPermission.UI_INJECT, "register_card_slot", "无界面注入权限（注册卡片插槽）")
        self._validate_widget_class(slot_id, widget_class, "卡片插槽")
        self._check_duplicate(slot_id, "card_slot")
        try:
            width, height = int(size[0]), int(size[1])
        except Exception:
            width, height = 320, 120
        try:
            off_x, off_y = int(offset[0]), int(offset[1])
        except Exception:
            off_x, off_y = 0, 0
        anchor = str(anchor or "bottom")
        if anchor not in ("top", "bottom", "left", "right",
                          "top-left", "top-right", "bottom-left", "bottom-right"):
            anchor = "bottom"
        self._register("card_slot", slot_id, display_name, widget_class, {
            "anchor": anchor,
            "size": [max(40, width), max(24, height)],
            "offset": [off_x, off_y],
        })

    def register_widget(self, id_name, display_name, widget_class):
        self._require(PluginPermission.UI_INJECT, "register_widget", "无界面注入权限（注册自定义控件）")
        self._validate_widget_class(id_name, widget_class, "自定义控件")
        self._check_duplicate(id_name, "custom_widget")
        self._register("custom_widget", id_name, display_name, widget_class)

    def register_float_widget(self, id_name, display_name, widget_class,
                              default_size=(200, 200), description="", gpu=False):
        self._require(PluginPermission.UI_INJECT, "register_float_widget", "无界面注入权限（注册悬浮控件）")
        self._validate_widget_class(id_name, widget_class, "独立控件")
        self._check_duplicate(id_name, "float_widget")
        try:
            w, h = int(default_size[0]), int(default_size[1])
        except Exception:
            w, h = 200, 200
        self._register("float_widget", id_name, display_name, widget_class,
                       {"size": [max(72, w), max(56, h)],
                        "description": description or "", "gpu": bool(gpu)})

    def register_fullscreen_skin(self, id_name, display_name, widget_class, description="", gpu=False):
        self._require(PluginPermission.UI_INJECT, "register_fullscreen_skin", "无界面注入权限（注册全屏皮肤）")
        self._validate_widget_class(id_name, widget_class, "全屏皮肤")
        self._check_duplicate(id_name, "fullscreen_skin")
        self._register("fullscreen_skin", id_name, display_name, widget_class,
                       {"description": description or "", "gpu": bool(gpu)})

    def get_config(self, key, default=None):
        return self._runtime.get_config(self._filename, key, default)

    def set_config(self, key, value):
        self._runtime.set_config(self._filename, key, value)

    def show_notification(self, title, message):
        self._require(PluginPermission.NOTIFICATION, "show_notification", "无发送通知权限")
        self._runtime.send_event("notify", {"title": str(title), "message": str(message)})

    def remove_float_widget(self, widget=None):
        token = str(getattr(widget, "_host_token", "") or "")
        if not token:
            raise RuntimeError("未找到控件标识")
        self._runtime.send_event("widget_remove", {"plugin": self._filename, "token": token})

    def resize_float_widget(self, widget=None, width=0, height=0, x=None, y=None, final=False):
        token = str(getattr(widget, "_host_token", "") or "")
        if not token:
            raise RuntimeError("未找到控件标识")
        self._runtime.send_event("widget_resize", {
            "plugin": self._filename, "token": token,
            "width": int(width), "height": int(height),
            "x": None if x is None else int(x),
            "y": None if y is None else int(y),
            "final": bool(final),
        })

    def set_autostart(self, name, path, enable=True):
        self._require(PluginPermission.AUTOSTART, "autostart.set",
                      "无开机启动项权限（宿主代写开机启动注册表）")
        return write_autostart_registry(name, path, enable)

    def ping(self):
        return self._host_capability("ping", {}, 4000, PluginPermission.SYSTEM_INFO,
                                     "host.ping", "无获取宿主信息权限（宿主连通检查）")

    def registry_read(self, path, name=None, root="HKEY_CURRENT_USER"):
        return self._host_capability("registry_read",
                                     {"path": str(path), "name": None if name is None else str(name),
                                      "root": str(root)},
                                     4000 + 1000, PluginPermission.REGISTRY,
                                     "registry.read", "无访问注册表权限（读取注册表）")

    def registry_write(self, path, name, value, root="HKEY_CURRENT_USER", kind="string"):
        return self._host_capability("registry_write",
                                     {"path": str(path), "name": str(name), "value": value,
                                      "root": str(root), "kind": str(kind)},
                                     4000 + 1000, PluginPermission.REGISTRY,
                                     "registry.write", "无访问注册表权限（写入注册表）")

    def registry_delete(self, path, name=None, root="HKEY_CURRENT_USER"):
        return self._host_capability("registry_delete",
                                     {"path": str(path), "name": None if name is None else str(name),
                                      "root": str(root)},
                                     4000 + 1000, PluginPermission.REGISTRY,
                                     "registry.delete", "无访问注册表权限（删除注册表项）")

    def run_command(self, command, timeout_ms=5000):
        try:
            limit = max(500, min(int(timeout_ms), 10000))
        except Exception:
            limit = 5000
        return self._host_capability("run_command", {"command": str(command), "timeout_ms": limit},
                                     limit + 2000, PluginPermission.COMMAND,
                                     "command.run", "无执行系统命令权限（宿主代理执行）")

    def spawn_process(self, program, args=None, timeout_ms=5000, cwd=""):
        try:
            limit = max(500, min(int(timeout_ms), 10000))
        except Exception:
            limit = 5000
        argv = [str(x) for x in (args or [])][:32]
        return self._host_capability("spawn_process",
                                     {"program": str(program), "args": argv,
                                      "timeout_ms": limit, "cwd": str(cwd or "")},
                                     limit + 2000, PluginPermission.PROCESS_SPAWN,
                                     "process.spawn", "无创建进程权限（宿主代理启动）")

    def socket_probe(self, host, port, timeout_ms=3000):
        try:
            limit = max(300, min(int(timeout_ms), 10000))
            port_value = int(port)
        except Exception:
            limit = 3000
            port_value = 0
        return self._host_capability("socket_probe",
                                     {"host": str(host), "port": port_value, "timeout_ms": limit},
                                     limit + 2000, PluginPermission.NETWORK_SOCKET,
                                     "socket.probe", "无直接 Socket 权限（宿主代理连接）")

    def request_permission(self, permission, feature="", reason="", timeout_ms=60000):
        raw = self._runtime.request_permission(
            self._filename, int(permission_flag_from(permission)), feature,
            reason, "explicit", timeout_ms)
        return self._build_result(raw, permission, "request_permission")

    def _build_result(self, raw, permission, operation):
        guard = getattr(self._runtime, "guard", None)
        result = dict(raw or {})
        denial = None
        if not result.get("ok") and guard is not None and self._plugin is not None:
            denial = guard.denial_from_result(self._plugin, permission, result,
                                              origin="host", operation=operation)
            self._last_denial = denial
        if denial is not None:
            result.setdefault("retryable", denial.get("retryable"))
            result.setdefault("unlockable", denial.get("unlockable"))
            result.setdefault("unlock_action", denial.get("unlock_action"))
        return PermissionResult(result, denial)

    def _notify_denial(self, decision):
        self._last_denial = decision
        if self._denial_callback is None or not isinstance(decision, dict):
            return
        try:
            self._denial_callback(dict(decision))
        except Exception as exc:
            self.log(f"on_denial 回调异常: {exc}", "WARNING")

    def request_permissions(self, permissions, feature="", reason="", timeout_ms=60000):
        try:
            values = list(permissions)
        except TypeError:
            return PermissionResult({"ok": False, "level": "none", "code": "invalid"})
        if len(values) > 3:
            self.log(tr("perm_request_max_three"), "WARNING")
            return PermissionResult({"ok": False, "level": "none", "code": "too_many"})
        if not values:
            return PermissionResult({"ok": True, "level": "permanent", "code": "empty"})
        last = None
        for value in values:
            last = self.request_permission(value, feature, reason, timeout_ms)
            if not last:
                return last
        return last

    def permission_status(self, permission):
        guard = getattr(self._runtime, "guard", None)
        if self._plugin is None or guard is None:
            return "unknown"
        return guard.permission_status(self._plugin, permission)

    def permission_state(self, permission):
        guard = getattr(self._runtime, "guard", None)
        if self._plugin is None or guard is None:
            return {"level": "unknown", "status": "unknown", "since": "",
                    "denials": {}, "unlockable": False, "unlock_action": ""}
        return guard.permission_state(self._plugin, permission)

    def can(self, permission, target=None, event=""):
        guard = getattr(self._runtime, "guard", None)
        if guard is None or self._plugin is None:
            return make_decision("origin.unknown_plugin", ok=False, capability=event,
                                 origin="host", operation=event, target=str(target or ""))
        return guard.evaluate(permission, target=target, event=event,
                              plugin=self._plugin, origin="host")

    def explain(self, permission, target=None, event=""):
        decision = self.can(permission, target, event)
        layer = decision.get("layer", "")
        return {
            "ok": decision.get("ok", False),
            "code": decision.get("code", ""),
            "layer": layer,
            "title": decision.get("title") or layer_title(layer or "L2"),
            "detail": decision.get("reason", ""),
            "action": decision.get("unlock_action", ""),
            "target": decision.get("target", ""),
            "permission": decision.get("permission", ""),
        }

    def on_denial(self, callback):
        self._denial_callback = callback if callable(callback) else None
        return self._denial_callback is not None

    def last_denial(self):
        return self._last_denial

    def call_with_fallback(self, permission, primary, fallback=None, target=None, event=""):
        decision = self.can(permission, target, event)
        if decision.get("ok"):
            return primary()
        self._notify_denial(decision)
        if fallback is None:
            raise decision_error(decision, origin="host")
        return fallback(decision)

    def declare_degraded(self, permission, reason, action):
        guard = getattr(self._runtime, "guard", None)
        entry = {
            "permission": getattr(permission, "name", str(permission)),
            "reason": str(reason or "")[:240],
            "action": str(action or "")[:120],
            "time": datetime.now().strftime("%Y-%m-%d %H:%M:%S"),
        }
        self._degraded[entry["permission"]] = entry
        if guard is not None and self._plugin is not None:
            guard.declare_plugin_degraded(self._plugin, entry)
        return True

    def degraded_state(self):
        return dict(self._degraded)

    def capabilities(self):
        guard = getattr(self._runtime, "guard", None)
        if guard is None or self._plugin is None:
            return {"api_version": _PLUGIN_API_VERSION, "status": "unknown", "items": [],
                    "limits": {}, "features": {}, "denials": {}, "degraded": {}}
        snapshot = guard.capabilities_snapshot(self._plugin)
        snapshot["api_version"] = _PLUGIN_API_VERSION
        snapshot["degraded"] = dict(self._degraded)
        return snapshot

    def describe(self, obj, depth=1):
        data = {"type": type(obj).__name__, "module": getattr(type(obj), "__module__", "")}
        try:
            data["attributes"] = self.members(obj, True)
        except Exception:
            data["attributes"] = []
        if depth and hasattr(obj, "__dict__"):
            data["values"] = {str(k): type(v).__name__ for k, v in list(vars(obj).items())[:40]}
        return data

    def members(self, obj, public_only=True):
        names = []
        for name in dir(obj):
            if public_only and name.startswith("_"):
                continue
            names.append(name)
        return names[:200]

    def signature(self, func):
        code = getattr(func, "__code__", None)
        name = getattr(func, "__name__", type(func).__name__)
        if code is None:
            return {"name": name, "params": []}
        count = getattr(code, "co_argcount", 0)
        names = list(getattr(code, "co_varnames", ())[:count])
        defaults = getattr(func, "__defaults__", None) or ()
        required = len(names) - len(defaults)
        params = []
        for index, item in enumerate(names):
            default = None
            if index >= required:
                value = defaults[index - required]
                default = value if isinstance(value, (int, float, str, bool, type(None))) else repr(value)[:60]
            params.append({"name": item, "required": index < required, "default": default})
        return {"name": name, "params": params}

    def bind_behavior(self, widget_class, name, func):
        self._require(PluginPermission.UI_MUTATE, f"widget.bind.{name}",
                      "无改写控件类权限（绑定行为）")
        type.__setattr__(widget_class, str(name), func)
        return True

    def hook(self, name, callback, priority=100):
        self._require(PluginPermission.EVENT_LISTEN, "hook", "无监听事件权限")
        self._runtime.register_hook(str(name), self._filename, callback, priority)

    def register_action(self, scope, action_id, label, callback, icon=""):
        self._require(PluginPermission.UI_INJECT, "register_action", "无界面注入权限（注册工具栏按钮）")
        self._runtime.register_action(str(scope), str(action_id), str(label)[:64],
                                      self._filename, callback, str(icon or "")[:64])

    def _observe_contract(self, flag, detail, target=""):
        guard = self._internal_manager()
        if guard is None or self._plugin is None:
            return
        declared = int(getattr(self._plugin, "requested_permissions", 0) or 0)
        if declared & int(flag):
            return
        guard.note_observation(self._plugin, "contract.not_declared",
                               f"{detail}（未声明 {flag.name}，观察模式放行）",
                               "host", target)

    def register_project_type(self, type_id, name, description=""):
        self._observe_contract(PluginPermission.UI_INJECT,
                               f"注册项目类型 {type_id}", str(type_id))
        self._runtime.register_project_type(str(type_id), str(name)[:64], self._filename,
                                            str(description or "")[:200])

    def provide_service(self, name, handler):
        self._observe_contract(PluginPermission.PLUGIN_CALL,
                               f"发布服务 {name}", str(name))
        self._runtime.provide_service(str(name), self._filename, handler)

    def call_service(self, name, *args, **kwargs):
        self._observe_contract(PluginPermission.PLUGIN_CALL,
                               f"调用服务 {name}", str(name))
        plugin, handler = self._runtime.call_service(str(name))
        prev = _plugin_context.current_plugin
        _plugin_context.current_plugin = plugin
        try:
            return handler(*args, **kwargs)
        finally:
            _plugin_context.current_plugin = prev

    def has_service(self, name):
        return str(name) in self._runtime.services

    def list_services(self):
        return [{"name": key, "plugin": value[0]}
                for key, value in list(self._runtime.services.items())]

    def register_content_provider(self, kind, provider_id, handler):
        self._observe_contract(PluginPermission.PLUGIN_DATA_SHARE,
                               f"注册内容源 {kind}/{provider_id}", str(provider_id))
        self._runtime.register_content_provider(str(kind), str(provider_id),
                                                self._filename, handler)

    def register_weather_provider(self, provider_id, display_name, handler):
        self._observe_contract(PluginPermission.PLUGIN_DATA_SHARE,
                               f"注册天气源 {provider_id}", str(provider_id))
        self._runtime.register_weather_provider(str(provider_id), str(display_name),
                                                self._filename, handler)


class PluginHostRuntime(QObject):

    def __init__(self, server_name, plugin_dir, data_dir, config_path):
        super().__init__()
        self.server_name = server_name
        self.plugin_dir = os.path.abspath(plugin_dir)
        self.data_dir = os.path.abspath(data_dir)
        self.config_path = config_path or ""
        self.plugins = []
        self.by_file = {}
        self.widget_classes = {}
        self.windows = {}
        self.widget_configs = {}
        self.hooks = {}
        self.actions = {}
        self.project_types = {}
        self.services = {}
        self.providers = {}
        self.weather_providers = {}
        self.card_slots = {}
        self.denied_once = set()
        self._ask_seq = 0
        self._ask_waiters = {}
        self._ask_lock = threading.Lock()
        self._asking = threading.local()
        self._caller_tokens = {}
        self._buf = b""
        self.shim = _HostShimApp(self)
        self.guard = PluginManager(self.shim)
        self.shim.plugin_manager = self.guard
        self.guard.plugin_dir = self.plugin_dir
        self.guard.plugin_configs = self.widget_configs
        self.guard._auth_perms = {}
        self.guard._install_audit_hook()
        self.socket = QLocalSocket(self)
        self.socket.connected.connect(self._on_connected)
        self.socket.readyRead.connect(self._on_ready_read)
        self.socket.disconnected.connect(self._on_disconnected)
        self.socket.errorOccurred.connect(lambda *_: QApplication.quit())
        self._window_tokens = {}
        self._drag_state = None
        app = QApplication.instance()
        if app is not None:
            app.installEventFilter(self)
        self.socket.connectToServer(server_name)

    def register_caller_token(self, filename, token):
        with self._ask_lock:
            self._caller_tokens[str(token)] = str(filename)

    def send_line(self, payload):
        _audit_guard.active = True
        try:
            data = json.dumps(payload, ensure_ascii=False).encode("utf-8") + b"\n"
            self.socket.write(data)
            self.socket.flush()
        except Exception:
            pass
        finally:
            _audit_guard.active = False

    def send_event(self, name, params):
        self.send_line({"event": name, "params": params})

    def request_permission(self, filename, perm, feature, reason, origin, timeout_ms):
        if getattr(self._asking, "busy", False):
            return {"ok": False, "level": "none", "code": "busy"}
        self._asking.busy = True
        try:
            return self._ask_host(filename, perm, feature, reason, origin, timeout_ms)
        finally:
            self._asking.busy = False

    def _ask_host(self, filename, perm, feature, reason, origin, timeout_ms):
        self._ask_seq += 1
        rid = f"perm-{self._ask_seq}"
        waiter = {"event": threading.Event(), "box": {}}
        with self._ask_lock:
            self._ask_waiters[rid] = waiter
        self.send_line({"id": rid, "event": "permission_request", "params": {
            "plugin": filename, "perm": int(perm), "feature": str(feature or ""),
            "reason": str(reason or ""), "origin": str(origin or "explicit"),
            "timeout_ms": int(timeout_ms or 60000),
        }})
        limit_ms = max(1000, int(timeout_ms or 60000) + 2000)
        self._wait_response(waiter, limit_ms)
        with self._ask_lock:
            self._ask_waiters.pop(rid, None)
        if not waiter["event"].is_set():
            return {"ok": False, "level": "none", "code": "timeout"}
        result = waiter["box"].get("result") or {"ok": False, "level": "none", "code": "cancelled"}
        if not isinstance(result, dict):
            return {"ok": False, "level": "none", "code": "invalid"}
        return result

    def host_request(self, kind, params, timeout_ms=6000):
        payload = dict(params or {})
        token = str(payload.pop("_caller_token", "") or "")
        caller = getattr(_plugin_context, "current_plugin", None)
        caller_name = getattr(caller, "filename", None) if caller is not None else None
        if not caller_name and token:
            caller_name = self._caller_tokens.get(token)
        if caller_name:
            payload["plugin"] = caller_name
        else:
            payload.pop("plugin", None)
        self._ask_seq += 1
        rid = f"req-{self._ask_seq}"
        waiter = {"event": threading.Event(), "box": {}}
        with self._ask_lock:
            self._ask_waiters[rid] = waiter
        self.send_line({"id": rid, "event": str(kind),
                        "params": _host_jsonable(payload)})
        limit_ms = max(1000, int(timeout_ms or 6000) + 1500)
        self._wait_response(waiter, limit_ms)
        with self._ask_lock:
            self._ask_waiters.pop(rid, None)
        if not waiter["event"].is_set():
            return {"ok": False, "error": "timeout"}
        return waiter["box"].get("result")

    def report_register_error(self, plugin, message):
        self.send_event("register_error", {"plugin": plugin, "message": message})

    def get_config(self, filename, key, default=None):
        return (self.widget_configs.get(filename) or {}).get(key, default)

    def set_config(self, filename, key, value):
        if filename not in self.widget_configs:
            self.widget_configs[filename] = {}
        self.widget_configs[filename][key] = value
        self.send_event("config_set", {"plugin": filename, "key": str(key),
                                       "value": _host_jsonable(value)})

    def _on_connected(self):
        self.send_event("ready", {"protocol": _PLUGIN_HOST_PROTOCOL, "pid": os.getpid()})

    def _on_disconnected(self):
        QApplication.quit()

    def _drain_socket(self):
        try:
            chunk = bytes(self.socket.readAll())
        except Exception:
            chunk = b""
        if chunk:
            self._feed(chunk)

    def _feed(self, chunk):
        self._buf += chunk
        if len(self._buf) > _PLUGIN_HOST_MAX_LINE:
            self._buf = b""
            QApplication.quit()
            return
        while b"\n" in self._buf:
            line, self._buf = self._buf.split(b"\n", 1)
            if not line.strip():
                continue
            try:
                msg = json.loads(line.decode("utf-8"))
            except Exception:
                continue
            if not isinstance(msg, dict):
                continue
            self._handle(msg)

    def _wait_response(self, waiter, limit_ms):
        if threading.current_thread() is not threading.main_thread():
            waiter["event"].wait(max(1, int(limit_ms)) / 1000.0)
            return
        deadline = time.monotonic() + max(1, int(limit_ms)) / 1000.0
        app = QApplication.instance()
        while not waiter["event"].is_set():
            remaining = deadline - time.monotonic()
            if remaining <= 0:
                break
            if app is not None:
                app.processEvents(QEventLoop.ProcessEventsFlag.AllEvents, 12)
            try:
                self._drain_socket()
            except Exception:
                pass
            if waiter["event"].is_set():
                break
            waiter["event"].wait(0.006)

    def _on_ready_read(self):
        self._drain_socket()

    def _handle(self, msg):
        mid = msg.get("id")
        method = msg.get("method")
        params = msg.get("params") or {}
        if method is None:
            if mid is not None:
                with self._ask_lock:
                    waiter = self._ask_waiters.get(mid)
                if waiter is not None:
                    waiter["box"]["result"] = msg.get("result")
                    waiter["event"].set()
            return
        if not isinstance(params, dict):
            params = {}
        try:
            result = self._dispatch(method, params)
            if mid is not None:
                self.send_line({"id": mid, "result": result})
        except Exception as e:
            if mid is not None:
                self.send_line({"id": mid, "result": None,
                                "error": f"{type(e).__name__}: {e}"})

    def _dispatch(self, method, params):
        if method == "load_plugins":
            return self.load_plugins(params)
        if method == "enable_plugin":
            return self._set_enabled(params.get("plugin"), True)
        if method == "disable_plugin":
            return self._set_enabled(params.get("plugin"), False)
        if method == "set_grants":
            return self._set_grants(params.get("plugin"), params.get("permissions"),
                                    params.get("trusted"), params.get("grant_levels"),
                                    params.get("path_whitelist"))
        if method == "event":
            return self._plugin_event(params)
        if method == "create_widget":
            return self._create_widget(params)
        if method == "resize_widget":
            return self._resize_widget(params)
        if method == "destroy_widget":
            return self._destroy_widget(params)
        if method == "widget_call":
            return self._widget_call(params)
        if method == "hook":
            return self._run_hook(params)
        if method == "action":
            return self._run_action(params)
        if method == "content":
            return self._run_content(params)
        if method == "weather":
            return self._run_weather(params)
        if method == "set_theme":
            return self._set_theme(params)
        if method == "security_pause":
            self.shim.security_center_disabled = bool(params.get("paused"))
            return True
        if method == "set_options":
            self.shim.plugin_prompt_on_intercept = bool(
                params.get("intercept", self.shim.plugin_prompt_on_intercept))
            return True
        if method == "shutdown":
            QTimer.singleShot(0, QApplication.quit)
            return True
        return None

    def _set_enabled(self, filename, enabled):
        plugin = self.by_file.get(filename)
        if plugin is None:
            return False
        plugin.enabled = bool(enabled)
        plugin.enable_error = ""
        if enabled:
            _plugin_context.current_plugin = plugin
            try:
                fn = getattr(plugin, "on_enable", None)
                if callable(fn):
                    fn()
            except Exception as e:
                plugin.enable_error = str(e)
                self.send_event("log", {"plugin": filename, "message": perm_text("perm_enable_failed", error=e), "level": "ERROR"})
            finally:
                _plugin_context.current_plugin = None
        else:
            _plugin_context.current_plugin = plugin
            try:
                fn = getattr(plugin, "on_disable", None)
                if callable(fn):
                    fn()
            except Exception as e:
                self.send_event("log", {"plugin": filename, "message": f"禁用失败: {e}", "level": "ERROR"})
            finally:
                _plugin_context.current_plugin = None
        pump = QApplication.instance()
        if pump is not None:
            pump.processEvents(QEventLoop.ProcessEventsFlag.AllEvents, 8)
        self.send_event("plugin_state", {"plugin": filename, "enabled": bool(enabled),
                                        "error": plugin.enable_error})
        return True

    def _set_grants(self, filename, permissions, trusted=None, grant_levels=None,
                    path_whitelist=None):
        plugin = self.by_file.get(filename)
        if plugin is None:
            return False
        try:
            value = PluginPermission(int(permissions or 0))
        except Exception:
            value = PluginPermission.NONE
        plugin.permissions = value
        self.guard._auth_perms[filename] = int(value)
        self.guard.apply_grant_levels(filename, grant_levels)
        self.guard.apply_path_whitelist(filename, path_whitelist)
        if trusted is not None:
            self.guard.apply_trust(filename, bool(trusted))
        plugin.permissions = self.guard.permanent_permissions(plugin)
        return True

    def register_hook(self, name, filename, callback, priority=100):
        if name not in _PLUGIN_HOOK_NAMES or not callable(callback):
            raise ValueError(f"无效的钩子: {name}")
        try:
            prio = int(priority)
        except Exception:
            prio = 100
        bucket = self.hooks.setdefault(name, [])
        bucket[:] = [item for item in bucket if not (item[1] == filename and item[2] == callback)]
        bucket.append((prio, filename, callback))
        bucket.sort(key=lambda item: item[0])
        self.send_event("log", {"plugin": filename, "message": f"注册钩子: {name} (priority={prio})"})

    def register_action(self, scope, action_id, label, filename, callback, icon=""):
        if scope not in _PLUGIN_ACTION_SCOPES or not callable(callback):
            raise ValueError(f"无效的动作注册: {scope}")
        if not re.fullmatch(r"[A-Za-z0-9_\-.:]{1,64}", action_id):
            raise ValueError(f"非法动作 ID: {action_id}")
        key = f"{scope}:{filename}:{action_id}"
        self.actions[key] = (scope, filename, callback)
        self.send_event("action_register", {"scope": scope, "id": action_id,
                                            "label": label, "icon": icon,
                                            "plugin": filename})

    def register_project_type(self, type_id, name, filename, description=""):
        if not re.fullmatch(r"[A-Za-z0-9_\-.:]{1,64}", type_id):
            raise ValueError(f"非法项目类型 ID: {type_id}")
        self.project_types[type_id] = {"name": name, "plugin": filename,
                                       "description": description}
        self.send_event("project_type_register", {"id": type_id, "name": name,
                                                  "description": description,
                                                  "plugin": filename})

    def provide_service(self, name, filename, handler):
        if not re.fullmatch(r"[A-Za-z0-9_\-.:]{1,64}", str(name)):
            raise ValueError(f"非法服务名: {name}")
        if not callable(handler):
            raise TypeError("服务处理器必须可调用")
        self.services[str(name)] = (filename, handler)
        self.send_event("log", {"plugin": filename, "message": f"注册服务: {name}"})

    def call_service(self, name):
        entry = self.services.get(str(name))
        if entry is None:
            raise KeyError(f"服务不存在: {name}")
        filename, handler = entry
        plugin = self.by_file.get(filename)
        if plugin is None or not plugin.enabled:
            raise RuntimeError(f"服务提供者未启用: {name}")
        return plugin, handler

    def register_content_provider(self, kind, provider_id, filename, handler):
        if kind not in ("poem", "tip"):
            raise ValueError(f"不支持的内容类型: {kind}")
        if not re.fullmatch(r"[A-Za-z0-9_\-.:]{1,64}", str(provider_id)):
            raise ValueError(f"非法的内容源 ID: {provider_id}")
        if not callable(handler):
            raise TypeError("内容源必须可调用")
        bucket = self.providers.setdefault(kind, [])
        bucket[:] = [item for item in bucket if not (item[0] == provider_id and item[1] == filename)]
        bucket.append((str(provider_id), filename, handler))
        self.send_event("content_provider_register", {
            "kind": kind, "id": str(provider_id), "plugin": filename,
        })
        self.send_event("log", {"plugin": filename, "message": f"注册内容源: {kind}/{provider_id}"})

    def register_weather_provider(self, provider_id, name, filename, handler):
        if not re.fullmatch(r"[A-Za-z0-9_\-.:]{1,64}", str(provider_id)):
            raise ValueError(f"非法的天气源 ID: {provider_id}")
        if not callable(handler):
            raise TypeError("天气源必须可调用")
        self.weather_providers[str(provider_id)] = (filename, handler)
        self.send_event("weather_provider_register", {
            "id": str(provider_id), "name": str(name)[:64], "plugin": filename,
        })
        self.send_event("log", {"plugin": filename, "message": f"注册天气源: {name}"})

    def _run_weather(self, params):
        provider_id = str(params.get("provider") or "")
        city = str(params.get("city") or "")[:64]
        entry = self.weather_providers.get(provider_id)
        if entry is None:
            return {"text": ""}
        filename, handler = entry
        plugin = self.by_file.get(filename)
        if plugin is None or not plugin.enabled:
            return {"text": ""}
        _plugin_context.current_plugin = plugin
        try:
            text = handler(city)
        except Exception as e:
            self.send_event("log", {"plugin": filename, "level": "ERROR",
                                    "message": f"天气源 {provider_id} 执行失败: {e}"})
            return {"text": ""}
        finally:
            _plugin_context.current_plugin = None
        return {"text": str(text or "")[:500]}

    def _run_content(self, params):
        kind = str(params.get("kind") or "")
        payload = params.get("payload")
        if not isinstance(payload, dict):
            payload = {}
        for provider_id, filename, handler in list(self.providers.get(kind, [])):
            plugin = self.by_file.get(filename)
            if plugin is None or not plugin.enabled:
                continue
            _plugin_context.current_plugin = plugin
            try:
                text = handler(dict(payload))
            except Exception as e:
                self.send_event("log", {"plugin": filename, "level": "ERROR",
                                        "message": f"内容源 {provider_id} 执行失败: {e}"})
                continue
            finally:
                _plugin_context.current_plugin = None
            if isinstance(text, str) and text.strip():
                return {"text": text[:500], "provider": provider_id}
        return {"text": ""}

    def _run_hook(self, params):
        name = str(params.get("name") or "")
        if name not in _PLUGIN_HOOK_NAMES:
            return {"action": "allow"}
        context = params.get("context")
        if not isinstance(context, dict):
            context = {}
        merged = {}
        for _prio, filename, fn in list(self.hooks.get(name, [])):
            plugin = self.by_file.get(filename)
            if plugin is None or not plugin.enabled:
                continue
            _plugin_context.current_plugin = plugin
            try:
                result = fn(dict(context))
            except Exception as e:
                self.send_event("log", {"plugin": filename, "level": "ERROR",
                                        "message": f"钩子 {name} 执行失败: {e}"})
                continue
            finally:
                _plugin_context.current_plugin = None
            if not isinstance(result, dict):
                continue
            if result.get("action") == "deny":
                return {"action": "deny",
                        "reason": str(result.get("reason") or "")[:200],
                        "value": _host_jsonable(merged)}
            value = result.get("value")
            if result.get("action") == "modify" and isinstance(value, dict):
                merged.update({str(k): _host_jsonable(v) for k, v in list(value.items())[:32]})
        if merged:
            return {"action": "modify", "value": _host_jsonable(merged)}
        return {"action": "allow"}

    def _run_action(self, params):
        action_id = str(params.get("id") or "")
        scope = str(params.get("scope") or "")
        target = None
        for key, entry in self.actions.items():
            if entry[0] == scope and key.rsplit(":", 1)[-1] == action_id:
                target = entry
                break
        if target is None:
            return None
        _scope, filename, fn = target
        plugin = self.by_file.get(filename)
        if plugin is None or not plugin.enabled:
            return None
        context = params.get("context")
        if not isinstance(context, dict):
            context = {}
        _plugin_context.current_plugin = plugin
        try:
            fn(dict(context))
            return {"ok": True}
        except Exception as e:
            self.send_event("log", {"plugin": filename, "level": "ERROR",
                                    "message": f"动作 {action_id} 执行失败: {e}"})
            return {"ok": False, "error": str(e)[:200]}
        finally:
            _plugin_context.current_plugin = None

    def _plugin_event(self, params):
        name = str(params.get("name") or "")
        target = params.get("plugin")
        args = [_host_jsonable(a) for a in (params.get("args") or [])]
        kwargs = {str(k): _host_jsonable(v) for k, v in (params.get("kwargs") or {}).items()}
        done = 0
        for plugin in self.plugins:
            if target and plugin.filename != target:
                continue
            if not plugin.enabled:
                continue
            fn = getattr(plugin, name, None)
            if not callable(fn):
                continue
            _plugin_context.current_plugin = plugin
            try:
                fn(*args, **kwargs)
                done += 1
            except TypeError:
                try:
                    fn()
                    done += 1
                except Exception as e:
                    self.send_event("log", {"plugin": plugin.filename, "message": f"{name}: {e}", "level": "ERROR"})
            except Exception as e:
                self.send_event("log", {"plugin": plugin.filename, "message": f"{name}: {e}", "level": "ERROR"})
            finally:
                _plugin_context.current_plugin = None
        return done

    def _create_widget(self, params):
        kind = str(params.get("kind") or "")
        widget_id = str(params.get("id") or "")
        token = str(params.get("token") or "")
        existing = self.windows.get(token)
        if existing is not None:
            self.send_event("window_created", {"token": token, "wid": int(existing["win"].winId())})
            return True
        plugin = self.by_file.get(params.get("plugin"))
        if plugin is None or not plugin.enabled:
            raise RuntimeError("插件未启用")
        if kind == "info_widget":
            if plugin is None:
                raise RuntimeError("插件未加载")
            _plugin_context.current_plugin = plugin
            try:
                widget = plugin.get_info_widget(None)
            finally:
                _plugin_context.current_plugin = None
            if not isinstance(widget, QWidget):
                raise RuntimeError("插件未提供详情控件")
            widget.setParent(None)
        else:
            cls = self.widget_classes.get((kind, widget_id))
            if cls is None:
                raise RuntimeError("控件未注册")
            _plugin_context.current_plugin = plugin
            try:
                try:
                    widget = cls()
                except TypeError:
                    widget = cls(None)
            finally:
                _plugin_context.current_plugin = None
        win = QWidget()
        win.setWindowFlags(Qt.WindowType.FramelessWindowHint | Qt.WindowType.Tool)
        lay = QVBoxLayout(win)
        lay.setContentsMargins(0, 0, 0, 0)
        lay.setSpacing(0)
        lay.addWidget(widget)
        try:
            widget._host_token = token
        except Exception:
            pass
        win.resize(max(72, int(params.get("width") or 320)), max(56, int(params.get("height") or 240)))
        win.show()
        self.windows[token] = {"win": win, "widget": widget, "plugin": plugin, "kind": kind}
        self._window_tokens[id(win)] = token
        self.send_event("window_created", {"token": token, "wid": int(win.winId())})
        return True

    def _resize_widget(self, params):
        entry = self.windows.get(str(params.get("token") or ""))
        if entry is None:
            return False
        try:
            entry["win"].resize(max(1, int(params.get("width") or 1)),
                                max(1, int(params.get("height") or 1)))
        except Exception:
            return False
        return True

    def _destroy_widget(self, params):
        entry = self.windows.pop(str(params.get("token") or ""), None)
        if entry is None:
            return False
        self._window_tokens.pop(id(entry.get("win")), None)
        if self._drag_state is not None and self._drag_state.get("token") == str(params.get("token") or ""):
            self._drag_state = None
        try:
            entry["win"].hide()
            entry["win"].deleteLater()
        except Exception:
            pass
        return True

    def eventFilter(self, obj, event):
        try:
            etype = event.type()
            if etype not in (QEvent.Type.MouseButtonPress, QEvent.Type.MouseMove, QEvent.Type.MouseButtonRelease):
                return False
            win = obj.window()
        except Exception:
            return False
        token = self._window_tokens.get(id(win))
        if token is None:
            return False
        entry = self.windows.get(token)
        if entry is None or entry.get("kind") not in ("card_slot", "float_widget"):
            return False
        if etype == QEvent.Type.MouseButtonPress:
            if event.button() == Qt.MouseButton.LeftButton:
                edge_at = getattr(entry.get("widget"), "_resize_edge_at", None)
                if callable(edge_at):
                    try:
                        if edge_at(entry["widget"].mapFromGlobal(QCursor.pos())) is not None:
                            self._drag_state = None
                            return False
                    except Exception:
                        pass
                self._drag_state = {"token": token, "origin": QCursor.pos(), "active": False}
            return False
        state = self._drag_state
        if state is None or state.get("token") != token:
            return False
        if etype == QEvent.Type.MouseMove:
            if not (event.buttons() & Qt.MouseButton.LeftButton):
                return False
            pos = QCursor.pos()
            if not state["active"]:
                origin = state["origin"]
                if abs(pos.x() - origin.x()) < 3 and abs(pos.y() - origin.y()) < 3:
                    return False
                state["active"] = True
                self.send_event("widget_drag", {"token": token, "phase": "start",
                                                "x": pos.x(), "y": pos.y()})
                return False
            self.send_event("widget_drag", {"token": token, "phase": "move",
                                            "x": pos.x(), "y": pos.y()})
            return False
        if state.get("active"):
            pos = QCursor.pos()
            self.send_event("widget_drag", {"token": token, "phase": "end",
                                            "x": pos.x(), "y": pos.y()})
        self._drag_state = None
        return False

    def _widget_call(self, params):
        entry = self.windows.get(str(params.get("token") or ""))
        if entry is None:
            return False
        widget = entry["widget"]
        method = str(params.get("method") or "")
        if not method or method.startswith("_"):
            return False
        fn = getattr(widget, method, None)
        if not callable(fn):
            return False
        args = [_host_jsonable(a) for a in (params.get("args") or [])]
        kwargs = {str(k): _host_jsonable(v) for k, v in (params.get("kwargs") or {}).items()}
        _plugin_context.current_plugin = entry.get("plugin")
        try:
            fn(*args, **kwargs)
        except Exception:
            pass
        finally:
            _plugin_context.current_plugin = None
        return True

    def _set_theme(self, params):
        try:
            theme = Theme.from_dict(params.get("theme") or {})
        except Exception:
            return False
        self.shim.theme = theme
        self.shim.current_theme = theme.name
        mode = "dark" if getattr(theme, "is_dark", False) else "light"
        for entry in self.windows.values():
            widget = entry["widget"]
            fn = getattr(widget, "set_theme_mode", None)
            if callable(fn):
                try:
                    fn(mode)
                    continue
                except Exception:
                    pass
            fn = getattr(widget, "refresh_theme", None)
            if callable(fn):
                try:
                    fn()
                except Exception:
                    pass
        return True

    def _plugin_import(self, name, globals=None, locals=None, fromlist=(), level=0):
        top = str(name).split('.')[0]
        if top in _PLUGIN_HOST_BLOCKED:
            guard = getattr(self, "guard", None)
            owner = getattr(guard, "_loading_plugin", None)
            if globals:
                filename = str(globals.get("__file__") or "")
                base = os.path.basename(filename) if filename else ""
                if base:
                    for item in getattr(self, "plugins", []) or []:
                        if getattr(item, "filename", "") == base:
                            owner = item
                            break
            if owner is None and guard is not None:
                candidate, in_plugin = guard._scan_plugin_stack()
                if in_plugin:
                    owner = candidate
            owner_name = getattr(owner, "name", "") or "未知插件"
            self.report_register_error(top, f"已拦截危险模块导入: {name}")
            try:
                guard.app.append_security_event(owner_name, "block", "import", str(name), "禁止导入危险模块")
            except Exception:
                pass
            raise PluginHardBlockDenied(
                f"插件 '{owner_name}' 禁止导入模块: {name}", code="hard.blocked_module",
                capability="import", origin="import", plugin=owner_name, operation="import",
                target=str(name))
        return __import__(name, globals, locals, fromlist, level)

    def _order_by_manifest(self, names):
        deps = {}
        for filename in names:
            req = []
            manifest_path = os.path.join(self.plugin_dir, filename[:-3] + ".json")
            if os.path.isfile(manifest_path):
                try:
                    with open(manifest_path, "rb") as f:
                        raw = f.read(256 * 1024 + 1)
                    if len(raw) <= 256 * 1024:
                        data = json.loads(raw.decode("utf-8", errors="replace"))
                        if isinstance(data, dict) and isinstance(data.get("requires"), list):
                            req = [str(x) for x in data["requires"] if str(x)]
                except Exception:
                    pass
            deps[filename] = req
        errors = []
        blocked = set()
        for filename, req in deps.items():
            missing = [d for d in req if d not in deps]
            if missing:
                errors.append(f"{filename}: 缺少依赖 {', '.join(missing)}，已跳过加载")
                blocked.add(filename)
        state = {}
        ordered = []

        def visit(node, stack):
            status = state.get(node, 0)
            if status == 2:
                return
            if status == 1:
                errors.append(f"{node}: 检测到循环依赖 {' -> '.join(stack + [node])}")
                blocked.add(node)
                return
            state[node] = 1
            for dep in deps.get(node, []):
                if dep not in blocked and dep in deps:
                    visit(dep, stack + [node])
            state[node] = 2
            ordered.append(node)

        for name in names:
            visit(name, [])
        return ordered, errors, blocked

    def load_plugins(self, params):
        self.widget_configs.clear()
        cfg = params.get("configs") or {}
        if isinstance(cfg, dict):
            for key, value in cfg.items():
                if isinstance(value, dict):
                    self.widget_configs[str(key)] = dict(value)
        grants = params.get("grants") or {}
        self.guard._auth_perms = {}
        if isinstance(grants, dict):
            for key, value in grants.items():
                try:
                    self.guard._auth_perms[str(key)] = int(value)
                except Exception:
                    pass
        only = params.get("only")
        if isinstance(only, list):
            allowed = set(str(x) for x in only)
        else:
            allowed = None
        self.plugins = []
        self.by_file = {}
        self.widget_classes = {}
        self.hooks = {}
        self.actions = {}
        self.project_types = {}
        self.services = {}
        self.providers = {}
        self.weather_providers = {}
        self.card_slots = {}
        for entry in self.windows.values():
            try:
                entry["win"].close()
                entry["win"].deleteLater()
            except Exception:
                pass
        self.windows = {}
        self.guard.plugins = self.plugins
        errors = []
        self.guard._audit_suppress = True
        try:
            if self.plugin_dir not in sys.path:
                sys.path.append(self.plugin_dir)
            try:
                names = sorted(os.listdir(self.plugin_dir))
            except Exception as e:
                names = []
                errors.append(f"目录读取失败: {e}")
            names = [n for n in names if n.endswith(".py") and not n.startswith("_")]
            names, dep_errors, blocked = self._order_by_manifest(names)
            errors.extend(dep_errors)
            for filename in names:
                if filename in blocked:
                    continue
                if allowed is not None and filename not in allowed:
                    continue
                filepath = os.path.join(self.plugin_dir, filename)
                module_name = filename[:-3]
                try:
                    with open(filepath, "rb") as f:
                        raw = f.read(2 * 1024 * 1024 + 1)
                    if len(raw) > 2 * 1024 * 1024:
                        errors.append(f"{filename}: 文件超过 2MB，已拒绝加载")
                        continue
                    source = raw.decode("utf-8", errors="replace")
                    risky = [p for p in _PLUGIN_HOST_RISK_PATTERNS if p in source]
                    if risky:
                        reason = f"检测到沙箱逃逸特征，已阻止加载: {', '.join(risky)}"
                        errors.append(f"{filename}: {reason}")
                        self.send_event("log", {"plugin": filename, "message": reason, "level": "ERROR"})
                        self.send_event("security", {"plugin": filename, "kind": "block",
                                                     "event": "plugin_load", "target": filename,
                                                     "reason": "沙箱逃逸特征"})
                        continue
                    warnings = [p for p in _PLUGIN_HOST_WARN_PATTERNS if p in source]
                    if warnings:
                        self.send_event("log", {"plugin": filename, "level": "WARNING",
                                                "message": f"插件包含高风险调用: {', '.join(warnings)}"})
                        self.send_event("security", {"plugin": filename, "kind": "warn",
                                                     "event": "plugin_load", "target": filename,
                                                     "reason": f"高风险调用: {', '.join(warnings)}"})
                    code = compile(source, filepath, "exec")
                    spec = importlib.util.spec_from_file_location(module_name, filepath)
                    module = importlib.util.module_from_spec(spec)
                    module.__builtins__ = _host_safe_builtins(self._plugin_import)
                    module.Plugin = Plugin
                    module.PluginPermission = PluginPermission
                    module.__file__ = filepath
                    ident = Plugin()
                    ident.name = module_name
                    ident.filename = filename
                    ident.enabled = True
                    ident.permissions = PluginPermission.NONE
                    prev = self.guard._loading_plugin
                    self.guard._loading_plugin = ident
                    _plugin_context.current_plugin = ident
                    api = HostPluginAPI(self, filename)
                    try:
                        exec(code, module.__dict__)
                        self.guard.seal_module_widgets(module, filename)
                        setup = getattr(module, "setup", None)
                        if not callable(setup):
                            errors.append(f"{filename}: 缺少 setup() 函数")
                            continue
                        instance = setup(self.shim, api)
                        if not isinstance(instance, Plugin):
                            errors.append(f"{filename}: setup() 未返回 Plugin 实例")
                            continue
                    finally:
                        _plugin_context.current_plugin = None
                        self.guard._loading_plugin = prev
                    manifest, merr = read_plugin_manifest(self.plugin_dir, module_name)
                    if merr:
                        errors.append(f"{filename}: {merr}")
                    if manifest:
                        api_version = manifest.get("api_version")
                        if isinstance(api_version, int) and api_version > _PLUGIN_HOST_PROTOCOL:
                            errors.append(f"{filename}: 需要插件 API v{api_version}，当前仅支持 v{_PLUGIN_HOST_PROTOCOL}")
                            continue
                    apply_plugin_manifest(instance, manifest)
                    instance.app = self.shim
                    instance.api = api
                    instance.filename = filename
                    instance.enabled = False
                    api.bind(instance)
                    self.plugins.append(instance)
                    self.by_file[filename] = instance
                except Exception as e:
                    errors.append(f"{filename}: {type(e).__name__}: {e}")
                    self.send_event("log", {"plugin": filename, "message": f"加载失败: {e}", "level": "ERROR"})
                pump = QApplication.instance()
                if pump is not None:
                    pump.processEvents(QEventLoop.ProcessEventsFlag.AllEvents, 8)
            try:
                sys.path.remove(self.plugin_dir)
            except ValueError:
                pass
        finally:
            self.guard._audit_suppress = False
            self.guard._loading_plugin = None
        states = params.get("states") or {}
        if isinstance(states, dict):
            for plugin in self.plugins:
                state = states.get(plugin.filename) or {}
                try:
                    plugin.enabled = bool(state.get("enabled"))
                except Exception:
                    plugin.enabled = False
                if plugin.filename in self.guard._auth_perms:
                    plugin.permissions = PluginPermission(self.guard._auth_perms[plugin.filename])
        return {"plugins": [self._meta(p) for p in self.plugins], "errors": errors}

    def _meta(self, plugin):
        return {
            "name": getattr(plugin, "name", ""),
            "version": getattr(plugin, "version", "0.1"),
            "author": getattr(plugin, "author", "Unknown"),
            "description": getattr(plugin, "description", ""),
            "filename": getattr(plugin, "filename", ""),
            "requested_permissions": int(getattr(plugin, "requested_permissions", 0) or 0),
            "permissions": int(getattr(plugin, "permissions", 0) or 0),
            "baseline_permissions": int(getattr(plugin, "baseline_permissions", 0) or 0),
            "ondemand_permissions": int(getattr(plugin, "ondemand_permissions", 0) or 0),
            "permission_specs": dict(getattr(plugin, "permission_specs", {}) or {}),
            "permission_warnings": list(getattr(plugin, "permission_warnings", []) or []),
            "permission_legacy": bool(getattr(plugin, "permission_legacy", False)),
            "trusted": bool(getattr(plugin, "trusted", False)),
            "signature_verified": bool(getattr(plugin, "signature_verified", False)),
            "enabled": bool(getattr(plugin, "enabled", False)),
            "has_info_widget": getattr(type(plugin), "get_info_widget", None) is not Plugin.get_info_widget,
        }


def run_plugin_host(argv):
    server_name = ""
    plugin_dir = ""
    data_dir = ""
    config_path = ""
    if _PLUGIN_HOST_FLAG in argv:
        idx = argv.index(_PLUGIN_HOST_FLAG)
        rest = argv[idx + 1:]
        if len(rest) >= 3:
            server_name, plugin_dir, data_dir = rest[0], rest[1], rest[2]
        if len(rest) >= 4:
            config_path = rest[3]
    if not server_name or not plugin_dir:
        return
    main_module = sys.modules.get("__main__")
    if main_module is not None:
        sys.modules.setdefault("djs_pyqt6", main_module)
    app = QApplication(sys.argv[:1])
    app.setApplicationName("DJS Plugin Host")
    app.setQuitOnLastWindowClosed(False)
    runtime = PluginHostRuntime(server_name, plugin_dir, data_dir, config_path)
    app._djs_plugin_runtime = runtime
    app.exec()


# 主题类
class Theme:
    def __init__(self, name="默认主题", is_dark=False,
                 bg_color="#f5f7fa", frame_bg="#ffffff", accent_color="#3498db",
                 text_color="#2c3e50", border_color="#d1d8e0",
                 font_family="Microsoft YaHei", font_size=9,
                 window_round_radius=15,
                 window_brightness=1.0,
                 window_saturation=1.0):
        self.name = name
        self.is_dark = is_dark
        self.bg_color = bg_color
        self.frame_bg = frame_bg
        self.accent_color = accent_color
        self.text_color = text_color
        self.border_color = border_color
        self.font_family = font_family
        self.font_size = font_size
        self.window_round_radius = window_round_radius
        self.window_brightness = window_brightness
        self.window_saturation = window_saturation

    def to_dict(self):
        return {
            "name": self.name,
            "is_dark": self.is_dark,
            "bg_color": self.bg_color,
            "frame_bg": self.frame_bg,
            "accent_color": self.accent_color,
            "text_color": self.text_color,
            "border_color": self.border_color,
            "font_family": self.font_family,
            "font_size": self.font_size,
            "window_round_radius": self.window_round_radius,
            "window_brightness": self.window_brightness,
            "window_saturation": self.window_saturation
        }

    @staticmethod
    def from_dict(data):
        return Theme(
            data.get("name", ""),
            data.get("is_dark", False),
            data.get("bg_color", "#f5f7fa"),
            data.get("frame_bg", "#ffffff"),
            data.get("accent_color", "#3498db"),
            data.get("text_color", "#2c3e50"),
            data.get("border_color", "#d1d8e0"),
            data.get("font_family", "Microsoft YaHei"),
            data.get("font_size", 9),
            data.get("window_round_radius", 15),
            data.get("window_brightness", 1.0),
            data.get("window_saturation", 1.0)
        )


