def apply_theme_palette(theme):
    tc = get_theme_colors(theme)
    pal = QPalette()
    bg = QColor(tc["bg_color"])
    panel = QColor(tc["panel_bg"])
    base = QColor(tc["input_bg"])
    text = QColor(tc["text_color"])
    secondary = QColor(tc["secondary_text"])
    accent = QColor(tc["accent"])
    on_accent = QColor(tc["selected_text"])
    border = QColor(tc["border_color"])
    deep = QColor(tc["dark_bg"])
    pal.setColor(QPalette.ColorRole.Window, bg)
    pal.setColor(QPalette.ColorRole.WindowText, text)
    pal.setColor(QPalette.ColorRole.Base, base)
    pal.setColor(QPalette.ColorRole.AlternateBase, QColor(tc["alternate_bg"]))
    pal.setColor(QPalette.ColorRole.Text, text)
    pal.setColor(QPalette.ColorRole.Button, panel)
    pal.setColor(QPalette.ColorRole.ButtonText, text)
    pal.setColor(QPalette.ColorRole.ToolTipBase, panel)
    pal.setColor(QPalette.ColorRole.ToolTipText, text)
    pal.setColor(QPalette.ColorRole.Highlight, accent)
    pal.setColor(QPalette.ColorRole.HighlightedText, on_accent)
    pal.setColor(QPalette.ColorRole.PlaceholderText, secondary)
    pal.setColor(QPalette.ColorRole.Link, accent)
    pal.setColor(QPalette.ColorRole.LinkVisited, QColor(tc["hover_accent"]))
    pal.setColor(QPalette.ColorRole.BrightText, QColor(tc["danger"]))
    pal.setColor(QPalette.ColorRole.Light, panel)
    pal.setColor(QPalette.ColorRole.Midlight, border)
    pal.setColor(QPalette.ColorRole.Mid, border)
    pal.setColor(QPalette.ColorRole.Dark, deep)
    pal.setColor(QPalette.ColorRole.Shadow, deep)
    for role in (QPalette.ColorRole.WindowText, QPalette.ColorRole.Text,
                 QPalette.ColorRole.ButtonText, QPalette.ColorRole.HighlightedText,
                 QPalette.ColorRole.Link, QPalette.ColorRole.LinkVisited):
        pal.setColor(QPalette.ColorGroup.Disabled, role, secondary)
    pal.setColor(QPalette.ColorGroup.Disabled, QPalette.ColorRole.Window, bg)
    pal.setColor(QPalette.ColorGroup.Disabled, QPalette.ColorRole.Base, QColor(tc["alternate_bg"]))
    pal.setColor(QPalette.ColorGroup.Disabled, QPalette.ColorRole.Button, panel)
    try:
        app = QApplication.instance()
        if app is not None:
            app.setPalette(pal)
    except Exception as e:
        log_message(f"应用调色板失败: {e}", "WARNING")
    return pal


_spec_tokens_cache = {}

def get_spec_tokens(is_dark):
    key = bool(is_dark)
    if key not in _spec_tokens_cache:
        if key:
            tokens = {
                "digit_bg_top": "#232634",
                "digit_bg_bottom": "#1A1D27",
                "digit_text": "#ECEEF4",
                "digit_border": QColor(236, 238, 244, 42),
                "caret": "#FBBF24",
                "due": "#F43F5E",
                "accent": "#FBBF24",
                "accent_deep": "#D97706",
                "colon": "#8B90A0",
            }
        else:
            tokens = {
                "digit_bg_top": "#FFFFFF",
                "digit_bg_bottom": "#EEF0F4",
                "digit_text": "#12141C",
                "digit_border": QColor(18, 20, 28, 38),
                "caret": "#D97706",
                "due": "#F43F5E",
                "accent": "#D97706",
                "accent_deep": "#B45309",
                "colon": "#5C6270",
            }
        tokens["type_ms"] = 70
        tokens["delete_ms"] = 20
        tokens["hold_ms"] = 2400
        _spec_tokens_cache[key] = tokens
    return _spec_tokens_cache[key]

_num_font_family = None
_poem_font_family = None

def resolve_num_font_family():
    global _num_font_family
    if _num_font_family is None:
        preferred = ["Bahnschrift", "DIN Condensed", "Bahnschrift Condensed", "Arial Narrow"]
        try:
            available = set(QFontDatabase.families())
            _num_font_family = next((f for f in preferred if f in available), "Microsoft YaHei")
        except Exception:
            _num_font_family = "Microsoft YaHei"
    return _num_font_family

def resolve_poem_font_family():
    global _poem_font_family
    if _poem_font_family is None:
        preferred = ["KaiTi", "STKaiti", "Kaiti SC", "SimSun", "Microsoft YaHei"]
        try:
            available = set(QFontDatabase.families())
            _poem_font_family = next((f for f in preferred if f in available), "Microsoft YaHei")
        except Exception:
            _poem_font_family = "Microsoft YaHei"
    return _poem_font_family

def make_num_font(pixel_size=None, point_size=None, bold=True):
    font = QFont(resolve_num_font_family())
    if pixel_size is not None:
        font.setPixelSize(int(pixel_size))
    if point_size is not None:
        font.setPointSize(point_size)
    font.setBold(bold)
    font.setStyleStrategy(QFont.StyleStrategy.PreferAntialias | QFont.StyleStrategy.PreferQuality)
    return font

class SystemThemeMonitor(QObject):
    theme_changed = pyqtSignal(bool)

    def __init__(self, parent=None):
        super().__init__(parent)
        self._current_dark = is_system_dark()
        self._timer = QTimer(self)
        self._timer.timeout.connect(self._check_theme)
        self._timer.start(2000)

    def _check_theme(self):
        new_dark = is_system_dark()
        if new_dark != self._current_dark:
            self._current_dark = new_dark
            self.theme_changed.emit(new_dark)

def _strict_bool(value):
    if isinstance(value, bool):
        return value
    if isinstance(value, str):
        return value.strip().lower() in ("1", "true", "yes", "on", "是", "开启")
    return bool(value)

class CountdownProject:
    def __init__(self, name="新项目", target_date="", target_time="00:00", show_both=True,
                 font_size=28, bg_color=None, font_color=None,
                 position=None, size=None,
                 screen_width=1920, screen_height=1080, always_on_top=True, auto_font=True,
                 background_type="color", background_image="", window_alpha=1.0,
                 project_type="normal", pomodoro_work=25, pomodoro_break=5, pomodoro_long_break=15,
                 pomodoro_cycles=4,
                 custom_layout=None, fullscreen_layout=None, window_round_radius=18,
                 use_neon=True, neon_start="#43e97b", neon_end="#38f9d7", neon_glow="#38f9d7",
                 weather_city="",
                 gradient_start=None, gradient_end=None,
                 dynamic_bg_type="particles", dynamic_fps=30, dynamic_quality="high", graphics_preset="high",
                 typewriter_interval=15, tip_interval=15, expired_text="已到期",
                 display_format="decimal", display_format_template="{days}天 {hours}时 {minutes}分",
                 click_through=False, recur_weekdays=None, recur_end_date="",
                 recur_mode="weekly", recur_monthday=1, recur_year_month=1, recur_year_day=1,
                 enable_end_sound=True, end_sound_mode="windchime", custom_sound_path="",
                 window_locked=False, fullscreen_layouts=None, bg_settings=None,
                 window_material="solid", window_border_enabled=False,
                 window_border_color="#5B8DEF", window_border_width=2,
                 skin_id="", skin_mode="auto", skin_variant=""):
        self.project_type = project_type
        self.click_through = _strict_bool(click_through)
        self.window_locked = _strict_bool(window_locked)
        self.recur_weekdays = recur_weekdays or []
        self.recur_end_date = recur_end_date
        self.recur_mode = recur_mode if recur_mode in ("weekly", "monthly", "yearly") else "weekly"
        try:
            self.recur_monthday = max(1, min(31, int(recur_monthday)))
        except (TypeError, ValueError):
            self.recur_monthday = 1
        try:
            self.recur_year_month = max(1, min(12, int(recur_year_month)))
        except (TypeError, ValueError):
            self.recur_year_month = 1
        try:
            self.recur_year_day = max(1, min(31, int(recur_year_day)))
        except (TypeError, ValueError):
            self.recur_year_day = 1
        self.enable_end_sound = enable_end_sound
        self.end_sound_mode = end_sound_mode
        self.custom_sound_path = custom_sound_path
        self.pomodoro_work = pomodoro_work
        self.pomodoro_break = pomodoro_break
        self.pomodoro_long_break = pomodoro_long_break
        self.pomodoro_cycles = pomodoro_cycles
        self.custom_layout = custom_layout or {}
        self.fullscreen_layout = fullscreen_layout or {}
        self.fullscreen_layouts = fullscreen_layouts or {}
        if not self.fullscreen_layouts and self.fullscreen_layout:
            self.fullscreen_layouts["default"] = self.fullscreen_layout
        self.window_round_radius = window_round_radius
        self.use_neon = use_neon
        self.neon_start = neon_start
        self.neon_end = neon_end
        self.neon_glow = neon_glow
        self.weather_city = weather_city
        self.typewriter_interval = typewriter_interval
        self.tip_interval = tip_interval
        self.expired_text = expired_text
        self.display_format = display_format
        self.display_format_template = display_format_template
        if gradient_start is None:
            gradient_start = "#0a0a1a" if is_system_dark() else "#f5f0e8"
        if gradient_end is None:
            gradient_end = "#1a1040" if is_system_dark() else "#e2ecf5"
        self.gradient_start = gradient_start
        self.gradient_end = gradient_end
        self.dynamic_bg_type = dynamic_bg_type
        self.dynamic_fps = dynamic_fps
        self.dynamic_quality = dynamic_quality
        self.graphics_preset = graphics_preset
        self.bg_settings = bg_settings or {}
        self.name = name
        self.target_date = target_date or (datetime.now() + timedelta(days=30)).strftime("%Y-%m-%d")
        self.target_time = target_time or "00:00"
        self.show_both = show_both
        self.font_size = font_size
        if bg_color is None:
            bg_color = "#0a0a1a" if is_system_dark() else "#f5f7fa"
        if font_color is None:
            font_color = "#c0c8f0" if is_system_dark() else "#2c3e50"
        self.bg_color = bg_color
        self.font_color = font_color
        self.size = size or self.get_default_size(screen_width, screen_height)
        if position is None:
            try:
                geo = QApplication.primaryScreen().availableGeometry()
                self.position = (geo.right() + 1 - self.size[0] - 24,
                                 geo.top() + max(0, (geo.height() - self.size[1]) // 2))
            except Exception:
                self.position = (screen_width - self.size[0] - 80, 80)
        else:
            self.position = position
        self.always_on_top = always_on_top
        self.auto_font = auto_font
        self.background_type = background_type
        self.background_image = background_image
        self.window_alpha = window_alpha
        self.window_material = window_material if window_material in ("glass", "frost", "solid") else "solid"
        self.window_border_enabled = _strict_bool(window_border_enabled)
        self.window_border_color = window_border_color or "#5B8DEF"
        try:
            self.window_border_width = max(1, min(20, int(window_border_width)))
        except (TypeError, ValueError):
            self.window_border_width = 2
        self.skin_id = skin_id or ""
        self.skin_mode = skin_mode if skin_mode in ("manual", "auto", "system") else "auto"
        self.skin_variant = skin_variant if skin_variant in ("light", "dark") else ""

    def get_default_size(self, screen_width, screen_height):
        width = max(360, min(460, int(screen_width * 0.24)))
        height = max(220, min(300, int(screen_height * 0.28)))
        return (int(width), int(height))

