_LAYOUT_THEME_DEFAULTS = {
    ("name", "color"): {"dark": "#FFFFFF", "light": "#1B1D24"},
    ("name", "bg_color"): {"dark": "rgba(18,20,28,0.42)", "light": "rgba(255,255,255,0.52)"},
    ("static_text", "color"): {"dark": "#E0E0E0", "light": "#3A3F4A"},
    ("countdown", "color"): {"dark": "#FFFFFF", "light": "#1B1D24"},
    ("countdown", "bg_color"): {"dark": "rgba(18,20,28,0.55)", "light": "rgba(255,255,255,0.44)"},
    ("countdown", "stroke_color"): {"dark": "rgba(236,238,244,0.22)", "light": "rgba(255,255,255,0.9)"},
    ("poem", "color"): {"dark": "#D0D0D0", "light": "#3A3F4A"},
    ("tip", "color"): {"dark": "#D0D0D0", "light": "#3A3F4A"},
}

def _hex_luminance(color_str):
    try:
        c = QColor(color_str)
        if not c.isValid():
            return 0.5
        return (0.299 * c.red() + 0.587 * c.green() + 0.114 * c.blue()) / 255.0
    except Exception:
        return 0.5

def normalize_layout_theme_colors(project):
    if project.background_type == "gradient":
        lum = (_hex_luminance(project.gradient_start) + _hex_luminance(project.gradient_end)) / 2.0
    elif project.background_type == "color":
        lum = _hex_luminance(project.bg_color)
    else:
        return
    want_key = "dark" if lum < 0.5 else "light"
    other_key = "light" if want_key == "dark" else "dark"
    layouts = [project.custom_layout]
    fs = getattr(project, "fullscreen_layouts", None) or {}
    if "default" in fs:
        layouts.append(fs["default"])
    for layout in layouts:
        if not layout:
            continue
        for (eid, field), colors in _LAYOUT_THEME_DEFAULTS.items():
            cfg = layout.get(eid)
            if not cfg:
                continue
            cur_val = cfg.get(field)
            if cur_val and cur_val == colors.get(other_key):
                cfg[field] = colors.get(want_key, cur_val)

_AUTO_INK_LIGHT = "#12141C"
_AUTO_INK_DARK = "#F1F4F9"
_AUTO_TEXT_ELEMENTS = ("poem", "tip")
_AUTO_COLOR_SENTINELS = ("", "#FFFFFF", "#D0D0D0", "#333333", "#3A3F4A", "#E0E0E0", "#1B1D24", "#F1F4F9")
_BG_LUM_CACHE = {}


def _image_luminance(path):
    if not path:
        return None
    candidates = [path]
    try:
        candidates.append(os.path.join(resource_path("data"), path))
        candidates.append(os.path.join(resource_path("data"), "user", path))
        candidates.append(os.path.join(resource_path("data"), "backgrounds", path))
    except Exception:
        pass
    for cand in candidates:
        try:
            if not os.path.isfile(cand):
                continue
            key = (os.path.abspath(cand), os.path.getmtime(cand))
            if key in _BG_LUM_CACHE:
                return _BG_LUM_CACHE[key]
            img = QImage(cand)
            if img.isNull():
                continue
            img = img.scaled(1, 1, Qt.AspectRatioMode.IgnoreAspectRatio, Qt.TransformationMode.SmoothTransformation)
            c = img.pixelColor(0, 0)
            if c.alpha() == 0:
                continue
            lum = (0.299 * c.red() + 0.587 * c.green() + 0.114 * c.blue()) / 255.0
            _BG_LUM_CACHE[key] = lum
            return lum
        except Exception:
            continue
    return None


def project_bg_luminance(project):
    try:
        bg_type = getattr(project, "background_type", "color")
        if bg_type == "gradient":
            return (_hex_luminance(getattr(project, "gradient_start", "#FFFFFF"))
                    + _hex_luminance(getattr(project, "gradient_end", "#000000"))) / 2.0
        if bg_type == "color":
            return _hex_luminance(getattr(project, "bg_color", "#FFFFFF"))
        if bg_type == "image":
            lum = _image_luminance(getattr(project, "background_image", ""))
            if lum is not None:
                return lum
        if bg_type == "transparent":
            return 0.1 if is_system_dark() else 0.9
        if bg_type == "dynamic":
            dyn = getattr(project, "dynamic_bg_type", "")
            return 0.35 if dyn == "sky" else 0.12
    except Exception:
        pass
    return 0.5


def auto_text_color(project):
    return _AUTO_INK_LIGHT if project_bg_luminance(project) >= 0.55 else _AUTO_INK_DARK


def resolve_elem_text_color(project, elem_id, cfg, fallback):
    color = cfg.get("color") or fallback
    if elem_id not in _AUTO_TEXT_ELEMENTS:
        return color
    auto = cfg.get("auto_color")
    if auto is False:
        return color
    if auto is True or (color or "").upper() in _AUTO_COLOR_SENTINELS:
        return auto_text_color(project)
    return color

SKIN_CLASSIC_ID = "classic"
SKIN_SNAPSHOT_FIELDS = (
    "background_type", "bg_color", "gradient_start", "gradient_end",
    "background_image", "dynamic_bg_type", "dynamic_quality", "dynamic_fps",
    "window_alpha", "window_material", "window_round_radius",
    "window_border_enabled", "window_border_color", "window_border_width",
    "font_color", "use_neon", "neon_start", "neon_end", "neon_glow", "auto_font",
    "display_format", "display_format_template"
)


def skin_snapshot_from_project(project):
    snap = {}
    for key in SKIN_SNAPSHOT_FIELDS:
        snap[key] = getattr(project, key, None)
    snap["custom_layout"] = json.loads(json.dumps(project.custom_layout or {}))
    return snap


def apply_skin_snapshot(project, snap):
    for key in SKIN_SNAPSHOT_FIELDS:
        if key in snap:
            setattr(project, key, snap.get(key))
    project.custom_layout = json.loads(json.dumps(snap.get("custom_layout") or {}))


