class TipHintWidget(QWidget):
    def __init__(self, parent=None):
        super().__init__(parent)
        self.setMinimumWidth(180)
        self.setSizePolicy(QSizePolicy.Policy.Expanding, QSizePolicy.Policy.Fixed)
        self.setFixedHeight(32)
        self.tip_text = ""
        self.tip_timer = QTimer(self)
        self.tip_timer.timeout.connect(self.rotate_tip)
        self.tip_timer.start(5500)

    def rotate_tip(self):
        self.tip_text = random.choice(TIPS_DATA)
        self.update()

    def paintEvent(self, event):
        painter = QPainter(self)
        painter.setRenderHint(QPainter.RenderHint.Antialiasing)
        painter.setFont(QFont("Microsoft YaHei", 9))
        painter.setPen(QColor("#ffffff"))
        painter.drawText(self.rect(), Qt.AlignmentFlag.AlignCenter | Qt.TextFlag.TextWordWrap, self.tip_text)

    def sizeHint(self):
        return QSize(220, 32)

class PomodoroWidget(QWidget):
    _PHASE_LABELS = {"work": "专注", "short": "短休", "long": "长休"}
    _float_draggable = False
    theme_mode = "system"
    _SOUND_FILES = {
        "windchime": "windchime.wav", "piano": "piano_ding.wav",
        "double_ding": "double_ding.wav", "urgent_beep": "urgent_beep.wav",
        "long_buzz": "long_buzz.wav", "alarm_rise": "alarm_rise.wav",
        "ocean_wave": "ocean_wave.wav", "synth_arp": "synth_arp.wav",
    }

    def __init__(self, parent=None, work_mins=25, break_mins=5, long_break_mins=15, cycles=4):
        super().__init__(parent)
        self.setMinimumSize(72, 72)
        self.setMouseTracking(True)
        self.setAttribute(Qt.WidgetAttribute.WA_TranslucentBackground, True)
        self.is_running = False
        self.phase = "work"
        self.cycle_done = 0
        self.work_time = max(1, int(work_mins)) * 60
        self.break_time = max(1, int(break_mins)) * 60
        self.long_break_time = max(1, int(long_break_mins)) * 60
        self.cycles = max(2, int(cycles))
        self.total_time = self.work_time
        self.time_left = self.total_time
        self.palette_name = "slate"
        self.show_ticks = True
        self.auto_next = False
        self.sound_enabled = True
        self.preview_mode = False
        self.master = None
        self.project = None
        self._hover = False
        self._press_pos = None
        self._last_drag_pos = QPoint()
        self._drag_moved = False
        self.timer = QTimer(self)
        self.timer.timeout.connect(self.update_time)

    def sizeHint(self):
        return QSize(112, 112)

    def set_sound_source(self, master, project=None):
        self.master = master
        self.project = project

    def set_palette(self, name):
        self.palette_name = name or "slate"
        self.update()

    def set_show_ticks(self, enabled):
        self.show_ticks = bool(enabled)
        self.update()

    def set_auto_next(self, enabled):
        self.auto_next = bool(enabled)

    def set_sound_enabled(self, enabled):
        self.sound_enabled = bool(enabled)

    def update_settings(self, work_mins, break_mins, long_break_mins=None, cycles=None):
        old_total = self._phase_seconds()
        self.work_time = max(1, int(work_mins)) * 60
        self.break_time = max(1, int(break_mins)) * 60
        if long_break_mins is not None:
            self.long_break_time = max(1, int(long_break_mins)) * 60
        if cycles is not None:
            self.cycles = max(2, int(cycles))
        if self.is_running:
            return
        new_total = self._phase_seconds()
        if new_total != old_total:
            self.total_time = new_total
            self.time_left = new_total
        self.update()

    def _phase_seconds(self):
        if self.phase == "work":
            return self.work_time
        if self.phase == "long":
            return self.long_break_time
        return self.break_time

    def reset_phase(self):
        self.timer.stop()
        self.is_running = False
        self.total_time = self._phase_seconds()
        self.time_left = self.total_time
        self.update()
        self._emit_lifecycle_hook("timer_reset")

    def reset_all(self):
        self.timer.stop()
        self.is_running = False
        self.phase = "work"
        self.cycle_done = 0
        self.total_time = self.work_time
        self.time_left = self.total_time
        self.update()
        self._emit_lifecycle_hook("timer_reset")

    def skip_phase(self):
        self.timer.stop()
        self.is_running = False
        self._advance_phase(auto=False, sound=False)
        self.update()

    def toggle_run(self):
        if self.is_running:
            self.timer.stop()
            self.is_running = False
            self._emit_lifecycle_hook("timer_pause")
        else:
            if self.time_left <= 0:
                self._advance_phase(auto=False, sound=False)
            self.timer.start(1000)
            self.is_running = True
            self._emit_lifecycle_hook("timer_start")
        self.update()

    def _emit_lifecycle_hook(self, name):
        pm = getattr(self.master, 'plugin_manager', None) if self.master is not None else None
        if pm is None:
            return
        try:
            pm.emit_hook(name, {"phase": self.phase, "running": self.is_running,
                                "project": getattr(self.project, 'name', '')})
        except Exception:
            pass

    def _advance_phase(self, auto=None, sound=True):
        if self.phase == "work":
            self.cycle_done += 1
            if self.cycle_done >= self.cycles:
                self.cycle_done = 0
                self.phase = "long"
            else:
                self.phase = "short"
        else:
            self.phase = "work"
        self.total_time = self._phase_seconds()
        self.time_left = self.total_time
        run = self.auto_next if auto is None else auto
        if run:
            self.timer.start(1000)
            self.is_running = True
        else:
            self.is_running = False
        if sound:
            self._play_sound()

    def _play_sound(self):
        if not self.sound_enabled or self.preview_mode:
            return
        master = self.master
        if master is None:
            p = self.parent()
            master = getattr(p, "master", None)
            if self.project is None:
                self.project = getattr(p, "project", None)
        if master is None:
            return
        proj = self.project
        if proj is None:
            projs = getattr(master, "projects", []) or []
            proj = projs[0] if projs else None
        mode = getattr(proj, "end_sound_mode", "windchime") if proj is not None else "windchime"
        data_dir = getattr(master, "data_dir", None) or resource_path("data")
        if mode == "custom":
            cust = getattr(proj, "custom_sound_path", "") if proj is not None else ""
            if not cust:
                return
            sound_path = cust if os.path.isabs(cust) else os.path.join(data_dir, cust)
        else:
            sound_path = os.path.join(data_dir, "sounds", self._SOUND_FILES.get(mode, "windchime.wav"))
        play_sound_file(sound_path)

    def update_time(self):
        if self.time_left > 0:
            self.time_left -= 1
        else:
            self.timer.stop()
            self.is_running = False
            self._advance_phase()
        self.update()

    def mousePressEvent(self, event):
        if event.button() == Qt.MouseButton.LeftButton:
            win = self.window()
            if win is not self and getattr(win, "_float_draggable", False):
                edge = win.resize_edge_at(event.position().toPoint())
                if edge:
                    win.begin_resize(edge, event.globalPosition().toPoint())
                    event.accept()
                    return
            self._press_pos = event.globalPosition().toPoint()
            self._last_drag_pos = self._press_pos
            self._drag_moved = False
            event.accept()
        elif event.button() == Qt.MouseButton.RightButton:
            win = self.window()
            if win is not self and getattr(win, "_float_draggable", False):
                win._show_menu(event.globalPosition().toPoint())
            else:
                self._show_menu(event.globalPosition().toPoint())
            event.accept()
        else:
            super().mousePressEvent(event)

    def mouseMoveEvent(self, event):
        win = self.window()
        if win is not self and getattr(win, "_resize_edge", None) and event.buttons() & Qt.MouseButton.LeftButton:
            win.apply_resize(event.globalPosition().toPoint())
            event.accept()
            return
        if self._press_pos is None or not (event.buttons() & Qt.MouseButton.LeftButton):
            if win is not self and getattr(win, "_float_draggable", False):
                edge = win.resize_edge_at(event.position().toPoint())
                if edge:
                    self.setCursor(win._EDGE_CURSORS.get(edge, Qt.CursorShape.ArrowCursor))
                else:
                    self.unsetCursor()
            super().mouseMoveEvent(event)
            return
        p = event.globalPosition().toPoint()
        if not self._drag_moved and (p - self._press_pos).manhattanLength() <= 6:
            return
        self._drag_moved = True
        win = self.window()
        if win is not None and win is not self and getattr(win, "_float_draggable", False):
            win.move(win.x() + p.x() - self._last_drag_pos.x(),
                     win.y() + p.y() - self._last_drag_pos.y())
            self._last_drag_pos = p
        else:
            super().mouseMoveEvent(event)

    def mouseReleaseEvent(self, event):
        if event.button() == Qt.MouseButton.LeftButton:
            win = self.window()
            if win is not self and getattr(win, "_resize_edge", None):
                win.end_resize()
                self.unsetCursor()
                self._press_pos = None
                self._drag_moved = False
                event.accept()
                return
            if self._press_pos is not None and not self._drag_moved:
                self.toggle_run()
            elif self._drag_moved:
                if win is not None and win is not self and getattr(win, "_float_draggable", False):
                    win.on_drag_finished()
            self._press_pos = None
            self._drag_moved = False
        else:
            super().mouseReleaseEvent(event)

    def mouseDoubleClickEvent(self, event):
        if event.button() == Qt.MouseButton.LeftButton:
            self.reset_phase()

    def context_actions(self, menu):
        master = getattr(self, "master", None) or getattr(self.window(), "master", None)
        theme = getattr(master, "theme", None) or get_system_theme()
        tc = get_theme_colors(theme)
        if not menu.styleSheet():
            apply_menu_style(menu, tc)
        act_toggle = menu.addAction(menu_vector_icon("pause" if self.is_running else "play", tc),
                                    "暂停" if self.is_running else "开始")
        act_reset = menu.addAction(menu_vector_icon("undo", tc), "重置当前阶段")
        act_skip = menu.addAction(menu_vector_icon("step", tc), "跳到下一阶段")
        menu.addSeparator()
        act_all = menu.addAction(menu_vector_icon("rotate", tc), "重置全部")
        return {act_toggle: self.toggle_run, act_reset: self.reset_phase,
                act_skip: self.skip_phase, act_all: self.reset_all}

    def _show_menu(self, pos):
        menu = QMenu(self)
        actions = self.context_actions(menu)
        chosen = menu.exec(pos)
        if chosen in actions:
            actions[chosen]()

    def enterEvent(self, event):
        self._hover = True
        self.update()
        super().enterEvent(event)

    def leaveEvent(self, event):
        self._hover = False
        self.update()
        super().leaveEvent(event)

    def wheelEvent(self, event):
        event.ignore()

    def _clock_text(self):
        mins, secs = divmod(max(0, int(self.time_left)), 60)
        if mins >= 100:
            hh, mm = divmod(mins, 60)
            return f"{hh}:{mm:02d}:{secs:02d}"
        return f"{mins:02d}:{secs:02d}"

    def _paint_clock_dial(self, painter, center, diameter, progress, accent, faint):
        radius = diameter / 2.0
        painter.save()
        painter.setBrush(Qt.BrushStyle.NoBrush)
        painter.setPen(QPen(faint, 1.0))
        painter.drawEllipse(center, radius, radius)
        painter.restore()
        if self.show_ticks:
            draw_dial_ticks(painter, center, radius - max(1.6, diameter * 0.018), 60, 5,
                            faint, faint, 0.0,
                            long_len=max(3.0, diameter * 0.050), width=1.0)
        draw_hairline_pointer(painter, center, 90.0 - 360.0 * progress,
                              radius * 0.60, radius * 0.82, accent,
                              max(1.5, diameter * 0.010), max(1.6, diameter * 0.016))

    def _paint_pomo_block(self, painter, rect, clock, accent, faint, fg):
        if rect.width() < 26 or rect.height() < 20:
            return
        dots = max(2, int(self.cycles))
        done = dots if self.phase == "long" else min(self.cycle_done, dots)
        seg_h = max(1.5, rect.height() * 0.030)
        seg_gap = max(2.5, rect.height() * 0.045)
        seg_w = max(4.0, rect.height() * 0.105)
        total_w = dots * seg_w + (dots - 1) * seg_gap
        limit = rect.width() * 0.86
        if total_w > limit:
            seg_w = max(2.0, (limit - (dots - 1) * seg_gap) / dots)
            total_w = dots * seg_w + (dots - 1) * seg_gap
        sx = rect.center().x() - total_w / 2.0
        painter.setPen(Qt.PenStyle.NoPen)
        for i in range(dots):
            painter.setBrush(QBrush(accent if i < done else faint))
            painter.drawRoundedRect(QRectF(sx + i * (seg_w + seg_gap), rect.top(), seg_w, seg_h),
                                    seg_h / 2.0, seg_h / 2.0)

        label = self._PHASE_LABELS.get(self.phase, "")
        chip_size = max(7, int(rect.height() * 0.115))
        chip_font = QFont("Microsoft YaHei")
        chip_font.setPixelSize(chip_size)
        chip_font.setBold(True)
        chip_font.setLetterSpacing(QFont.SpacingType.AbsoluteSpacing, max(0.8, chip_size * 0.26))
        chip_w = QFontMetricsF(chip_font).horizontalAdvance(label)
        chip_h = chip_size * 1.5
        dot_r = max(1.6, chip_size * 0.26)
        chip_gap = max(3.5, chip_size * 0.50)
        chip_cy = rect.bottom() - chip_h / 2.0

        band_top = rect.top() + seg_h + max(4.0, rect.height() * 0.06)
        band_h = (rect.bottom() - chip_h - max(3.0, rect.height() * 0.04)) - band_top
        if band_h < 10:
            return
        num_font, _nfm = fit_num_font(clock, rect.width() * 0.94, band_h * 0.92,
                                      max(10, int(band_h * 1.10)), min_size=8)
        painter.setFont(num_font)
        painter.setPen(fg)
        painter.drawText(QRectF(rect.left(), band_top, rect.width(), band_h),
                         Qt.AlignmentFlag.AlignCenter, clock)

        chip_total = dot_r * 2 + chip_gap + chip_w
        x0 = rect.center().x() - chip_total / 2.0
        dot_c = QPointF(x0 + dot_r, chip_cy)
        painter.save()
        if self.is_running:
            painter.setPen(Qt.PenStyle.NoPen)
            painter.setBrush(QBrush(accent))
            painter.drawEllipse(dot_c, dot_r, dot_r)
        elif self.time_left < self.total_time:
            painter.setBrush(Qt.BrushStyle.NoBrush)
            painter.setPen(QPen(accent, max(1.0, dot_r * 0.5)))
            painter.drawEllipse(dot_c, dot_r * 0.66, dot_r * 0.66)
        else:
            idle = QColor(accent)
            idle.setAlpha(110)
            painter.setPen(Qt.PenStyle.NoPen)
            painter.setBrush(QBrush(idle))
            painter.drawEllipse(dot_c, dot_r, dot_r)
        painter.restore()
        painter.setFont(chip_font)
        painter.setPen(accent)
        painter.drawText(QRectF(x0 + dot_r * 2 + chip_gap, chip_cy - chip_h / 2.0, chip_w + 4, chip_h),
                         Qt.AlignmentFlag.AlignLeft | Qt.AlignmentFlag.AlignVCenter, label)

    def set_theme_mode(self, mode):
        self.theme_mode = mode if mode in ("system", "dark", "light", "auto") else "system"
        self.update()

    def paintEvent(self, event):
        w, h = self.width(), self.height()
        if w < 8 or h < 8:
            return
        painter = QPainter(self)
        painter.setRenderHint(QPainter.RenderHint.Antialiasing)
        painter.setRenderHint(QPainter.RenderHint.TextAntialiasing)

        dark = widget_is_dark(self)
        fg = QColor(255, 255, 255) if dark else QColor(GLASS_INK)
        faint = QColor(255, 255, 255, 44) if dark else QColor(27, 36, 48, 34)

        progress = (self.time_left / self.total_time) if self.total_time > 0 else 0.0
        progress = max(0.0, min(1.0, progress))
        c1, c2 = pomo_phase_colors(self.palette_name, self.phase)
        if self._hover:
            c1 = QColor(c1).lighter(112).name()
            c2 = QColor(c2).lighter(112).name()
        accent = QColor(c2 if dark else c1)
        clock = self._clock_text()

        short = float(min(w, h))
        margin = max(2.0, short * 0.02)
        aspect = w / float(h)
        gap = short * 0.06
        num_font_probe = QFontMetricsF(QFont("Microsoft YaHei", 20))
        need_w = num_font_probe.horizontalAdvance(clock) * 1.35
        min_block_w = max(48.0, need_w)
        min_block_h = 40.0
        diameter = short - margin * 2.0
        center = QPointF(w / 2.0, h / 2.0)
        block = QRectF(0.0, h / 2.0 - diameter * 0.22, float(w), diameter * 0.46)

        if aspect >= 1.30:
            room = w - margin * 2.0 - gap - (h - margin * 2.0)
            if room >= min_block_w:
                diameter = h - margin * 2.0
                center = QPointF(margin + diameter / 2.0, h / 2.0)
                bx = margin + diameter + gap
                block = QRectF(bx, margin, w - bx - margin, h - margin * 2.0)
        elif aspect <= 0.78:
            room = h - margin * 2.0 - short * 0.05 - (w - margin * 2.0)
            if room >= min_block_h:
                diameter = w - margin * 2.0
                center = QPointF(w / 2.0, margin + diameter / 2.0)
                by = margin + diameter + short * 0.05
                block = QRectF(margin, by, w - margin * 2.0, h - by - margin)

        self._paint_clock_dial(painter, center, diameter, progress, accent, faint)
        self._paint_pomo_block(painter, block, clock, accent, faint, fg)


class PomodoroBarWidget(PomodoroWidget):
    _float_draggable = False

    def __init__(self, parent=None, work_mins=25, break_mins=5, long_break_mins=15, cycles=4):
        super().__init__(parent, work_mins, break_mins, long_break_mins, cycles)
        self.setMinimumSize(132, 72)

    def sizeHint(self):
        return QSize(272, 120)

    def paintEvent(self, event):
        w, h = self.width(), self.height()
        if w < 24 or h < 20:
            return
        painter = QPainter(self)
        painter.setRenderHint(QPainter.RenderHint.Antialiasing)
        painter.setRenderHint(QPainter.RenderHint.TextAntialiasing)

        pal = flat_palette(widget_is_dark(self))
        paint_flat_card(painter, QRectF(0.5, 0.5, w - 1.0, h - 1.0), min(18.0, h * 0.18), pal)

        progress = (self.time_left / self.total_time) if self.total_time > 0 else 0.0
        progress = max(0.0, min(1.0, progress))
        c1, c2 = pomo_phase_colors(self.palette_name, self.phase)
        if self._hover:
            c1 = QColor(c1).lighter(112).name()
            c2 = QColor(c2).lighter(112).name()
        accent = QColor(c2 if pal["dark"] else c1)

        pad = max(8.0, min(w * 0.048, h * 0.105))
        chip_h = max(13.0, min(h * 0.21, 22.0))
        chip_font = QFont("Microsoft YaHei")
        chip_font.setPixelSize(max(9, int(chip_h * 0.60)))
        chip_font.setBold(True)
        chip_font.setLetterSpacing(QFont.SpacingType.AbsoluteSpacing, max(0.6, chip_h * 0.10))
        label = self._PHASE_LABELS.get(self.phase, "")
        cfm = QFontMetricsF(chip_font)
        chip_w = cfm.horizontalAdvance(label) + chip_h * 0.92
        chip_rect = QRectF(pad, pad, chip_w, chip_h)
        if self.is_running:
            painter.setPen(Qt.PenStyle.NoPen)
            painter.setBrush(QBrush(accent))
            painter.drawRoundedRect(chip_rect, chip_h * 0.28, chip_h * 0.28)
            chip_ink = flat_contrast_ink(accent)
        elif self.time_left < self.total_time:
            painter.setBrush(Qt.BrushStyle.NoBrush)
            painter.setPen(QPen(accent, max(1.2, chip_h * 0.09)))
            painter.drawRoundedRect(chip_rect.adjusted(0.7, 0.7, -0.7, -0.7),
                                    chip_h * 0.26, chip_h * 0.26)
            chip_ink = accent
        else:
            painter.setPen(Qt.PenStyle.NoPen)
            painter.setBrush(QBrush(pal["track"]))
            painter.drawRoundedRect(chip_rect, chip_h * 0.28, chip_h * 0.28)
            chip_ink = pal["dim"]
        painter.setFont(chip_font)
        painter.setPen(chip_ink)
        painter.drawText(chip_rect, Qt.AlignmentFlag.AlignCenter, label)

        dots = max(2, int(self.cycles))
        done = dots if self.phase == "long" else min(self.cycle_done, dots)
        sq = max(5.0, chip_h * 0.44)
        gap = max(3.0, sq * 0.55)
        total_w = dots * sq + (dots - 1) * gap
        avail = w - pad * 2.0 - chip_w - max(8.0, w * 0.05)
        if total_w > avail and dots > 1:
            sq = max(2.5, (avail - (dots - 1) * gap) / dots)
            total_w = dots * sq + (dots - 1) * gap
        sx = w - pad - total_w
        painter.setPen(Qt.PenStyle.NoPen)
        for i in range(dots):
            painter.setBrush(QBrush(accent if i < done else pal["track"]))
            painter.drawRoundedRect(QRectF(sx + i * (sq + gap), pad + (chip_h - sq) / 2.0, sq, sq),
                                    sq * 0.22, sq * 0.22)

        mins, secs = divmod(max(0, int(self.time_left)), 60)
        if mins >= 100:
            hh, mm = divmod(mins, 60)
            head, tail = f"{hh}:{mm:02d}", f"{secs:02d}"
        else:
            head, tail = f"{mins:02d}", f"{secs:02d}"

        track_h = max(3.0, min(h * 0.058, 7.0))
        axis_h = max(8.0, h * 0.092)
        track_cy = h - pad - axis_h - max(2.0, h * 0.028) - track_h / 2.0
        num_top = pad + chip_h + max(2.0, h * 0.026)
        num_bottom = track_cy - track_h * 0.5 - max(2.0, h * 0.026)
        num_h = num_bottom - num_top
        num_w = w - pad * 2.0

        if num_h >= 10 and num_w >= 24:
            num_font, nfm = fit_num_font(head + ":" + tail, num_w, num_h,
                                         max(12, int(num_h * 1.02)), min_size=9)
            num_size = num_font.pixelSize()
            col_font = make_num_font(pixel_size=max(8, int(num_size * 0.64)), bold=False)
            cfm2 = QFontMetricsF(col_font)
            hw = nfm.horizontalAdvance(head)
            tw2 = nfm.horizontalAdvance(tail)
            cw = cfm2.horizontalAdvance(":")
            col_pad = max(1.5, num_size * 0.07)
            span = hw + tw2 + cw + col_pad * 2.0
            if span > num_w:
                num_size = max(9, int(num_size * num_w / span))
                num_font = make_num_font(pixel_size=num_size)
                nfm = QFontMetricsF(num_font)
                col_font = make_num_font(pixel_size=max(8, int(num_size * 0.64)), bold=False)
                cfm2 = QFontMetricsF(col_font)
                hw = nfm.horizontalAdvance(head)
                tw2 = nfm.horizontalAdvance(tail)
                cw = cfm2.horizontalAdvance(":")
                col_pad = max(1.5, num_size * 0.07)
            num_cy = (num_top + num_bottom) / 2.0
            base = num_cy + (nfm.ascent() - nfm.descent()) / 2.0
            colon_base = num_cy + (cfm2.ascent() - cfm2.descent()) / 2.0
            painter.setFont(num_font)
            painter.setPen(pal["ink"])
            painter.drawText(QPointF(pad, base), head)
            painter.setFont(col_font)
            painter.setPen(pal["dim"])
            painter.drawText(QPointF(pad + hw + col_pad, colon_base), ":")
            painter.setFont(num_font)
            painter.setPen(pal["ink"])
            painter.drawText(QPointF(pad + hw + col_pad + cw + col_pad, base), tail)

        track_x0 = pad
        track_x1 = w - pad
        span_w = max(10.0, track_x1 - track_x0)
        painter.setPen(Qt.PenStyle.NoPen)
        painter.setBrush(QBrush(pal["track"]))
        painter.drawRoundedRect(QRectF(track_x0, track_cy - track_h / 2.0, span_w, track_h),
                                track_h / 2.0, track_h / 2.0)
        played = track_x0 + span_w * progress
        fill_w = played - track_x0
        if fill_w > 0.5:
            painter.setBrush(QBrush(accent))
            painter.drawRoundedRect(QRectF(track_x0, track_cy - track_h / 2.0, fill_w, track_h),
                                    track_h / 2.0, track_h / 2.0)
        painter.setBrush(Qt.BrushStyle.NoBrush)
        painter.setPen(QPen(pal["line"], 1.0))
        for i in (1, 2, 3):
            qx = track_x0 + span_w * i / 4.0
            painter.drawLine(QPointF(qx, track_cy - track_h), QPointF(qx, track_cy + track_h))
        play_h = track_h * 2.2
        painter.setPen(QPen(accent, max(1.6, track_h * 0.34), Qt.PenStyle.SolidLine, Qt.PenCapStyle.FlatCap))
        painter.drawLine(QPointF(played, track_cy - play_h / 2.0), QPointF(played, track_cy + play_h / 2.0))

        total_secs = max(0, int(self.total_time))
        tmins, tsecs = divmod(total_secs, 60)
        if tmins >= 100:
            thh, tmm = divmod(tmins, 60)
            total_text = f"{thh}:{tmm:02d}:{tsecs:02d}"
        else:
            total_text = f"{tmins:02d}:{tsecs:02d}"
        axis_font = make_num_font(pixel_size=max(7, int(axis_h * 0.88)), bold=False)
        painter.setFont(axis_font)
        painter.setPen(pal["dim"])
        axis_y = track_cy + track_h * 0.5 + max(1.0, h * 0.014)
        painter.drawText(QRectF(track_x0, axis_y, span_w * 0.5, axis_h),
                         Qt.AlignmentFlag.AlignLeft | Qt.AlignmentFlag.AlignVCenter, "00:00")
        painter.drawText(QRectF(track_x0 + span_w * 0.5, axis_y, span_w * 0.5, axis_h),
                         Qt.AlignmentFlag.AlignRight | Qt.AlignmentFlag.AlignVCenter, total_text)


class GlassWeatherWidget(QWidget):
    theme_mode = "system"

    def set_theme_mode(self, mode):
        self.theme_mode = mode if mode in ("system", "dark", "light", "auto") else "system"
        self.update()

    def __init__(self, parent=None, master=None):
        super().__init__(parent)
        self.setMinimumSize(104, 108)
        self.setAttribute(Qt.WidgetAttribute.WA_TranslucentBackground, True)
        self.setMouseTracking(True)
        self.master = master
        self._detail_rect = QRectF()
        self._temp = "--"
        self._unit = "°"
        self._emoji = "🌤️"
        self._icon_code = None
        self._icon_day = True
        self._kind = "partly_day"
        self._city = ""
        self._desc = "获取天气中"
        self._ring_color = QColor(120, 180, 240, 220)
        self._fetcher = None
        self._timer = QTimer(self)
        self._timer.setInterval(30 * 60 * 1000)
        self._timer.timeout.connect(self.refresh)
        self._init_fetcher()

    def sizeHint(self):
        return QSize(168, 176)

    def _init_fetcher(self):
        if self.master is None:
            return
        try:
            self._fetcher = WeatherFetcher(
                api_provider=getattr(self.master, 'weather_provider', 'qweather'),
                custom_url_template=getattr(self.master, 'custom_weather_url', ''),
                qweather_api_key=getattr(self.master, 'qweather_api_key', ''),
                qweather_api_host=getattr(self.master, 'qweather_api_host', ''))
            self._fetcher.weather_updated.connect(self.setText)
            self._timer.start()
            QTimer.singleShot(3000, self.refresh)
        except Exception as e:
            log_message(f"独立天气控件初始化失败: {e}", "ERROR")

    def refresh(self):
        if self._fetcher is None or self.master is None:
            return
        try:
            city = self.master._effective_weather_city(getattr(self.master, 'weather_city', ''))
            self._fetcher.fetch(city)
        except Exception as e:
            log_message(f"独立天气控件刷新失败: {e}", "ERROR")

    def setText(self, text):
        raw = text or ""
        plain = re.sub(r'<[^>]+>', '', raw).strip()
        code, day = wx_icon_from_text(raw)
        img_match = re.search(r'src="file:///([^"]+)"', raw)
        if img_match:
            code = code or os.path.splitext(os.path.basename(img_match.group(1).replace("/", os.sep)))[0]
        self._icon_code = code
        if day is None:
            code_int = _wx_code_int(code)
            self._icon_day = (not wx_is_night_code(code_int)) if code_int is not None else (6 <= datetime.now().hour < 19)
        else:
            self._icon_day = day
        emoji_match = re.match(r'^([\U0001F300-\U0001FAFF\u2600-\u27BF]\ufe0f?)', plain)
        if emoji_match:
            self._emoji = emoji_match.group(1)
            plain = plain[emoji_match.end():].strip()
        plain = plain.replace("\ufe0f", "").replace("\u200d", "").strip()
        head = plain.split(" · ")[0].strip()
        m = re.match(r'^(\S+)\s+(?:(\d{1,2}:\d{2})\s+)?(\S+)\s+(-?\d+)\s*°C?', head)
        if m:
            self._city = m.group(1)
            self._desc = m.group(3)
            self._temp = m.group(4)
        else:
            tm = re.search(r'(-?\d+)\s*°', plain)
            if tm:
                self._temp = tm.group(1)
            tokens = [t for t in re.split(r'[·\s]+', head) if t]
            self._desc = tokens[0] if tokens else plain
        if self._fetcher is not None and getattr(self._fetcher, 'city_name', ''):
            self._city = self._fetcher.city_name
        self._kind = weather_icon_kind(self._icon_code, self._desc, self._icon_day)
        self._ring_color = _weather_ring_color(self._desc, self._icon_day)
        self.update()

    def paintEvent(self, event):
        w, h = self.width(), self.height()
        if w < 24 or h < 24:
            return
        painter = QPainter(self)
        painter.setRenderHint(QPainter.RenderHint.Antialiasing)
        painter.setRenderHint(QPainter.RenderHint.SmoothPixmapTransform)
        painter.setRenderHint(QPainter.RenderHint.TextAntialiasing)

        pal = flat_palette(widget_is_dark(self))
        paint_flat_card(painter, QRectF(0.5, 0.5, w - 1.0, h - 1.0), min(18.0, min(w, h) * 0.13), pal)

        rc = self._ring_color
        accent = QColor(rc.red(), rc.green(), rc.blue())
        if not pal["dark"]:
            for _ in range(8):
                if 0.299 * accent.red() + 0.587 * accent.green() + 0.114 * accent.blue() <= 150:
                    break
                accent = accent.darker(116)

        pad = max(9.0, min(w, h) * 0.085)
        bar_w = max(2.5, w * 0.024)
        bar_h = max(12.0, h * 0.30)
        painter.setPen(Qt.PenStyle.NoPen)
        painter.setBrush(QBrush(accent))
        painter.drawRoundedRect(QRectF(pad, pad, bar_w, bar_h), bar_w * 0.5, bar_w * 0.5)

        chip_h = max(16.0, min(w, h) * 0.105)
        chip_w = max(36.0, chip_h * 2.4)
        self._detail_rect = QRectF(w - pad - chip_w, pad - min(3.0, h * 0.02), chip_w, chip_h)
        text_x = pad + bar_w + max(6.0, w * 0.055)
        text_w = max(20.0, self._detail_rect.left() - text_x - max(6.0, w * 0.03))
        city_font = QFont("Microsoft YaHei")
        city_font.setPixelSize(max(9, int(min(h * 0.105, w * 0.135))))
        city_font.setBold(True)
        city_font.setLetterSpacing(QFont.SpacingType.AbsoluteSpacing, 1.1)
        cfm = QFontMetricsF(city_font)
        desc_font = QFont("Microsoft YaHei")
        desc_font.setPixelSize(max(8, int(min(h * 0.082, w * 0.108))))
        dfm = QFontMetricsF(desc_font)
        block_h = cfm.height() + dfm.height() * 1.10
        top = pad + max(0.0, (bar_h - block_h) / 2.0)
        painter.setFont(city_font)
        painter.setPen(pal["ink"])
        painter.drawText(QRectF(text_x, top, text_w, cfm.height()),
                         Qt.AlignmentFlag.AlignLeft | Qt.AlignmentFlag.AlignVCenter, self._city)
        painter.setFont(desc_font)
        painter.setPen(pal["dim"])
        painter.drawText(QRectF(text_x, top + cfm.height() * 1.10, text_w, dfm.height()),
                         Qt.AlignmentFlag.AlignLeft | Qt.AlignmentFlag.AlignVCenter, self._desc)

        chip_r = chip_h * 0.5
        painter.setPen(Qt.PenStyle.NoPen)
        painter.setBrush(QColor(255, 255, 255, 30) if pal["dark"] else QColor(20, 23, 31, 20))
        painter.drawRoundedRect(self._detail_rect, chip_r, chip_r)
        painter.setBrush(Qt.BrushStyle.NoBrush)
        painter.setPen(QPen(pal["line"], 1.0))
        painter.drawRoundedRect(self._detail_rect.adjusted(0.5, 0.5, -0.5, -0.5),
                                max(0.0, chip_r - 0.5), max(0.0, chip_r - 0.5))
        chip_font = QFont("Microsoft YaHei")
        chip_font.setPixelSize(max(9, int(chip_h * 0.46)))
        painter.setFont(chip_font)
        painter.setPen(pal["ink"])
        painter.drawText(self._detail_rect, Qt.AlignmentFlag.AlignCenter, "详细")

        zone_top = pad + bar_h + max(5.0, h * 0.055)
        zone_h = max(16.0, h - pad - zone_top)
        sep_y = zone_top - max(2.0, h * 0.022)
        painter.setBrush(Qt.BrushStyle.NoBrush)
        painter.setPen(QPen(pal["line"], 1.0))
        painter.drawLine(QPointF(pad, sep_y), QPointF(w - pad, sep_y))

        icon_side = max(20.0, min(w * 0.32, zone_h * 0.92))
        icon_x = w - pad - icon_side
        zone_cy = zone_top + zone_h / 2.0
        icon_box = min(icon_side, zone_h)
        draw_weather_icon(painter,
                          QRectF(icon_x + (icon_side - icon_box) / 2.0, zone_cy - icon_box / 2.0,
                                 icon_box, icon_box),
                          self._kind, pal["dark"])

        num_avail = max(24.0, icon_x - pad - max(4.0, w * 0.03))
        num_font, nfm = fit_num_font(self._temp, num_avail * 0.74, zone_h * 0.98,
                                     max(16, int(zone_h * 1.02)), min_size=12)
        num_size = num_font.pixelSize()
        unit_font = QFont("Microsoft YaHei")
        unit_font.setPixelSize(max(10, int(num_size * 0.42)))
        unit_font.setBold(True)
        ufm = QFontMetricsF(unit_font)
        tw = nfm.horizontalAdvance(self._temp)
        uw = ufm.horizontalAdvance(self._unit)
        gap = max(1.0, num_size * 0.06)
        span = tw + gap + uw
        if span > num_avail:
            num_size = max(12, int(num_size * num_avail / span))
            num_font = make_num_font(pixel_size=num_size)
            nfm = QFontMetricsF(num_font)
            unit_font.setPixelSize(max(10, int(num_size * 0.42)))
            ufm = QFontMetricsF(unit_font)
            tw = nfm.horizontalAdvance(self._temp)
            uw = ufm.horizontalAdvance(self._unit)
            gap = max(1.0, num_size * 0.06)
        base = zone_cy + (nfm.ascent() - nfm.descent()) / 2.0
        painter.setFont(num_font)
        painter.setPen(pal["ink"])
        painter.drawText(QPointF(pad, base), self._temp)
        painter.setFont(unit_font)
        painter.setPen(accent)
        painter.drawText(QPointF(pad + tw + gap, base - num_size * 0.30), self._unit)

    def mousePressEvent(self, event):
        if event.button() == Qt.MouseButton.LeftButton and self._detail_rect.contains(event.position()):
            self._open_detail()
            event.accept()
            return
        super().mousePressEvent(event)

    def mouseMoveEvent(self, event):
        if self._detail_rect.contains(event.position()):
            self.setCursor(Qt.CursorShape.PointingHandCursor)
            event.accept()
            return
        self.unsetCursor()
        super().mouseMoveEvent(event)

    def _open_detail(self):
        f = self._fetcher
        if f is None:
            return
        lat, lon = getattr(f, "lat", None), getattr(f, "lon", None)
        if lat is None or lon is None:
            self.refresh()
            return
        master = self.master
        provider = getattr(master, "weather_provider", "") or getattr(f, "api_provider", "qweather")
        key = (getattr(master, "qweather_api_key", "") or getattr(f, "qweather_api_key", "") or "").strip()
        host = (getattr(master, "qweather_api_host", "") or getattr(f, "qweather_api_host", "") or "").strip()
        city = getattr(f, "city_name", "") or self._city
        addr = getattr(f, "detailed_address", "") or city
        dlg = WeatherForecastDialog(lat, lon, city, self, provider=provider,
                                    qw_key=key, qw_host=host, detailed_address=addr)
        dlg.exec()


