class SkinThemeDialog(QDialog):
    def __init__(self, master, project, window, skin, parent=None):
        super().__init__(parent)
        self.master = master
        self.project = project
        self.window = window
        self.skin = skin
        variants = skin_variants(skin)
        dark = is_system_dark()
        self.dark = dark
        self.mode = project.skin_mode if getattr(project, "skin_id", "") == skin.get("id") else skin.get("default_mode", "manual")
        if self.mode not in ("manual", "auto", "system"):
            self.mode = "manual"
        tc = _skin_theme(dark)
        self.setWindowTitle("倒计时·DJS - 深浅色切换方式")
        self.resize(580, 500)
        self.setStyleSheet(_skin_qss(dark))
        root = QVBoxLayout(self)
        root.setContentsMargins(26, 22, 26, 18)
        root.setSpacing(6)
        title = QLabel("深浅色切换方式")
        title.setFont(QFont("Microsoft YaHei", 13, QFont.Weight.Bold))
        title.setStyleSheet(f"color: {tc['text_color']};")
        root.addWidget(title)
        sub = QLabel(f"{skin.get('name', '皮肤')} · 适用于本项目的外观")
        sub.setFont(QFont("Microsoft YaHei", 9))
        sub.setStyleSheet(f"color: {tc['secondary_text']};")
        root.addWidget(sub)
        root.addSpacing(14)
        if self.master.skin_sun_service.configured() and self.master.skin_sun_service.times_today() is None:
            self.master.skin_sun_service.ensure_async()
        opts = [
            ("用户自行切换", "在皮肤页手动选择浅色或深色，切换立即生效。", "", "manual"),
            ("根据日落时间", "日落 20 分钟后切换为深色，次日日出恢复浅色。",
             self.master.skin_sun_service.status_text(), "auto"),
            ("跟随系统主题", "与 Windows 的应用主题保持一致，系统切换时自动跟随。", "", "system"),
        ]
        self.options = []
        for text, desc, extra, mode in opts:
            card = SkinModeOption(dark, text, desc, extra, self.mode == mode)
            card.clicked.connect(lambda m=mode: self._select(m))
            self.options.append((mode, card))
            root.addWidget(card)
            root.addSpacing(8)
        tip = QLabel("未配置天气 API 或获取日落失败时，按 20:00–08:00 自动切换。")
        tip.setFont(QFont("Microsoft YaHei", 7))
        tip.setStyleSheet(f"color: {tc['secondary_text']};")
        tip.setWordWrap(True)
        root.addWidget(tip)
        root.addStretch()
        line = QFrame()
        line.setFixedHeight(1)
        line.setStyleSheet(f"background: {tc['border_color']};")
        root.addWidget(line)
        btns = QHBoxLayout()
        btns.setContentsMargins(0, 12, 0, 0)
        btns.addStretch()
        cancel = QPushButton("取消")
        cancel.setMinimumHeight(32)
        cancel.setCursor(Qt.CursorShape.PointingHandCursor)
        cancel.clicked.connect(self.reject)
        save = QPushButton("保存")
        save.setProperty("primary", True)
        save.setMinimumHeight(32)
        save.setMinimumWidth(88)
        save.setCursor(Qt.CursorShape.PointingHandCursor)
        save.clicked.connect(self._save)
        btns.addWidget(cancel)
        btns.addWidget(save)
        root.addLayout(btns)

    def _select(self, mode):
        self.mode = mode
        for m, card in self.options:
            card.set_selected(m == mode)

    def _save(self):
        skin = find_skin(self.master, self.project.skin_id) or self.skin
        variant = getattr(self.project, "skin_variant", "") or resolved_skin_variant(self.project)
        self.master.apply_skin_to_project(self.project, skin, self.window,
                                          variant=variant if self.mode == "manual" else None,
                                          mode=self.mode, persist=True)
        self.accept()


