        super().__init__(parent)
        self.master = master
        self.project = project
        self.window = window
        self.variants = variants
        self.designed = designed
        self.variant = variant
        self.edit_skin = edit_skin
        self.saved_skin = None
        dark = is_system_dark()
        self.dark = dark
        tc = _skin_theme(dark)
        self.setWindowTitle("倒计时·DJS - " + ("编辑皮肤" if edit_skin else "保存皮肤"))
        self.resize(800, 470)
