        body.setSpacing(22)
        left = QVBoxLayout()
        left.setSpacing(8)
        cap = QLabel("预览")
        cap.setFont(QFont("Microsoft YaHei", 8, QFont.Weight.Bold))
        cap.setStyleSheet(f"color: {tc['secondary_text']};")
        left.addWidget(cap)
        previews = QHBoxLayout()
        previews.setSpacing(12)
        for key, name in (("light", "浅色"), ("dark", "深色")):
            col = QVBoxLayout()
            col.setSpacing(6)
            if self.designed.get(key):
                card = SkinPreviewWidget(project, variants.get(key) or {})
                card.setFixedSize(170, 104)
