        left.addLayout(previews)
        left.addStretch()
        body.addLayout(left, 1)
        body.addSpacing(4)
        divider = QFrame()
        divider.setFixedWidth(1)
        divider.setStyleSheet(f"background: {tc['border_color']};")
        body.addWidget(divider)
