        self.name_edit = QLineEdit((edit_skin or {}).get("name") or "我的皮肤")
        self.name_edit.setMinimumHeight(32)
        form.addWidget(self.name_edit)
        info_text = "覆盖保存原皮肤 · 未编辑的深浅色外观保持不变" if edit_skin else "基于当前外观创建 · 元素布局与配色会随皮肤保存"
        info = QLabel(info_text)
        info.setFont(QFont("Microsoft YaHei", 7))
        info.setStyleSheet(f"color: {tc['secondary_text']};")
        form.addWidget(info)
