        self.info_name.setFont(QFont("Microsoft YaHei", 9, QFont.Weight.Bold))
        self.info_status = QLabel("")
        self.info_status.setFont(QFont("Microsoft YaHei", 7))
        info_col = QVBoxLayout()
        info_col.setSpacing(2)
        info_col.addWidget(self.info_name)
        info_col.addWidget(self.info_status)
        bl.addLayout(info_col)
        bl.addSpacing(18)
        self.seg_holder = QWidget()
        self.seg_layout = QHBoxLayout(self.seg_holder)
        self.seg_layout.setContentsMargins(0, 0, 0, 0)
        self.seg_layout.setSpacing(2)
        self.seg_holder.setVisible(False)
        bl.addWidget(self.seg_holder)
        bl.addStretch()
        self.btn_edit = QPushButton("编辑")
        self.btn_edit.setIcon(app_icon('fa5s.pen', color=self.tc["text_color"]))
        self.btn_edit.setMinimumHeight(32)
