        self.btn_delete = QPushButton("删除")
        self.btn_delete.setIcon(app_icon('fa5s.trash-alt', color=self.tc["danger_icon"]))
        self.btn_delete.setMinimumHeight(32)
        self.btn_delete.setMinimumWidth(72)
        self.btn_delete.setCursor(Qt.CursorShape.PointingHandCursor)
        self.btn_delete.clicked.connect(self.delete_selected)
        self.btn_mode = QPushButton("深浅色切换…")
        self.btn_mode.setIcon(app_icon('fa5s.adjust', color=self.tc["text_color"]))
        self.btn_mode.setMinimumHeight(32)
        self.btn_mode.setCursor(Qt.CursorShape.PointingHandCursor)
        self.btn_mode.clicked.connect(self.open_mode_dialog)
        self.btn_apply = QPushButton("应用")
        self.btn_apply.setIcon(app_icon('fa5s.check', color=self.tc["btn_text"]))
        self.btn_apply.setProperty("primary", True)
        self.btn_apply.setMinimumHeight(32)
        self.btn_apply.setMinimumWidth(88)
