            f" border-radius: 6px; padding: 8px 18px; font-weight: bold; }}"
            f"QPushButton:disabled {{ background-color: {self.pal['border']}; color: {self.pal['secondary']}; }}"
            f"QPushButton:hover:enabled {{ background-color: #FB7185; }}"
