    def _refresh_captcha(self):
        self.captcha.refresh()
        self.input.clear()
        self.input.setFocus()

    def _start_captcha(self):
        self.stack.setCurrentIndex(1)
        self.input.setFocus()
        QTimer.singleShot(80, self._enter_english_mode)

    def _back_to_warning(self):
        self._restore_ime()
        self.stack.setCurrentIndex(0)

    def _enter_english_mode(self):
        if self._ime_context is not None or self._hkl_saved is not None:
            return
        try:
            kernel32 = ctypes.WinDLL("kernel32")
            user32 = ctypes.WinDLL("user32", use_last_error=True)
            user32.GetKeyboardLayout.restype = ctypes.c_void_p
            user32.GetKeyboardLayout.argtypes = [ctypes.c_uint32]
            user32.LoadKeyboardLayoutW.restype = ctypes.c_void_p
            user32.LoadKeyboardLayoutW.argtypes = [ctypes.c_wchar_p, ctypes.c_uint32]
            user32.ActivateKeyboardLayout.restype = ctypes.c_void_p
            user32.ActivateKeyboardLayout.argtypes = [ctypes.c_void_p, ctypes.c_uint32]
            user32.GetWindowThreadProcessId.restype = ctypes.c_uint32
            user32.GetWindowThreadProcessId.argtypes = [ctypes.c_void_p, ctypes.c_void_p]
            hwnd = ctypes.c_void_p(int(self.input.winId()))
            tid = user32.GetWindowThreadProcessId(hwnd, None)
            if not tid:
                tid = kernel32.GetCurrentThreadId()
            old_hkl = user32.GetKeyboardLayout(tid)
            en_hkl = user32.LoadKeyboardLayoutW("00000409", 0)
            if old_hkl and en_hkl and user32.ActivateKeyboardLayout(en_hkl, 0):
                self._user32 = user32
                self._hkl_saved = old_hkl
                self._hkl_en = en_hkl
                return
        except Exception:
            self._user32 = None
            self._hkl_saved = None
            self._hkl_en = None
        self._enter_imm_english()

    def _enter_imm_english(self):
        try:
            imm = ctypes.WinDLL("imm32")
            imm.ImmGetContext.restype = ctypes.c_void_p
            imm.ImmGetContext.argtypes = [ctypes.c_void_p]
            imm.ImmGetConversionStatus.restype = ctypes.c_bool
            imm.ImmGetConversionStatus.argtypes = [
                ctypes.c_void_p, ctypes.POINTER(ctypes.c_uint32), ctypes.POINTER(ctypes.c_uint32)]
            imm.ImmSetConversionStatus.restype = ctypes.c_bool
            imm.ImmSetConversionStatus.argtypes = [ctypes.c_void_p, ctypes.c_uint32, ctypes.c_uint32]
            imm.ImmReleaseContext.restype = ctypes.c_bool
            imm.ImmReleaseContext.argtypes = [ctypes.c_void_p, ctypes.c_void_p]
            hwnd = ctypes.c_void_p(int(self.input.winId()))
            context = imm.ImmGetContext(hwnd)
            if not context:
                return
            conv = ctypes.c_uint32()
            sentence = ctypes.c_uint32()
            if not imm.ImmGetConversionStatus(context, ctypes.byref(conv), ctypes.byref(sentence)):
                imm.ImmReleaseContext(hwnd, context)
                return
            self._imm = imm
            self._ime_hwnd = hwnd
            self._ime_context = context
            self._ime_saved = (conv.value, sentence.value)
            imm.ImmSetConversionStatus(context, (conv.value & ~0x0003) | 0x0008, sentence.value)
        except Exception:
            self._imm = None
            self._ime_hwnd = None
            self._ime_context = None
            self._ime_saved = None

    def _restore_ime(self):
        if self._hkl_saved is not None:
            try:
                self._user32.ActivateKeyboardLayout(self._hkl_saved, 0)
            except Exception:
                pass
            self._user32 = None
            self._hkl_saved = None
            self._hkl_en = None
        context = self._ime_context
        if context is None:
            return
        try:
            if self._ime_saved is not None:
                self._imm.ImmSetConversionStatus(context, self._ime_saved[0], self._ime_saved[1])
            self._imm.ImmReleaseContext(self._ime_hwnd, context)
        except Exception:
            pass
        finally:
            self._imm = None
            self._ime_hwnd = None
            self._ime_context = None
            self._ime_saved = None

    def done(self, result):
        self._restore_ime()
        super().done(result)

    def _on_input(self, text):
        self.err_label.setText("")
        self.btn_verify.setEnabled(len(text.strip()) == len(self.captcha.code))

    def _tick(self):
        if self.remaining > 0:
            self.remaining -= 1
            self.progress.setValue(int((10 - self.remaining) / 10 * 100))
            if self.remaining == 0:
                self.progress.setValue(100)
                self.count_label.hide()
                self.progress.hide()
                self.btn_continue.setEnabled(True)
            else:
                self.count_label.setText(f"{self.remaining} 秒")

    def _verify(self):
        if not self.btn_verify.isEnabled():
            return
        if self.input.text().strip().upper() == self.captcha.code:
            self.timer.stop()
            self._restore_ime()
            self.verified.emit()
            self.stack.setCurrentIndex(2)
            return
        self.failures += 1
        if self.failures >= 3:
            QTimer.singleShot(0, self.reject)
            return
        self._refresh_captcha()
        self.err_label.setText(f"验证码错误，还可尝试 {3 - self.failures} 次")
        self._shake()

    def _shake(self):
        anim = QPropertyAnimation(self.input, b"pos", self)
        base = self.input.pos()
        anim.setDuration(260)
        anim.setStartValue(base)
        seq = [QPoint(base.x() - 6, base.y()), QPoint(base.x() + 6, base.y()),
               QPoint(base.x() - 4, base.y()), QPoint(base.x(), base.y())]
        for i, pt in enumerate(seq):
            anim.setKeyValueAt((i + 1) / len(seq), pt)
        anim.setEasingCurve(QEasingCurve.Type.OutQuad)
        anim.start()
        self._shake_anim = anim

    def apply_palette(self):
        pal = self.pal
        self.setStyleSheet(f"""
            QDialog {{ background-color: {pal['bg']}; }}
            QPushButton {{ background-color: {pal['input']}; color: {pal['text']};
                border: 1px solid {pal['border']}; border-radius: 6px; padding: 7px 16px; }}
            QPushButton:hover {{ border-color: {pal['blue']}; }}
            QLineEdit {{ background-color: {pal['input']}; color: {pal['text']};
                border: 1px solid {pal['border']}; border-radius: 6px; padding: 6px 10px;
                font-size: 16px; letter-spacing: 6px; }}
            QLineEdit:focus {{ border-color: {pal['blue']}; }}
        """)


