def _security_icon(name, color, size=18):
    if not HAS_QT_SVG:
        return QIcon()
    body = _SECURITY_ICON_BODIES.get(name, _SECURITY_ICON_BODIES["shield"])
    svg = ('<svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" '
           'fill="none" stroke="{color}" stroke-width="1.8" stroke-linecap="round" '
           'stroke-linejoin="round">' + body + '</svg>').replace("{color}", color or "#888888")
    try:
        renderer = QSvgRenderer(QByteArray(svg.encode("utf-8")))
        dpr = 2.0
        pix = QPixmap(int(size * dpr), int(size * dpr))
        pix.fill(Qt.GlobalColor.transparent)
        painter = QPainter(pix)
        renderer.render(painter)
        painter.end()
        pix.setDevicePixelRatio(dpr)
        return QIcon(pix)
    except Exception:
        return QIcon()


class PermissionRequestDialog(QDialog):
    LEVEL_VALUES = ("once", "session", "permanent", "deny")

    def __init__(self, manager, plugin, flags, app, mode="ondemand", parent=None,
                 origin="explicit"):
        super().__init__(parent)
        self.manager = manager
        self.plugin = plugin
        self.app = app
        self.mode = mode
        self.origin = origin
        values = (tuple(value for value in self.LEVEL_VALUES if value != "once")
                  if mode == "baseline" else self.LEVEL_VALUES)
        self.levels = [(value, perm_level_text(value)) for value in values]
        self.tc = get_theme_colors(getattr(app, 'theme', None))
        self.flags = [permission_flag_from(f) for f in flags]
        self.result_data = {"ok": False, "level": "none", "code": "cancelled"}
        self.setWindowTitle(tr("perm_dialog_title_ondemand") if mode == "ondemand"
                            else tr("perm_dialog_title_baseline"))
        self.setModal(True)
        self.setMinimumWidth(560)
        self.setMinimumHeight(480)
        self.resize(620, 620)
        self.setStyleSheet(
            f"QDialog {{ background-color: {self.tc['panel_bg']}; }}"
            + _theme_scrollbar_qss(self.tc, bool(getattr(getattr(app, 'theme', None), 'is_dark', False)))
            + _perm_secondary_qss(self.tc))
        self._build()
        self._fit_height()

    def _chip(self, risk):
        color = {1: self.tc.get('success', '#22C55E'),
                 2: self.tc.get('warning', '#F59E0B'),
                 3: self.tc.get('danger', '#EF4444')}.get(risk, self.tc.get('secondary_text'))
        chip = QLabel(perm_risk_text(risk))
        chip.setStyleSheet(
            f"QLabel {{ color: {color}; background-color: {self.tc['panel_bg']};"
            f" border: 1px solid {color}; border-radius: 8px; padding: 1px 8px;"
            f" font-size: 10px; font-weight: bold; }}")
        return chip

    def _build(self):
        root = QVBoxLayout(self)
        root.setContentsMargins(20, 18, 20, 16)
        root.setSpacing(10)
        name = getattr(self.plugin, 'name', '') or getattr(self.plugin, 'filename', '')
        if self.mode == "baseline":
            title_text = perm_text("perm_dialog_baseline_title", name=name)
            subtitle_text = tr("perm_dialog_baseline_subtitle")
        else:
            spec = self.manager.permission_spec(self.plugin, self.flags[0])
            title_text = spec.get("title") or perm_text("perm_dialog_ondemand_title", name=name)
            subtitle_text = tr("perm_dialog_ondemand_subtitle")
        title = QLabel(title_text)
        title.setWordWrap(True)
        title.setStyleSheet(f"font-size: 16px; font-weight: bold; color: {self.tc['text_color']};")
        root.addWidget(title)
        sub = QLabel(subtitle_text)
        sub.setWordWrap(True)
        sub.setStyleSheet(f"font-size: 11px; color: {self.tc['secondary_text']};")
        root.addWidget(sub)
        if getattr(self.plugin, 'permission_legacy', False):
            legacy = QLabel(tr("perm_dialog_legacy_notice"))
            legacy.setWordWrap(True)
            legacy.setStyleSheet(
                f"QLabel {{ color: {self.tc.get('warning', '#F59E0B')};"
                f" background-color: {self.tc['panel_bg']}; border-radius: 6px; padding: 6px 8px;"
                f" font-size: 11px; }}")
            root.addWidget(legacy)
        body = QScrollArea()
        body.setWidgetResizable(True)
        body.setMinimumHeight(80)
        body.setStyleSheet(
            f"QScrollArea {{ border: 1px solid {self.tc['border_color']};"
            f" border-radius: 8px; background-color: {self.tc['panel_bg']}; }}")
        inner = QWidget()
        inner.setStyleSheet(f"background-color: {self.tc['panel_bg']};")
        lay = QVBoxLayout(inner)
        lay.setContentsMargins(10, 10, 10, 10)
        lay.setSpacing(8)
        for flag in self.flags:
            spec = self.manager.permission_spec(self.plugin, flag)
            risk = int(spec.get("risk", 3))
            row = QFrame()
            row.setObjectName("permRow")
            border = (f"border-left: 3px solid {self.tc['danger']};"
                      if risk >= 3 else "")
            row.setStyleSheet(
                f"QFrame#permRow {{ background-color: {self.tc['bg_color']};"
                f" border: 1px solid {self.tc['border_color']}; {border} border-radius: 7px; }}")
            row_lay = QVBoxLayout(row)
            row_lay.setContentsMargins(10, 8, 10, 8)
            row_lay.setSpacing(3)
            head = QHBoxLayout()
            head.setSpacing(6)
            label = QLabel(perm_feature(flag, spec))
            label.setWordWrap(True)
            label.setStyleSheet(
                f"QLabel {{ border: none; background: transparent; font-size: 12px;"
                f" font-weight: bold; color: {self.tc['text_color']}; }}")
            head.addWidget(label, 1)
            head.addWidget(self._chip(spec.get("risk", 3)))
            row_lay.addLayout(head)
            scope = QLabel(perm_scope(flag))
            scope.setWordWrap(True)
            scope.setStyleSheet(
                f"QLabel {{ border: none; background: transparent; font-size: 11px;"
                f" color: {self.tc['secondary_text']}; }}")
            row_lay.addWidget(scope)
            lay.addWidget(row)
        lay.addStretch()
        body.setWidget(inner)
        root.addWidget(body)
        reason_box = QFrame()
        reason_box.setObjectName("permReasonBox")
        reason_box.setStyleSheet(
            f"QFrame#permReasonBox {{ background-color: {self.tc['input_bg']};"
            f" border: 1px solid {self.tc['border_color']}; border-radius: 7px; }}")
        reason_lay = QVBoxLayout(reason_box)
        reason_lay.setContentsMargins(10, 8, 10, 8)
        reason_lay.setSpacing(3)
        reason_title = QLabel(tr("perm_reason_title"))
        reason_title.setStyleSheet(
            f"QLabel {{ border: none; background: transparent; font-size: 11px;"
            f" font-weight: bold; color: {self.tc['secondary_text']}; }}")
        reason_lay.addWidget(reason_title)
        reasons = []
        for flag in self.flags:
            spec = self.manager.permission_spec(self.plugin, flag)
            text = spec.get("reason") or tr("perm_reason_missing")
            if self.mode == "baseline":
                text = perm_text("perm_reason_line", feature=perm_feature(flag, spec), reason=text)
            reasons.append(text)
        reason = QTextEdit()
        reason.setReadOnly(True)
        reason.setPlainText("\n".join(reasons))
        reason.setWordWrapMode(QTextOption.WrapMode.WrapAtWordBoundaryOrAnywhere)
        reason.setFrameShape(QFrame.Shape.NoFrame)
        reason.setMinimumHeight(56)
        reason.setMaximumHeight(96)
        reason.setStyleSheet(
            f"QTextEdit {{ background: transparent; border: none;"
            f" font-size: 12px; color: {self.tc['text_color']}; }}")
        reason_lay.addWidget(reason)
        root.addWidget(reason_box)
        level_row = QHBoxLayout()
        level_row.setSpacing(8)
        level_label = QLabel(tr("perm_scope_title"))
        level_label.setStyleSheet(f"font-size: 11px; color: {self.tc['secondary_text']};")
        level_row.addWidget(level_label)
        self.level_combo = QComboBox()
        for value, text in self.levels:
            self.level_combo.addItem(text, value)
        self.level_combo.setCurrentIndex(0)
        self.level_combo.setMinimumWidth(150)
        self.level_combo.setStyleSheet(
            f"QComboBox {{ background-color: {self.tc['input_bg']}; color: {self.tc['text_color']};"
            f" border: 1px solid {self.tc['border_color']}; border-radius: 6px; padding: 4px 8px; }}")
        self.level_combo.currentIndexChanged.connect(self._sync_primary)
        level_row.addWidget(self.level_combo)
        if self.mode == "baseline":
            adjust = QPushButton(tr("perm_action_adjust"))
            adjust.setObjectName("permSecondary")
            adjust.setCursor(Qt.CursorShape.PointingHandCursor)
            adjust.clicked.connect(self._open_adjust)
            level_row.addWidget(adjust)
        level_row.addStretch()
        root.addLayout(level_row)
        hint = QLabel(tr("perm_dialog_hint"))
        hint.setWordWrap(True)
        hint.setStyleSheet(f"font-size: 10px; color: {self.tc['secondary_text']};")
        root.addWidget(hint)
        if self.mode == "baseline":
            footer = QLabel(tr("perm_footer_baseline"))
            footer.setWordWrap(True)
            footer.setStyleSheet(f"font-size: 10px; color: {self.tc['secondary_text']};")
            root.addWidget(footer)
        else:
            spec_now = self.manager.permission_spec(self.plugin, self.flags[0])
            feature = perm_feature(self.flags[0], spec_now)
            footer = QLabel(perm_text("perm_footer_ondemand", feature=feature))
            footer.setWordWrap(True)
            footer.setStyleSheet(f"font-size: 10px; color: {self.tc['secondary_text']};")
            root.addWidget(footer)
        btns = QHBoxLayout()
        btns.setSpacing(8)
        btns.addStretch()
        self.btn_reject = QPushButton(tr("perm_btn_reject"))
        self.btn_reject.setObjectName("permSecondary")
        self.btn_reject.setMinimumWidth(96)
        self.btn_reject.setCursor(Qt.CursorShape.PointingHandCursor)
        self.btn_reject.clicked.connect(self._reject)
        btns.addWidget(self.btn_reject)
        self.btn_primary = QPushButton(perm_level_text("session"))
        self.btn_primary.setMinimumWidth(132)
        self.btn_primary.setDefault(True)
        self.btn_primary.setCursor(Qt.CursorShape.PointingHandCursor)
        self.btn_primary.setStyleSheet(
            f"QPushButton {{ background-color: {self.tc['accent']}; color: {self.tc['btn_text']};"
            f" border: none; border-radius: 6px; padding: 8px 16px; font-weight: bold; }}"
            f"QPushButton:hover {{ background-color: {self.tc['blue']}; }}")
        self.btn_primary.clicked.connect(self._accept)
        btns.addWidget(self.btn_primary)
        root.addLayout(btns)
        self.setTabOrder(self.level_combo, self.btn_reject)
        self.setTabOrder(self.btn_reject, self.btn_primary)
        self._sync_primary()

    def _fit_height(self):
        lay = self.layout()
        if lay is not None:
            lay.activate()
        for label in self.findChildren(QLabel):
            if label.wordWrap() and label.width() > 0:
                need_label = label.heightForWidth(label.width())
                if need_label > 0:
                    label.setMinimumHeight(need_label)
        need = lay.heightForWidth(self.width()) if lay is not None and lay.hasHeightForWidth() else 0
        if need <= 0:
            need = lay.sizeHint().height() if lay is not None else self.sizeHint().height()
        screen = QApplication.primaryScreen()
        avail = screen.availableGeometry().height() if screen is not None else 760
        cap = max(420, min(760, avail - 32))
        self.setMaximumHeight(cap)
        self.resize(self.width(), min(cap, max(480, need)))

    def showEvent(self, event):
        super().showEvent(event)
        if not getattr(self, "_fitted_once", False):
            self._fitted_once = True
            self._fit_height()

    def _sync_primary(self):
        level = self.level_combo.currentData()
        self.btn_primary.setText(perm_level_text(level) if level in self.LEVEL_VALUES
                                 else perm_level_text("session"))

    def _reject(self):
        self.result_data = {"ok": False, "level": "none", "code": "rejected"}
        self.reject()

    def _accept(self):
        level = self.level_combo.currentData() or "session"
        self.result_data = {"ok": level != "deny", "level": level,
                            "code": "granted" if level != "deny" else "denied"}
        self.accept()

    def _open_adjust(self):
        manager = self.manager
        app = self.app
        adjust_levels = ([("none", perm_level_text("none"))] +
                         [item for item in self.levels if item[0] != "none"])
        dlg = PluginGrantDialog(manager, self.plugin, app, self,
                                flags=self.flags, levels=adjust_levels)
        if dlg.exec() == QDialog.DialogCode.Accepted:
            level = "none"
            for flag in self.flags:
                got = manager.grant_level(self.plugin, flag)
                if got in ("permanent", "session", "once", "deny"):
                    level = got
                    break
            self.result_data = {"ok": level in ("permanent", "session", "once"),
                                "level": level, "code": "adjusted"}
            self.accept()

    def keyPressEvent(self, event):
        if event.key() == Qt.Key.Key_Escape:
            self._reject()
            return
        super().keyPressEvent(event)


class PermissionAskCard(QWidget):
    finished = pyqtSignal(dict)
    LEVEL_VALUES = PermissionRequestDialog.LEVEL_VALUES

    def __init__(self, manager, plugin, flag, spec, app, origin="explicit"):
        super().__init__(None, Qt.WindowType.Tool | Qt.WindowType.FramelessWindowHint
                         | Qt.WindowType.WindowStaysOnTopHint)
        self.manager = manager
        self.plugin = plugin
        self.flag = permission_flag_from(flag)
        self.spec = spec
        self.app = app
        self.origin = origin
        self.tc = get_theme_colors(getattr(app, 'theme', None))
        self.result_data = {"ok": False, "level": "none", "code": "timeout"}
        self._remaining = 60
        self.setAttribute(Qt.WidgetAttribute.WA_ShowWithoutActivating, True)
        self.setAttribute(Qt.WidgetAttribute.WA_StyledBackground, True)
        self.setFocusPolicy(Qt.FocusPolicy.StrongFocus)
        self.setFixedWidth(430)
        self._build()
        self._timer = QTimer(self)
        self._timer.setInterval(100)
        self._timer.timeout.connect(self._tick)
        self._deadline = time.monotonic() + 60

    def _build(self):
        self.setStyleSheet(
            f"PermissionAskCard {{ background-color: {self.tc['panel_bg']};"
            f" border: 1px solid {self.tc['border_color']}; border-radius: 12px; }}"
            + _theme_scrollbar_qss(self.tc, bool(getattr(getattr(self.app, 'theme', None), 'is_dark', False)))
            + _perm_secondary_qss(self.tc))
        root = QVBoxLayout(self)
        root.setContentsMargins(14, 12, 14, 12)
        root.setSpacing(8)
        head = QHBoxLayout()
        head.setSpacing(6)
        title = QLabel(self.spec.get("title") or tr("perm_card_title"))
        title.setWordWrap(True)
        title.setStyleSheet(f"font-size: 13px; font-weight: bold; color: {self.tc['text_color']};")
        head.addWidget(title, 1)
        risk = QLabel(perm_risk_text(self.spec.get("risk", 3)))
        color = {1: self.tc.get('success', '#22C55E'), 2: self.tc.get('warning', '#F59E0B'),
                 3: self.tc.get('danger', '#EF4444')}.get(self.spec.get("risk"), self.tc['secondary_text'])
        risk.setStyleSheet(
            f"QLabel {{ color: {color}; border: 1px solid {color}; border-radius: 8px;"
            f" padding: 1px 7px; font-size: 10px; font-weight: bold; }}")
        head.addWidget(risk)
        root.addLayout(head)
        source = QLabel(perm_text(
            "perm_card_source",
            name=getattr(self.plugin, 'name', '') or getattr(self.plugin, 'filename', '')))
        source.setWordWrap(True)
        source.setStyleSheet(f"font-size: 10px; color: {self.tc['secondary_text']};")
        root.addWidget(source)
        if self.origin == "intercept":
            blocked = QLabel(perm_text("perm_card_blocked", layer=layer_title("L2")))
            blocked.setWordWrap(True)
            blocked.setStyleSheet(
                f"QLabel {{ color: {self.tc.get('warning', '#F59E0B')};"
                f" background-color: {self.tc['input_bg']}; border-radius: 6px; padding: 6px 8px;"
                f" font-size: 11px; }}")
            root.addWidget(blocked)
        reason = QLabel(self.spec.get("reason") or tr("perm_reason_missing"))
        reason.setWordWrap(True)
        reason.setStyleSheet(
            f"QLabel {{ color: {self.tc['text_color']}; background-color: {self.tc['input_bg']};"
            f" border-radius: 6px; padding: 7px 8px; font-size: 11px; }}")
        root.addWidget(reason)
        scope = QLabel(perm_scope(self.flag))
        scope.setWordWrap(True)
        scope.setStyleSheet(f"font-size: 10px; color: {self.tc['secondary_text']};")
        root.addWidget(scope)
        self.level_combo = QComboBox()
        for value in self.LEVEL_VALUES:
            self.level_combo.addItem(perm_level_text(value), value)
        self.level_combo.setCurrentIndex(0)
        self.level_combo.setStyleSheet(
            f"QComboBox {{ background-color: {self.tc['input_bg']}; color: {self.tc['text_color']};"
            f" border: 1px solid {self.tc['border_color']}; border-radius: 6px; padding: 3px 8px; }}")
        self.level_combo.currentIndexChanged.connect(self._sync_primary)
        root.addWidget(self.level_combo)
        self.progress = QProgressBar()
        self.progress.setRange(0, 60)
        self.progress.setValue(60)
        self.progress.setTextVisible(False)
        self.progress.setFixedHeight(3)
        self.progress.setStyleSheet(
            f"QProgressBar {{ background-color: {self.tc['input_bg']}; border: none; border-radius: 1px; }}"
            f"QProgressBar::chunk {{ background-color: {self.tc['accent']}; border-radius: 1px; }}")
        root.addWidget(self.progress)
        btns = QHBoxLayout()
        btns.setSpacing(8)
        self.btn_reject = QPushButton(tr("perm_btn_keep_blocking") if self.origin == "intercept"
                                      else tr("perm_btn_disallow"))
        self.btn_reject.setObjectName("permSecondary")
        self.btn_reject.setCursor(Qt.CursorShape.PointingHandCursor)
        self.btn_reject.clicked.connect(self._reject)
        btns.addWidget(self.btn_reject)
        btns.addStretch()
        self.btn_primary = QPushButton(tr("perm_btn_allow_retry") if self.origin == "intercept"
                                       else tr("perm_level_once"))
        self.btn_primary.setDefault(False)
        self.btn_primary.setCursor(Qt.CursorShape.PointingHandCursor)
        self.btn_primary.setStyleSheet(
            f"QPushButton {{ background-color: {self.tc['accent']}; color: {self.tc['btn_text']};"
            f" border: none; border-radius: 6px; padding: 6px 12px; font-weight: bold; }}"
            f"QPushButton:hover {{ background-color: {self.tc['blue']}; }}")
        self.btn_primary.clicked.connect(self._accept)
        btns.addWidget(self.btn_primary)
        root.addLayout(btns)
        feature = perm_feature(self.flag, self.spec)
        if self.origin == "intercept":
            consequence = perm_text("perm_card_consequence_intercept", feature=feature)
        else:
            consequence = perm_text("perm_card_consequence_explicit", feature=feature)
        tail = QLabel(consequence)
        tail.setWordWrap(True)
        tail.setStyleSheet(f"font-size: 10px; color: {self.tc['secondary_text']};")
        root.addWidget(tail)
        more = QLabel(tr("perm_card_more"))
        more.setStyleSheet(f"font-size: 9px; color: {self.tc['secondary_text']};")
        root.addWidget(more)
        self.setTabOrder(self.level_combo, self.btn_reject)
        self.setTabOrder(self.btn_reject, self.btn_primary)

    def _sync_primary(self):
        level = self.level_combo.currentData()
        base = tr("perm_btn_allow_retry") if self.origin == "intercept" else perm_level_text("once")
        if level == "once":
            self.btn_primary.setText(base)
        elif level in ("session", "permanent", "deny"):
            self.btn_primary.setText(perm_level_text(level))
        else:
            self.btn_primary.setText(base)

    def show_card(self):
        screen = QApplication.primaryScreen()
        if screen is not None:
            area = screen.availableGeometry()
            self.adjustSize()
            x = area.right() - self.width() - 18
            y = area.bottom() - self.height() - 18
            self.move(max(area.left(), x), max(area.top(), y))
        self.show()
        self.raise_()
        self.activateWindow()
        self.setFocus()
        self._deadline = time.monotonic() + 60
        self._timer.start()

    def _tick(self):
        left = max(0, int(self._deadline - time.monotonic()))
        self.progress.setValue(left)
        if left <= 0:
            self._timer.stop()
            self._finish(False, "none", "timeout")

    def _finish(self, ok, level, code):
        if getattr(self, "_done", False):
            return
        self._done = True
        self._timer.stop()
        self.result_data = {"ok": bool(ok) and level in ("once", "session", "permanent"),
                            "level": level, "code": code}
        self.hide()
        self.finished.emit(self.result_data)
        self.deleteLater()

    def _reject(self):
        self._finish(False, "none", "rejected")

    def _accept(self):
        level = self.level_combo.currentData() or "once"
        self._finish(level != "deny", level,
                     "granted" if level != "deny" else "denied")

    def _open_advanced(self):
        manager = self.manager
        dlg = PermissionRequestDialog(manager, self.plugin, [self.flag], self.app,
                                      mode="ondemand", parent=None, origin=self.origin)
        code = dlg.exec()
        data = dlg.result_data
        if code == QDialog.DialogCode.Accepted or data.get("code") in ("rejected", "denied"):
            self._finish(data.get("ok"), data.get("level", "none"), data.get("code", "cancelled"))

    def keyPressEvent(self, event):
        if event.key() == Qt.Key.Key_Escape:
            self._reject()
            return
        if event.key() in (Qt.Key.Key_Return, Qt.Key.Key_Enter):
            self._open_advanced()
            return
        super().keyPressEvent(event)


class PluginGrantDialog(QDialog):

    LEVEL_VALUES = ("none", "once", "session", "permanent", "deny")

    def __init__(self, manager, plugin, app, parent=None, flags=None, levels=None):
        super().__init__(parent)
        self.manager = manager
        self.plugin = plugin
        self.app = app
        self.levels = list(levels) if levels else [
            (value, perm_level_text(value)) for value in self.LEVEL_VALUES]
        self.tc = get_theme_colors(getattr(app, 'theme', None))
        if flags is not None:
            wanted = {int(permission_flag_from(flag)) for flag in flags}
            self.flags = [int(flag) for flag, _label in _PERM_LABELS if int(flag) in wanted]
        else:
            self.flags = [int(flag) for flag, _label in _PERM_LABELS]
        self._labels = {int(flag): perm_label(flag) for flag, _label in _PERM_LABELS}
        self.setWindowTitle(perm_text("perm_grant_title",
                                      name=getattr(plugin, 'name', '')))
        self.setModal(True)
        self.resize(640, 560)
        self.setMinimumSize(560, 480)
        self.setStyleSheet(
            f"QDialog {{ background-color: {self.tc['panel_bg']}; }}"
            + _theme_scrollbar_qss(self.tc, bool(getattr(getattr(app, 'theme', None), 'is_dark', False)))
            + _perm_secondary_qss(self.tc))
        self.combos = {}
        self._build()
        self._load_levels()

    def _build(self):
        root = QVBoxLayout(self)
        root.setContentsMargins(18, 16, 18, 14)
        root.setSpacing(10)
        title = QLabel(perm_text("perm_grant_heading", name=getattr(self.plugin, 'name', '')))
        title.setStyleSheet(f"font-size: 16px; font-weight: bold; color: {self.tc['text_color']};")
        root.addWidget(title)
        hint = QLabel(tr("perm_grant_hint"))
        hint.setWordWrap(True)
        hint.setStyleSheet(f"font-size: 11px; color: {self.tc['secondary_text']};")
        root.addWidget(hint)
        body = QScrollArea()
        body.setWidgetResizable(True)
        body.setStyleSheet(f"QScrollArea {{ border: 1px solid {self.tc['border_color']};"
                           f" border-radius: 8px; background-color: {self.tc['panel_bg']}; }}")
        inner = QWidget()
        inner.setStyleSheet(f"background-color: {self.tc['panel_bg']};")
        grid = QGridLayout(inner)
        grid.setContentsMargins(12, 12, 12, 12)
        grid.setHorizontalSpacing(12)
        grid.setVerticalSpacing(8)
        declared = plugin_declared_permissions(self.plugin)
        for index, flag in enumerate(self.flags):
            label = self._labels.get(int(flag), str(flag))
            row = index // 2
            col = (index % 2) * 2
            is_declared = bool(declared & flag)
            if not is_declared:
                label = perm_text("perm_undeclared_suffix", label=label)
            name = QLabel(label)
            name.setStyleSheet(f"font-size: 12px; color: {self.tc['text_color']};")
            combo = QComboBox()
            for _value, text in self.levels:
                if _value == "none" and not is_declared:
                    text = tr("perm_undeclared")
                combo.addItem(text, _value)
            combo.setStyleSheet(
                f"QComboBox {{ background-color: {self.tc['input_bg']}; color: {self.tc['text_color']};"
                f" border: 1px solid {self.tc['border_color']}; border-radius: 6px; padding: 4px 8px; }}")
            self.combos[int(flag)] = combo
            grid.addWidget(name, row, col)
            grid.addWidget(combo, row, col + 1)
        body.setWidget(inner)
        root.addWidget(body, 1)
        btns = QHBoxLayout()
        btns.setSpacing(8)
        if any(value == "once" for value, _text in self.levels):
            btn_once = QPushButton(tr("perm_btn_allow_all_once"))
            btn_once.setObjectName("permSecondary")
            btn_once.setIcon(app_icon("fa5s.clock", self.tc.get('warning', self.tc['danger'])))
            btn_once.clicked.connect(lambda: self._set_all("once"))
            btns.addWidget(btn_once)
        btn_revoke = QPushButton(tr("perm_btn_revoke_all"))
        btn_revoke.setObjectName("permSecondary")
        btn_revoke.setIcon(app_icon("fa5s.undo", self.tc['secondary_text']))
        btn_revoke.clicked.connect(lambda: self._set_all("none"))
        btns.addWidget(btn_revoke)
        btns.addStretch()
        cancel = QPushButton(tr("cancel"))
        cancel.setObjectName("permSecondary")
        cancel.clicked.connect(self.reject)
        btns.addWidget(cancel)
        save = QPushButton(tr("save"))
        save.setObjectName("permPrimary")
        save.setIcon(app_icon("fa5s.check", self.tc['btn_text']))
        save.setDefault(True)
        save.clicked.connect(self._save)
        btns.addWidget(save)
        root.addLayout(btns)

    def _load_levels(self):
        for flag, combo in self.combos.items():
            level = self.manager.grant_level(self.plugin, PluginPermission(int(flag)))
            index = combo.findData(level)
            combo.setCurrentIndex(index if index >= 0 else 0)

    def _set_all(self, level):
        for combo in self.combos.values():
            combo.setCurrentIndex(combo.findData(level))

    def _save(self):
        levels = {}
        for flag, combo in self.combos.items():
            level = combo.currentData()
            if level is None:
                level = "none"
            levels[int(flag)] = level
        self.manager.set_grants_bulk(self.plugin, levels)
        try:
            self.app.append_sensitive_log(
                tr("perm_grant_log_target"), "修改授权级别",
                f"{getattr(self.plugin, 'name', '')} · " +
                "、".join(f"{self._labels.get(flag, str(flag))}={dict(self.levels)[level]}"
                         for flag, level in levels.items()
                         if level != "none"))
        except Exception:
            pass
        self.accept()


