        lay = QVBoxLayout(page)
        lay.setContentsMargins(6, 6, 6, 6)
        lay.setSpacing(6)
        hint = QLabel("风险等级（运行时）：按插件实际发生的危险操作动态评估，被拦截的操作按双倍计权；"
                      "出现执行命令／动态执行代码／注册表写入／删除文件等直接判为高风险，"
                      "加权总分 ≥12 高风险、≥6 中风险、≥2 低风险。\n"
                      "风险评估（静态）：解析插件代码内容，按危险模块导入、动态执行、系统调用、"
                      "内存与反序列化、代码混淆等加权，分 1–15 级，1 为无风险、15 为极高风险。")
        hint.setWordWrap(True)
        hint.setStyleSheet(f"color: {self.tc['secondary_text']}; font-size: 11px;")
        lay.addWidget(hint)
        bar = QHBoxLayout()
        bar.setSpacing(8)
        self.perm_view = QComboBox()
        self.perm_view.addItems(("按插件视角", "按权限视角"))
        self.perm_view.setMinimumHeight(30)
        self.perm_view.setStyleSheet(
            f"QComboBox {{ background-color: {self.tc['input_bg']}; color: {self.tc['text_color']};"
            f" border: 1px solid {self.tc['border_color']}; border-radius: 6px; padding: 4px 8px; }}")
        self.perm_view.currentIndexChanged.connect(lambda *_: self._fill_perm_tree())
        bar.addWidget(self.perm_view)
        self.perm_filter = QLineEdit()
        self.perm_filter.setPlaceholderText("筛选：插件 / 权限 / 授权级别")
        self.perm_filter.setClearButtonEnabled(True)
        self.perm_filter.setMinimumHeight(30)
        self.perm_filter.setStyleSheet(
            f"QLineEdit {{ background-color: {self.tc['input_bg']}; color: {self.tc['text_color']};"
            f" border: 1px solid {self.tc['border_color']}; border-radius: 6px; padding: 4px 8px; }}")
        self.perm_filter.textChanged.connect(lambda text: self._fill_perm_tree(text))
        bar.addWidget(self.perm_filter, 1)
        self.perm_sort = QComboBox()
        self.perm_sort.addItems(("名称升序", "授权数量", "名称降序"))
        self.perm_sort.setMinimumHeight(30)
        self.perm_sort.setStyleSheet(
            f"QComboBox {{ background-color: {self.tc['input_bg']}; color: {self.tc['text_color']};"
            f" border: 1px solid {self.tc['border_color']}; border-radius: 6px; padding: 4px 8px; }}")
