        bar.addWidget(self.perm_sort)
        lay.addLayout(bar)
        self.perm_tree = self._event_tree(("插件名称", "版本", "状态", "已放行权限", "授权级别明细", "风险评估"))
        self.perm_tree.itemDoubleClicked.connect(lambda *_: self._open_permission_editor())
        lay.addWidget(self.perm_tree, 1)
        self.perm_empty = QLabel("暂无插件。把插件放入 plugins 目录后，这里会显示权限与授权级别。")
        self.perm_empty.setAlignment(Qt.AlignmentFlag.AlignCenter)
        self.perm_empty.setWordWrap(True)
        self.perm_empty.setStyleSheet(f"font-size: 12px; color: {self.tc['secondary_text']}; padding: 14px;")
